INSERT INTO `ghtweb_all_items` VALUES ('963', 'Orcish Arrowhead', null, 'Наконечник стрелы, которую используют Снайперы Орков Тунат на Говорящем Острове. Соберите эти наконечники и принесите их Мастеру Минии.', 'weapon_winged_spear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('964', 'Alberius\'s Letter', null, 'Письмо Альберия для Мастера Кобенделлу.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('965', 'Evergreen Amulet', null, 'Ожерелье с зеленым камнем. Оно должно быть у Вас, чтобы Вы могли получить слезы убитых Дриад.', 'accessary_near_forest_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('966', 'Dryad\'s Tears', null, 'Алмаз, содержащий в себе эссенцию души Дриады. Соберите 10 штук и отнесите их Мастеру Кобенделлу.', 'etc_crystal_ball_green_i00', '0');
