INSERT INTO `ghtweb_all_items` VALUES ('968', 'Karrod\'s Letter', null, 'Письмо, написанное Кузнецом Кэрродом. Отнесите его Служителю Бездны Кектинону в Храме Шилен.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('969', 'Cecktinon\'s First Voucher', null, 'Письмо от Служителя Бездны Кектинона. Отнесите его Магистру Харн в деревню.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('970', 'Cecktinon\'s Second Voucher', null, 'Записка от Магистра Харн. Отправляйтесь в Школу Темной Магии и соберите 10 Обломков Костей Скелетов.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('971', 'Soul Catcher', null, 'Предмет для ритуала вызова души умершего. Отнесите его Служителю Бездны Кектинону.', 'weapon_voodoo_doll_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('972', 'Preserving Oil', null, 'Масло, предотвращающее разложение трупа. Возьмите его на охоту на Зомби в Болотах.', 'etc_potion_clear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('973', 'Zombie Head', null, 'Голова Зомби, бывшего когда-то лесным эльфом. Отнесите ее Служителю Бездны Кектинону.', 'etc_skull_black_i00', '0');
