INSERT INTO `ghtweb_all_items` VALUES ('975', 'Blood Saber', null, 'Орихаруконовый меч в стиле Авеллы, изготовленный где-то на востоке.', 'weapon_broad_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('976', '1st Mark of Sentinel', null, 'Знак принадлежности к Эльфийским Часовым. Уничтожьте Тануки Крушителя Черепов и отчитайтесь Часовому Кенделлу.', 'item_system03', '0');
