INSERT INTO `ghtweb_all_items` VALUES ('1008', 'Harrys\'s 1st Receipt', null, 'Расписка, полученная Харрисом после заказа инструментов. Отнесите ее Кузнецу Альтрану.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1009', 'Harrys\'s 2nd Receipt', null, 'Расписка, полученная Харрисом после составления заказа на его инструменты. Соберите Осколки Голема, необходимые для создания инструмента.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1010', 'Golem Shard', null, 'Осколки камня, упавшие с тела Голема. Соберите 5 осколков и отнесите их Кузнецу Альтрану.', 'etc_lump_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1011', 'Tool Box', null, 'Ящик, содержащий изготовленные Кузнецом Альтраном инструменты. Отнесите его Магистру Харрису.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1012', 'Delivery List', null, 'Отнесите Тяжелый Деревянный Ящик Торговцу Джексону, Моток Ткани - Торговцу Сильвии, а Глиняный Горшок - Смотрителю Склада Ранту.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1013', 'Heavy Wood Box', null, 'Деревянный ящик, который необходимо отнести Торговцу Джексону, работающему в оружейном магазине.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1014', 'Cloth Bundle', null, 'Моток ткани, который необходимо отнести Торговцу Сильвии в бакалейную лавку.', 'etc_piece_of_cloth_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1015', 'Clay Pot', null, 'Глиняный горшок, который необходимо отнести Смотрителю Склада Ранту.', 'etc_oil_pot_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1016', 'Jackson\'s Receipt', null, 'Расписка Торговца Джексона о получении Деревянного Ящика. Отнесите ее Стражу Арнольду.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1017', 'Silvia\'s Receipt', null, 'Расписка Торговца Сильвии о получении Мотка Ткани. Отнесите ее Стражу Арнольду.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1018', 'Rant\'s Receipt', null, 'Расписка Смотрителя Склада Ранта о получении Глиняного Горшка. Отнесите ее Стражу Арнольду.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1019', 'Official Letter', null, 'Официальное письмо с просьбой о встрече, которую Лорд Глудио послал сэру Коллину Виндавуду. Отнесите его сэру Виндавуду.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1020', 'Flame Shard', null, 'Осколок огненной руды, полученный от Огненной Саламандры. Отдайте его Торговцу Катерине.', 'etc_crystal_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1021', 'Ice Shard', null, 'Осколок Камня Воды, полученный от Водяной Ундины. Отдайте его Торговцу Катерине.', 'etc_crystal_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1022', 'Lilith\'s Letter', null, 'Письмо Лилит, написанное возлюбленному, пропавшему тысячу лет назад. Узнайте для нее новости о ее возлюбленном.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1023', 'Theon\'s Diary', null, 'Дневник Теона со строками о его возлюбленной. Отнесите его Лилит.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1024', 'Adamantite Ore', null, 'Адамантитовая руда, привезенная из Грации. Соберите 20 штук этой руды и отнесите Смотрителю Склада Вильфорду.', 'etc_plate_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1025', 'Clay Tablet', null, 'Табличка демона Неркаса, прославляющая Белефа. Отнесите ее Верховному Жрецу Биотину.', 'etc_plate_glay_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1026', 'Silvery Spidersilk', null, 'Шелк паука. Отнесите его Торговцу Унорену в оружейный магазин.', 'etc_skein_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1027', 'Unoren\'s Receipt', null, 'Расписка Унорена. Отнесите ее Торговцу Кримису.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1028', 'Creamees\'s Ticket', null, 'Билет, выданный Складом. Отнесите его Смотрителю Склада Джулии.', 'etc_ticket_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1029', 'Nightshade Leaf', null, 'Лист белладонны. Отнесите его Нерупе.', 'etc_herb_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1030', 'Cracked Skull', null, 'Треснувший череп Темного Ужаса. Отнесите его Магистру Влэсти.', 'etc_skull_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1031', 'Perfect Skull', null, 'Череп Темного Ужаса. Отнесите его Магистру Влэсти.', 'etc_skull_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1032', 'Fox Fur', null, 'Мягкий мех, идеально подходит для создания нитей и пряжи. Отнесите его Кристел.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1033', 'Fox Fur Yarn', null, 'Пряжа из меха. Отнесите ее Смотрителю Склада Ролфе, чтобы он смог сделать волосы для куклы.', 'etc_skein_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1034', 'Maiden Doll', null, 'Кукла, напоминающая человеческую девушку. Отнесите ее Смотрителю Маяка Роксвеллу.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1035', 'Plague Dust', null, 'Пыль, полученная с останков Чумного Зомби. Отнесите ее Иерарху Астериосу.', 'etc_powder_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1036', 'Andellia\'s Letter', null, 'Письмо Анделии к ее сестре Талии с просьбой прислать ей плод Древа Жизни.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1037', 'Fruit of the Mother Tree', null, 'Плод, который Древо Жизни приносит раз в несколько лет. Отнесите его Анделии.', 'etc_fruit_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1038', 'Rumiel\'s 1st Poem', null, 'Свиток с первой поэмой Румиэля Лунный Свет. Соберите все четыре поэмы и отнесите их Часовому Стардену.', 'etc_piece_of_paper_black_i00', '0');
