INSERT INTO `ghtweb_all_items` VALUES ('1140', 'Rusted Bronze Sword', null, 'Старый бронзовый меч, используемый Скелетами Следопытами. Соберите 10 штук и отнесите Торговцу Симплону.', 'weapon_broad_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1141', 'Rusted Bronze Sword', null, 'Ржавый бронзовый меч, который, по словам Торговца Симплона, является Мечом Испытаний. Отнесите его Мастеру Аурону.', 'weapon_broad_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1142', 'Rusted Bronze Sword', null, 'Старый бронзовый меч, известный также как \"Меч Испытаний\". Используйте его для охоты на Ядовитых Пауков и Арахнидов Охотников.', 'weapon_broad_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1143', 'Simplon\'s Letter', null, 'Письмо Торговца Симплона. Отнесите его Мастеру Аурону.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1144', 'Venomous Spider\'s Leg', null, 'Отрезанная паучья лапка. Соберите 20 штук и отнесите Мастеру Аурону.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1145', 'Medallion of Warrior', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Воителей.', 'accessary_earing_of_protection_i00', '0');
