INSERT INTO `ghtweb_all_items` VALUES ('1150', 'Spellbook: Wind Strike', null, 'Книга, необходимая для изучения умения \"Удар Ветра\".', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1151', 'Spellbook: Self Heal', null, 'Книга, необходимая для изучения умения \"Самолечение\".', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1152', 'Spellbook: Heal', null, 'Книга, необходимая для изучения умения \"Лечение\". Профессии: Мистик, Светлый Мистик, Темный Мистик.Необходимый уровень: 7.', 'etc_spell_books_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1153', 'Jenna\'s Letter', null, 'Письмо Часового Дженны Мастеру Харанту.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1154', 'Sentry Blade', null, 'Меч из адамантита, недавно выданный всем Часовым.', 'weapon_bastard_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1155', 'Sentry Blade', null, 'Меч из адамантита, недавно выданный всем Часовым.', 'weapon_bastard_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1156', 'Sentry Blade', null, 'Меч из адамантита, недавно выданный всем Часовым.', 'weapon_bastard_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1157', 'Old Bronze Sword', null, 'Бронзовый меч, который раньше использовали Часовые. Отнесите его Часовому Дженне.', 'weapon_crimson_sword_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1158', 'Bone Fragment', null, 'Обломок кости скелета. Соберите 10 Обломков Костей и 3 Черепа Эльфа и отнесите их Унорену.', 'etc_piece_bone_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1159', 'Elf Skull', null, 'Череп Эльфа. Соберите 10 Обломков Костей и 3 Черепа Эльфа и отнесите их Унорену.', 'etc_skull_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1160', 'Dark Bezoar', null, 'Соберите 13 Темных Безоаров и отнесите их Часовому Нельсии.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1161', 'Sword of Ritual', null, 'Предмет для смены профессии. Чтобы стать Рыцарем, отдайте его Великому Мастеру в Гильдии Воинов.', 'weapon_flamberge_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1162', 'Coin of Lords', null, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'etc_coins_silver_i00', '0');
