INSERT INTO `ghtweb_all_items` VALUES ('1167', 'Coin of Lords', null, 'Золотая монета со знаком лорда Глудио. Чтобы пройти испытание, соберите, как минимум, 3 такие монеты.', 'etc_coins_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1168', 'Gludio Guard\'s 1st Badge', null, 'Знак принадлежности к Стражам. Согласно приказу Капитана Батиса, Вы должны охотиться на Людоедов Налетчиков.', 'etc_badge_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1169', 'Bugbear Necklace', null, 'Ожерелье, носимое Людоедами для использования заклинаний. Соберите 10 штук и принесите их Капитану Батису.', 'etc_totem_necklace_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1170', 'Einhasad\'s 1st Temple Badge', null, 'По просьбе Верховного Жреца Раймонда, отправляйтесь в Руины Отчаяния. Там Вы должны победить Духов Жрецов и собрать 12 Распятий Эйнхасад.', 'accessary_earing_of_holy_spirit_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1171', 'Einhasad\'s Crucifix', null, 'Святой символ Эйнхасад, богини Света. Соберите 12 штук и отнесите Верховному Жрецу Раймонду.', 'accessary_necklace_of_knowledge_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1172', 'Gludio Guard\'s 2nd Badge', null, 'Знак принадлежности к Стражам. По приказу Капитана Безика, Вы должны охотиться на гигантских пауков.', 'etc_badge_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1173', 'Venomous Spider\'s Leg', null, 'Отрезанная лапка Ядовитого Паука. Соберите 20 штук и отнесите их Капитану Безику.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1174', 'Einhasad\'s 2nd Temple Badge', null, 'По просьбе Верховной Жрицы Левиан, отправляйтесь на охоту на Ящеров Лангк. Убейте их и принесите доказательства этого.', 'accessary_earing_of_holy_spirit_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1175', 'Lizardman\'s Totem', null, 'Маленькая скульптура, которую Ящеры Лангк носят с собой. Соберите 20 штук и отнесите их Верховной Жрице Левиан.', 'etc_totem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1176', 'Gludio Guard\'s 3rd Badge', null, 'Знак принадлежности к Стражам. По приказу Капитана Гилберта, Вы должны охотиться на Гигантских Пауков.', 'etc_badge_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1177', 'Giant Spider\'s Husk', null, 'Кожа Гигантского Паука. Соберите 20 штук и отнесите Капитану Гилберту.', 'etc_leather_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1178', 'Einhasad\'s 3rd Temple Badge', null, 'По просьбе Верховного Жреца Биотина, отправляйтесь на охоту на Безмолвных Ужасов в Эльфийские Руины.', 'accessary_earing_of_holy_spirit_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1179', 'Skull of Silent Horror', null, 'Череп давно умершего Эльфа. Соберите 10 штук и отнесите их Верховному Жрецу Биотину.', 'etc_skull_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1180', 'Bezique\'s Letter', null, 'Письмо Капитана Безика, адресованное Нети. Найдите Нети в Глудине и отдайте ей это письмо.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1181', 'Neti\'s Bow', null, 'Любимый лук Нети, который она носила во время своих путешествий. Используйте его для охоты на скелетов в Руинах Страданий.', 'weapon_bow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1182', 'Neti\'s Dagger', null, 'Кинжал Нети, который она использовала во время своих путешествий. Используйте его для охоты на скелетов в Руинах Страданий.', 'weapon_knife_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1183', 'Spartoi\'s Bones', null, 'Кости нежити. Соберите 10 штук и отнесите их Нети.', 'etc_piece_bone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1184', 'Horseshoe of Light', null, 'Доказательство прохождения испытания Нети. Отнесите эту подкову Капитану Безику.', 'accessary_red_cresent_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1185', 'Most Wanted List', null, 'Здесь написано, что тот, кто покончит с Бандой Кошачьего Глаза и вернет украденные товары, будет вознагражден.', 'etc_recipe_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1186', 'Stolen Jewelry', null, 'Ювелирное украшение, украденное бандитами. Отнесите его Капитану Безику.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1187', 'Stolen Tomes', null, 'Очень редкая книга, украденная бандитами. Отнесите ее Капитану Безику.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1188', 'Stolen Ring', null, 'Очень дорогое кольцо, украденное бандитами. Отнесите его Капитану Безику.', 'accessary_ring_of_grace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1189', 'Stolen Necklace', null, 'Очень дорогое ожерелье, украденное бандитами. Отнесите его Капитану Безику.', 'accessary_necklace_of_blessing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1190', 'Bezique\'s Recommendation', null, 'Предмет для смены профессии. Чтобы стать Разбойником, отдайте это Великому Мастеру в Гильдии Воинов.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1191', '1st Letter of Order', null, 'Свидетельство, выданное Жрецом Зигонтом, разрешающее Вам собирать запретные книги. Держите его при себе, когда отправитесь на поиски этих книг.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1192', '2nd Letter of Order', null, 'Свидетельство, выданное Жрецом Зигонтом, указывающее, что его предъявитель относится к Храму. Отнесите его Лионелю для получения договора.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1193', 'Lionel\'s Book', null, 'Последняя книга Лионеля. Отнесите эту книгу Великому Магистру Галлинту в Школу Магов Айнховант.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1194', 'Book of Vivyan', null, 'Запрещенная книга, которую Симплон продал Вивиан. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1195', 'Book of Simplon', null, 'Запрещенная книга, найденная у Симплона. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1196', 'Book of Praga', null, 'Запрещенная книга, которую Симплон продал Прагу. Соберите пять запрещенных книг и отнесите их Жрецу Зигонту.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1197', 'Certificate of Gallint', null, 'Свидетельство, выданное Галлинтом за хранение запрещенных книг. Отнесите его Лионелю для получения договора.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1198', 'Pendant of Mother', null, 'Подвеска матери Стража Прага, которую он потерял в Руинах. Отнесите ее Прагу и получите запрещенную книгу.', 'accessary_blessed_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1199', 'Necklace of Mother', null, 'Ожерелье, использовавшееся для ношения подвески. Найдите его у зомби в Руинах Страданий и соберите целое ожерелье.', 'accessary_blessed_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1200', 'Lionel\'s Covenant', null, 'Лионель поклялся, что больше не будет писать запрещенных книг. Отдайте договор Жрецу Зигонту и получите Знак Доверия.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1201', 'Mark of Faith', null, 'Предмет для смены профессии. Отдайте его Верховному Жрецу в Храме, чтобы стать Клериком.', 'accessary_earing_of_wisdom_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1202', 'Sorius\'s Letter', null, 'Письмо Мастера Сориуса, которое необходимо передать Кузнецу Клуто в Глудине.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1203', 'Kluto Box', null, 'Коробка, которую Клуто просил передать Мастеру Сориусу.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1204', 'Elven Knight Brooch', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру в гильдии Воинов, чтобы стать Рыцарем.', 'accessary_elven_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1205', 'Topaz Piece', null, 'Осколок топаза, полученный при убийстве нежити в Руинах. Соберите 20 штук и отнесите их Мастеру Сориусу.', 'etc_jewel_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1206', 'Emerald Piece', null, 'Осколок изумруда, полученный при убийстве Новичков Гноллов. Соберите 20 штук и отнесите их Кузнецу Клуто.', 'etc_jewel_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1207', 'Reisa\'s Letter', null, 'Письмо Мастера Рейсы, адресованное Стражу Моретти.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1208', 'Prias\'s 1st Torn Letter', null, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1209', 'Prias\'s 2nd Torn Letter', null, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1210', 'Prias\'s 3rd Torn Letter', null, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1211', 'Prias\'s 4th Torn Letter', null, 'Обрывок письма, написанного Приасом. Соберите все четыре обрывка и отнесите их Стражу Моретти.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1212', 'Moretti\'s Herb', null, 'Растение, которое Страж Моретти попросил отдать Приасу.', 'etc_herb_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1213', 'Guard\'s Bow', null, 'Лук, отданный Стражем Моретти. Возможно, у него есть важное назначение.', 'weapon_bow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1214', 'Moretti\'s Letter', null, 'Срочное послание Стража Моретти Приасу.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1215', 'Prias\'s Letter', null, 'Ответ Приаса на письмо Стража Моретти. Отнесите его Моретти.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1216', 'Honorary Guard', null, 'Письмо Мастеру Рейсе, написанное Стражем Моретти. Отнесите его Мастеру Рейсе.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1217', 'Reisa\'s Recommendation', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Воинов, чтобы стать Разведчиком.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1218', 'Rosella\'s Letter', null, 'Письмо Розеллы Эльфийскому Магистру Гринис, в котором говорится о рубине, символе Огня.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1219', 'Red Down', null, 'Материал, необходимый для создания рубина с магическими свойствами. Соберите 5 штук и отнесите их Магистру Гринис для получения магического рубина.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1220', 'Magical Powers Ruby', null, 'Рубин, символизирующий Огонь. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1221', 'Pure Aquamarine', null, 'Аквамарин, символизирующий Воду. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'etc_jewel_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1222', 'Appetizing Apple', null, 'Красивое спелое яблоко. Отдайте его Талии, и она расскажет Вам про аквамарин.', 'etc_fruit_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1223', 'Gold Leaves', null, 'Листья, используемые как удобрение для Древа Жизни. Соберите 5 таких листьев, отдайте их Талии и получите аквамарин.', 'etc_leaf_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1224', 'Immortal Love', null, 'Книга, которую очень хочет получить Нортвинд. Если Вы отдадите ему эту книгу, он расскажет про аметист.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1225', 'Amethyst', null, 'Аметист, найденный у Трусливого Крысолюда. Отдайте 2 таких аметиста Нортвинду, чтобы получить Благородный Аметист.', 'etc_crystal_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1226', 'Nobility Amethyst', null, 'Аметист, символизирующий Ветер. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1227', 'Rosella\'s Recommendation', null, 'Рекомендация Розеллы. Покажите ее Варсаку, чтобы получить информацию о Благородном Хризолите.', 'item_normal131', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1228', 'Peridot', null, 'Хризолит, который можно получить при убийстве Скелета Снайпера. Соберите 3 штуки и отнесите их Варсаку. Взамен он даст Вам Благородный Хризолит.', 'item_normal16', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1229', 'Fertility Peridot', null, 'Хризолит, символизирующий Землю. Соберите все 4 камня стихий и отнесите их Розелле для получения разрешения на смену профессии.', 'etc_jewel_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1230', 'Eternity Diamond', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру в Гильдии Магов, чтобы стать Светлым Магом.', 'etc_jewel_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1231', 'Crystal Medallion', null, 'Ожерелье, выданное Жрецом Мануэлем. Отправляйтесь с ним в Гавань Глудина и найдите там девушку, творящую чудеса.', 'accessary_blue_diamond_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1232', 'Swindler\'s Money', null, 'Деньги Перрина, полученные при помощи мошенничества. Отдайте их Аллане.', 'etc_coins_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1233', 'Allana\'s Diary', null, 'Дневник с описанием фальшивых чудес. Покажите его Жрецу Мануэлю в качестве доказательства того, что Вы выполнили задание.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1234', 'Lizard Captain Order', null, 'Приказ Капитана Ящеров о похищении святой из пророчества.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1235', 'Leaf of Oracle', null, 'Предмет для смены профессии. Отдайте его Верховному Жрецу, чтобы стать Оракулом.', 'etc_leaf_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1236', 'Half of Diary', null, 'Половина дневника Алланы. Вы должны забрать деньги у Перрина и найти вторую часть этого дневника.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1237', 'Palus Talisman', null, 'Талисман с рунами, символизирующими озеро. Держите его при себе, пока будете охотиться на Ликантропов в Нейтральной Зоне.', 'accessary_earing_of_grace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1238', 'Lycanthrope Skull', null, 'Череп, добытый с мертвого Ликантропа. Соберите 13 штук и отнесите их Мастеру Вирджилу.', 'etc_skull_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1239', 'Virgil\'s Letter', null, 'Письмо Мастера Вирджила. Отнесите его Служителю Бездны Калинте в Глудин.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1240', 'Morte Talisman', null, 'Талисман с руной Морте, символом смерти. Возьмите его с собой на поиски гроба.', 'accessary_necklace_of_binding_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1241', 'Venomous Spider\'s Carapace', null, 'Твердый панцирь Ядовитого Паука. Отнесите его и 5 кусков Шелка Арахнида Охотника Служителю Бездны Калинте.', 'etc_bark_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1242', 'Arachnid Tracker Silk', null, 'Куски паутины Арахнида Охотника. Соберите 5 штук и отнесите их Служителю Бездны Калинте вместе с Панцирем Ядовитого Паука.', 'etc_skein_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1243', 'Coffin of Eternal Rest', null, 'Гроб для похорон Темных Рыцарей Отнесите его Мастеру Вирджилу.', 'shield_tower_shield_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1244', 'Gaze of Abyss', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Воинов, чтобы стать Темным Рыцарем.', 'etc_eyeball_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1245', 'Shilen\'s Call', null, 'Письмо Трискела. Отнесите его Ведьме Аркении к Церемониальному Алтарю.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1246', 'Arkenia\'s Letter', null, 'Письмо Аркении. Отнесите его Стражу Лейкану, чтобы узнать информацию о воре.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1247', 'Leikan\'s Note', null, 'Контракт, выданный Стражем Лейканом. Отправляйтесь на охоту на Зверей Лунного Камня и соберите их зубы.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1248', 'Moonstone Beast\'s Molar', null, 'Зуб, добытый у убитого Зверя Лунного Камня. Соберите 10 штук и отнесите их Стражу Лейкану.', 'etc_molar_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1249', 'Leikan\'s Knife', null, 'Нож, подаренный Лейканом в качестве благодарности. Говорят, он отлично действует против Кальпико.', 'weapon_ss09', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1250', 'Shilen\'s Tears', null, 'Магическая жидкость, украденная с Церемониального Алтаря. Отдайте ее Ведьме Аркении.', 'etc_lesser_potion_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1251', 'Arkenia\'s Recommendation', null, 'Знак благодарности от Аркении. Отнесите эту рекомендацию Трискелу.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1252', 'Iron Heart', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Ассасином.', 'accessary_earing_of_mana_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1253', 'Seed of Anger', null, 'Семя, полученное от Чаркерена. Отнесите его Ведьме Варике.', 'etc_bead_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1254', 'Seed of Despair', null, 'Семя, полученное от Ведьмы Варики. Вы должны достать все четыре семени, чтобы получить Украшение Тьмы.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1255', 'Seed of Horror', null, 'Семя, полученное от Анники. Отнесите его Ведьме Варике.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1256', 'Seed of Lunacy', null, 'Семя, полученное от безумца. Отнесите его Ведьме Варике.', 'etc_bead_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1257', 'Family\'s Remains', null, 'Останки семьи Чаркерена. Соберите 3 части и верните их Чаркерену.', 'etc_ashes_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1258', 'Varika\'s Liquor', null, 'Лекарство, которое Варика изготовила для сына герцогини. Отнесите его герцогине, чтобы получить Семя Отчаяния.', 'item_canuse47', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1259', 'Knee Bone', null, 'Коленная кость нежити, которую так долго искала Анника. Отдайте ее Аннике, чтобы получить Семя Ужаса.', 'etc_piece_bone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1260', 'Heart of Lunacy', null, 'Сердце превращенного в скелет. Соберите 3 штуки и отнесите их Аркении.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1261', 'Dark Jewel', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Темным Магом.', 'accessary_necklace_of_phantom_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1262', 'Sidra\'s Letter', null, 'Письмо, написанное Магистром Сидрой. Отнесите его Магистру Талботу.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1263', 'Blank Sheet', null, 'Пустой свиток. Возьмите его с собой во время охоты на Темных Суккубов, чтобы нанести на него кровавые руны.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1264', 'Bloody Rune', null, 'Руны, написанные кровью Темных Суккубов. Соберите 5 штук и отнесите Магистру Талботу.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1265', 'Garmiel\'s Book', null, 'Священная книга Гран Каина, бога Тьмы, написанная на эльфийском языке. Одна из тех двух книг, которые Вам нужно найти для Сидры.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1266', 'Prayer of Adonius', null, 'Молитвенник, который необходимо отнести Жрецу Адониусу в Глудин.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1267', 'Penitent\'s Mark', null, 'Знак искупления грехов своего обладателя. Держите его при себе во время охоты на Скелетов и Зомби в Руинах Отчаяния.', 'accessary_earing_of_holy_spirit_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1268', 'Ashen Bones', null, 'Кости Скелетов и Зомби из Руин Отчаяния. Соберите 10 штук и отнесите Жрецу Адониусу.', 'etc_piece_bone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1269', 'Andariel Book', null, 'Священная книга Эйнхасад, богини света, написанная на эльфийском языке. Одна из тех двух книг, которые Вам нужно найти для Сидры.', 'etc_spell_books_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1270', 'Orb of Abyss', null, 'Предмет для смены профессии. Отдайте его Великому Мастеру Гильдии Темных Эльфов, чтобы стать Оракулом Шилен.', 'etc_bead_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1271', 'Squire\'s Mark', null, 'Знак оруженосца. Вам надлежит встретиться с Капитанами Стражи и Верховными Жрецами в Глудио.', 'accessary_earing_of_wisdom_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1272', 'Greenis\'s Charm', null, 'Талисман на удачу, принадлежащий Гринис. Добудьте 5 трофеев с Пауков Хелицера и отнесите их Гринис.', 'accessary_aquastone_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1273', 'Sap of the Mother Tree', null, 'Сок Древа Жизни, который так любят Старшие Дриады. Соберите с них 5 золотых листьев и отнесите их Талии.', 'etc_potion_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1274', 'Lucky Potpourri', null, 'Счастливая смесь, принадлежащая Нортвинду. Отнесите ему 2 аметиста, добытых у Трусливых Крысолюдов.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1275', 'Tamil\'s Necklace', null, 'Ожерелье Тамил, которое необходимо показать Перрину.', 'etc_totem_necklace_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1276', 'Kluto\'s Memo', null, 'Записка от Кузнеца Клуто с просьбой убить Новичков Гноллов.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1277', 'Lucky Key', null, 'Бронзовый ключ. Держите его при себе, когда отправитесь на охоту на Зомби в районе болот. Соберите 3 комплекта останков и отнесите их Чаркерену.', 'etc_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1278', 'Candle', null, 'Свеча, освещающая дорогу во тьме. Соберите 2 Коленных Кости с нежити и отнесите их Аннике, чтобы получить Семя Ужаса.', 'etc_spirit_bullet_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1279', 'Hub Scent', null, 'Смесь из пряных трав. Соберите 3 Сердца Безумия со Скелетов Разведчиков и отнесите их Аркении.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1280', 'Map of Luster', null, 'Карта, полученная от Огненной Саламандры. Убивайте Крысолюдов, пока не получите Ключ Пламени. Отнесите его Саламандре в обмен на знак Огня.', 'etc_recipe_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1281', 'Key of Flame', null, 'Ключ, полученный с убитого Крысолюда. Отдайте его Саламандре в обмен на знак Огня.', 'etc_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1282', 'Flame Earring', null, 'Знак Огня, полученный от Огненной Саламандры. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'accessary_earing_of_mana_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1283', 'Broken Bronze Mirror', null, 'Зеркало Воздушного Сильфа. Отправляйтесь к Ящерам в Пустошь, заберите Перо Воздушного Сильфа и верните его владельцу.', 'etc_mirror_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1284', 'Wind Feather', null, 'Перо, принадлежащее Воздушному Сильфу, живущему у Пустоши. Верните его и получите Знак Ветра.', 'etc_feather_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1285', 'Wind Bangle', null, 'Знак Ветра, полученный от Воздушного Сильфа. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'accessary_blue_coral_ring_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1286', 'Rama\'s Diary', null, 'Убивайте Водных Пророков, пока не найдете 2 Сверкающих Камня. Отнесите их Водяной Ундине, чтобы получить знак Воды.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1287', 'Sparkle Pebble', null, 'Камень Водного Пророка. Отдайте его Водяной Ундине, чтобы получить знак Воды.', 'etc_crystal_ball_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1288', 'Water Necklace', null, 'Знак Воды, полученный от Водяной Ундины. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'accessary_necklace_of_assistance_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1289', 'Rusty Coin', null, 'Монета, полученная от Земляной Змеи. Соберите Красную Глину во время охоты на Рыжих Медведей и отдайте ее Земляной Змее в обмен на знак Земли.', 'etc_coins_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1290', 'Red Soil', null, 'Глина, полученная во время охоты на Рыжих Медведей. Отдайте его Земляной Змее в обмен на знак Земли.', 'etc_powder_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1291', 'Earth Ring', null, 'Знак Земли, полученный от Земляной Змеи. Соберите четыре знака стихий и отдайте их Парине, чтобы получить возможность сменить профессию.', 'accessary_ring_of_firefly_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1292', 'Bead of Season', null, 'Предмет для смены профессии. Отдайте его Верховному Жрецу в Храме, чтобы стать Магом.', 'etc_crystal_ball_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1293', 'Rusted Key', null, 'Ключ, открывающий замок на оковах Приаса. Отнесите его Приасу.', 'etc_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1294', 'Spellbook: Defense Aura', null, 'Книга, необходимая для изучения умения \"Аура Защиты\". Профессии: Светлый Воин, Темный Воин.Необходимый уровень: 5.', 'etc_spell_books_efighter_i00', '0');
