INSERT INTO `ghtweb_all_items` VALUES ('1541', 'Honey Khandar', null, 'Удивительный препарат, созданный из меда и экстракта хандара. Отнесите его Центуриону Накушину.', 'etc_potion_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1542', 'Bear Fur Cloak', null, 'Плащ, сделанный из меха гризли. Отнесите его Центуриону Накушину.', 'etc_piece_of_cloth_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1543', 'Bloody Axe', null, 'Топор, покрытый кровью диких животных. Говорят, он придает жизненные силы своему владельцу. Отнесите его Центуриону Накушину.', 'weapon_tomahawk_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1544', 'Ancestor Skull', null, 'Череп предка Урутуса. Говорят, он придает силы своему хозяину. Отнесите его Центуриону Накушину.', 'etc_skull_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1545', 'Spider Dust', null, 'Порошок из сушеных лапок ядовитого паука. Как ни странно, обладает очень освежающим запахом. Отнесите его Центуриону Накушину.', 'etc_powder_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1546', 'Deep Sea Orb', null, 'Жемчужина, найденная глубоко в море. Говорят, она помогает предсказывать будущее. Отнесите ее Центуриону Накушину.', 'etc_crystal_ball_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1547', 'Bolter\'s List', null, 'Список вещей, которые надо принести Больтеру из деревни.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1548', 'Mining Boots', null, 'Пара шахтерских сапог, полученных от Торговца Гариты. Отдайте их Шахтеру Больтеру.', 'armor_apprentices_shoes_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1549', 'Miner\'s Pick', null, 'Кирка Шахтера, полученная у Кузнеца Брюнона. Отдайте ее Шахтеру Больтеру.', 'weapon_guard_spear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1550', 'Boomboom Powder', null, 'Мешочек со взрывным порошком, полученный у Торговца Шари. Отнесите его Шахтеру Больтеру.', 'etc_powder_black_i00', '0');
