INSERT INTO `ghtweb_all_items` VALUES ('1559', 'Gouph\'s Contract', null, 'Контракт, заключенный Коллекционером Гуфом при покупке Звездного Алмаза у Торговца Рипа. Отнесите его Торговцу Рипу.', 'etc_letter_blue_i00', '0');
