INSERT INTO `ghtweb_all_items` VALUES ('1605', 'Gantaki\'s Letter of Recommendation', null, 'Рекомендательное письмо Гентаки. Обратитесь к Хранителю Портала Тамил и отнесите эту рекомендацию Префекту Касману в Глудин.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1606', 'Fig', null, 'Инжир, полученный от Префекта Касмана. Отдайте его Аватару Торуку.', 'etc_fruit_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1607', '4th Leather Pouch', null, 'Мешочек, полученный от Аватара Торуку. Убивайте воинов различных племен и соберите 12 их клыков.', 'etc_pouch_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1608', '4th Leather Pouch (Full)', null, 'Мешочек, наполненный клыками убитых воинов. Отдайте его Аватару Торуку.', 'etc_pouch_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1609', 'Vuku Orc Tusk', null, 'Клык, полученный при убийстве Орка Вуку. Необходимо собрать 3 штуки.', 'etc_molar_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1610', 'Ratman Fang', null, 'Коготь, полученный при убийстве Крысолюда Воина. Необходимо собрать 3 штуки.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1611', 'Langk Lizardman Tooth', null, 'Зуб, полученный при убийстве Ящера Лангк. Необходимо собрать 3 штуки.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1612', 'Felim Lizardman Tooth', null, 'Зуб, полученный при убийстве Ящера Фелим. Необходимо собрать 3 штуки.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1613', 'Iron Will Scroll', null, 'Второй свиток, содержащий тайну традиционного воинского искусства Орков, Кабарта.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1614', 'Toruku\'s Letter', null, 'Письмо Аватара Торуку. Отдайте его Префекту Касману.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1615', 'Khavatari Totem', null, 'Тотем того, кто достоин стать Монахом. Отдайте его Понтифику для смены профессии.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1616', 'Fire Charm', null, 'Оберег с описанием молитвы огня. Возьмите его и найдите 3 предмета, о которых говорил Татару.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1617', 'Kasha Bear Pelt', null, 'Шкура Медведя Кхаши. Отнесите ее Татару вместе с Кожей Опасного Паука Кхаши и Огненным Яйцом.', 'etc_leather_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1618', 'Kasha Blade Spider Husk', null, 'Кожа Опасного Паука Кхаши. Отнесите ее Татару вместе со Шкурой Медведя Кхаши и Огненным Яйцом.', 'etc_leather_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1619', '1st Fiery Egg', null, 'Яйцо, полученное от Алой Саламандры. Отдайте его Татару вместе со Шкурой Медведя Кхаши и Кожей Опасного Паука Кхаши.', 'etc_crystal_ball_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1620', 'Hestui Mask', null, 'Маска медведя. Отнесите ее тотемному духу Хестуи.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1621', '2nd Fiery Egg', null, 'Яйцо, полученное от Алой Саламандры. Отдайте его Татару вместе со Шкурой Медведя Кхаши и Кожей Опасного Паука Кхаши.', 'etc_crystal_ball_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1622', 'Totem Spirit Claw', null, 'Коготь, полученный у тотемного духа Хестуи. Возьмите его и идите к Татару.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1623', 'Tataru\'s Letter of Recommendation', null, 'Письмо, написанное Татару. Отдайте его Провидцу Умосу в Глудине.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1624', 'Flame Charm', null, 'Оберег с описанием молитвы огня. Возьмите его, соберите кровь гризли и отдайте Провидцу Умосу.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1625', 'Grizzly Blood', null, 'Стеклянная бутылка, наполненная кровью гризли. Соберите 3 таких и отнесите Провидцу Умосу.', 'etc_reagent_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1626', 'Blood Cauldron', null, 'Кувшин, наполненный кровью гризли. Отдайте его духу Дуда-Мара.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1627', 'Spirit Net', null, 'Сеть, сплетенная из паучьего шелка. Используйте ее для поимки Духа Дарки, прячущегося внутри Ядовитых Пауков.', 'etc_piece_of_cloth_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1628', 'Bound Durka Spirit', null, 'Дух Дарки, пойманный призрачной сетью. Отдайте его духу Дуда-Мара.', 'etc_crystal_ball_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1629', 'Durka Parasite', null, 'Злой дух, который исходит из пауков, зараженных духом Дарки. Необходим для призыва духа Дарки.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1630', 'Totem Spirit Blood', null, 'Кровь тотема Дуда-Мара. Отнесите ее Провидцу Умосу.', 'etc_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1631', 'Mask of Medium', null, 'Маска, вручаемая только Оркам, достойным стать Шаманами. Отнесите ее Понтифику для смены профессии.', 'etc_skull_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1632', 'Silvera\'s Ring', null, 'Кольцо, сделанное для кандидатов в ремесленники Кузнецом Сильверой. Убейте Крысолюдов Бугл и соберите их зубы.', 'accessary_ring_of_assistance_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1633', '1st Pass Certificate', null, 'Свидетельство об успешном прохождении I испытания Ремесленника. Далее Вы должны поговорить с Клуто из Глудина.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1634', '2nd Pass Certificate', null, 'Свидетельство об успешном прохождении II испытания Ремесленника. Отнесите его Кузнецу Клуто в Глудин.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1635', 'Final Pass Certificate', null, 'Свидетельство об успешном прохождении последнего испытания Ремесленника. Отдайте его Главному Кузнецу для смены профессии.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1636', 'Boogle Ratman Tooth', null, 'Уродливый зуб Крысолюда Бугл. Один его вид вызывает тошноту. Соберите 10 таких зубов и отдайте их Кузнецу Сильвере.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1637', 'Boogle Ratman Leader\'s Tooth', null, 'Очень вонючий зуб Главаря Крысолюдов Бугл. Найдите 2 штуки и отдайте их Кузнецу Сильвере.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1638', 'Kluto\'s Letter', null, 'Письмо Кузнеца Клуто. Отнесите его Кузнецу Пинтеру в Глудио.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1639', 'Footprint of Thief', null, 'След, оставленный ворами. Убейте Бойцов Орков Вуку, верните украденные вещи и отнесите их Кузнецу Пинтеру.', 'etc_leather_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1640', 'Stolen Secret Box', null, 'Ящик, украденный Бойцами Орков Вуку. Содержимое его неизвестно, но в любом случае отдайте его Кузнецу Пинтеру.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1641', 'Secret Box', null, 'Ящик, полученный от Пинтера. Содержимое его неизвестно, но Вас оно и не должно волновать - просто отнесите сундук Кузнецу Клуто в Глудин.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1642', 'Ring of Raven', null, 'Знак, необходимый для того, чтобы стать Собирателем. Если Вы отдадите его Начальнику Склада, то сможете сменить профессию.', 'accessary_ring_of_raccoon_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1643', 'Pippi\'s Letter of Recommendation', null, 'Рекомендация, написанная Коллекционером Пепи. Отдайте ее Торговцу Мион.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1644', 'Raut\'s Teleport Scroll', null, 'Заказ Раута. Отнесите его Тораю в южную часть Долины Смерти.', 'etc_scroll_of_return_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1645', 'Succubus Undies', null, 'Белье Суккуба, полученное от Торая. Отнесите его Рабочему Склада Рауту в Глудин.', 'etc_piece_of_cloth_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1646', 'Mion\'s Letter', null, 'Письмо от Торговца Мион своему брату. Отнесите его Мастеру Томе.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1647', 'Bronk\'s Ingot', null, 'Слиток, который надо отдать Главному Кузнецу Бронку.', 'etc_plate_glay_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1648', 'Shari\'s Axe', null, 'Топор, который надо отдать Торговцу Шари.', 'weapon_tomahawk_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1649', 'Zimenf\'s Potion', null, 'Зелье, которое нужно отдать Жрецу Земли Зименфу.', 'etc_potion_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1650', 'Bronk\'s Pay', null, 'Плата Главного Кузнеца Бронка. Отдайте ее Торговцу Мион.', 'etc_coins_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('1651', 'Shari\'s Pay', null, 'Плата Шари. Отдайте ее Торговцу Мион.', 'etc_coins_gold_i00', '0');
