INSERT INTO `ghtweb_all_items` VALUES ('1656', 'Bead', null, 'Бусинка, полученная из Тарантула. Соберите 20 таких и отдайте их Мастеру Томе.', 'etc_crystal_ball_blue_i00', '0');
