INSERT INTO `ghtweb_all_items` VALUES ('2817', '2nd Secret Letter', null, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2818', '3rd Secret Letter', null, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'weapon_scroll_of_wisdom_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2819', '4th Secret Letter', null, 'Документ Ящеров Лито. Соберите все документы и отнесите их Святой Кристине.', 'weapon_scroll_of_wisdom_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2820', 'Mark of Healer', null, 'Знак, выдаваемый прошедшим Испытание целителя. Предмет для смены профессии.', 'etc_jewel_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2821', 'Mark of Reformer', null, 'Знак, выдаваемый прошедшим Испытание жреца. Предмет для смены профессии.', 'etc_jewel_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2822', 'Book of Reform', null, 'Книга, полученная от Жрицы Пупины. Отправляйтесь в Землю Казненных и убейте нежить при помощи силы света.', 'weapon_apprentices_spellbook_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2823', 'Letter of Introduction', null, 'Письмо Жрицы Пупины. Возьмите его и отдайте Проповеднице Сла в Пустоши.', 'etc_scroll_of_enchant_armor_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2824', 'Sla\'s Letter', null, 'Письмо Сла. Отнесите его Катари, которая находится недалеко от водопада в Нейтральной Зоне.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2825', 'Greetings', null, 'Письмо, отправленное Сла ее ученикам. Отнесите его в Деревню Орков, Деревню Гномов и на Говорящий Остров. Только не перепутайте!', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2826', 'Ol Mahum\'s Money', null, 'Деньги Гноллов, которые они дают вместо награды. Для чего они нужны? Этого не знает никто.', 'etc_coins_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2827', 'Katari\'s Letter', null, 'Ответное письмо Катари для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2828', 'Nyakuri\'s Letter', null, 'Ответное письмо Ниакури для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2829', 'Undead List', null, 'Скелет Стрелок, Лорд Скелетов, Скелет Снайпер, Скелет Каторжник, Безмолвный Ужас.', 'etc_recipe_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2830', 'Ramus\'s Letter', null, 'Ответное письмо Рамуса для Сла. Соберите все 3 ответных письма и отнесите их Сла.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2831', 'Ripped Diary', null, 'Обрывок дневника, содержащего последние слова молодой женщины, убитой во время охоты на ведьм герцога Байрона Эштона. Соберите 7 таких.', 'etc_map_piece_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2832', 'Huge Nail', null, 'Огромный ноготь, вросший в череп Арурона. Отнесите его Жрице Пупине в Гиран.', 'weapon_heavy_chisel_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2833', 'Letter of Betrayer', null, 'Письмо Гнолла Предателя. Отнесите его Катари, находящейся в районе болот Темного Леса.', 'etc_scroll_gray_i00', '0');
