INSERT INTO `ghtweb_all_items` VALUES ('2839', 'Bone Fragment', null, 'Обломок кости Скелета. Отнесите его вместе с остальными костями нежити Рамусу.', 'etc_rib_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2840', 'Mark of Magus', null, 'Знак, выдаваемый прошедшим Испытание магии. Предмет для смены профессии.', 'etc_mark_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2841', 'Rukal\'s Letter', null, 'Письмо Барда Рукала Парине из Глудина.', 'etc_letter_blue_i00', '0');
