INSERT INTO `ghtweb_all_items` VALUES ('2849', 'Flame Crystal', null, 'Кристалл, добытый из призрачного огня. Соберите 5 таких и отнесите их Огненной Саламандре.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2850', 'Harpy\'s Feather', null, 'Перо убитой гарпии. Соберите 20 таких и отнесите их Воздушному Сильфу.', 'etc_feather_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2851', 'Wyrm\'s Wingbone', null, 'Кость из крыла змея. Соберите 10 таких и отнесите их Воздушному Сильфу.', 'etc_piece_bone_red_i00', '0');
