INSERT INTO `ghtweb_all_items` VALUES ('2854', 'Enchanted Golem Powder', null, 'Каменная пыль с убитого зачарованного голема. Соберите 10 таких и отнесите их Земляной Змее.', 'etc_powder_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2855', 'Enchanted Iron Golem Shard', null, 'Осколок зачарованного железного голема. Соберите 10 таких и отнесите их Земляной Змее.', 'etc_stone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2856', 'Tone of Water', null, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'etc_scroll_of_enchant_armor_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2857', 'Tone of Fire', null, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'etc_scroll_of_enchant_weapon_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2858', 'Tone of Wind', null, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'etc_scroll_of_return_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2859', 'Tone of Earth', null, 'Одна из частей гармонии звуков стихий. Отнесите ее Барду Рукалу в Дион.', 'etc_scroll_of_resurrection_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2860', 'Salamander Charm', null, 'Оберег, данный Огненной Саламандрой. Она согласна отдать Звук Огня за 5 Кристаллов Пламени.', 'etc_piece_of_cloth_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2861', 'Sylph Charm', null, 'Оберег, данный Воздушным Сильфом. Он согласен отдать Звук Ветра за материалы, собранные с Гарпий, Змеев и Вепрей.', 'etc_piece_of_cloth_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2862', 'Undine Charm', null, 'Оберег, данный Водной Ундиной. Она согласна отдать Звук Воды за 20 Ослепительных Камней.', 'etc_piece_of_cloth_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2863', 'Serpent Charm', null, 'Оберег, данный Земляной Змеей. Она согласна отдать Звук Земли за уничтожение Зачарованных Монстров вокруг Башни Слоновой Кости.', 'etc_piece_of_cloth_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2864', 'Recommendation of Balanki', null, 'Рекомендательное письмо от Баланки из Гильдии Серебряных Весов. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2865', 'Recommendation of Filaur', null, 'Рекомендательное письмо от Филара из Гильдии Серой Колонны. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2866', 'Recommendation of Arin', null, 'Рекомендательное письмо от Арина из Гильдии Черной Наковальни. Соберите все три рекомендации и отнесите их Локрину из Гильдии Железных Врат.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2867', 'Mark of Maestro', null, 'Знак, выдаваемый прошедшим Испытание мастера. Предмет для смены профессии.', 'etc_badge_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2868', 'Letter of Solder Detachment', null, 'Письмо Капитана Крото, в котором говорится о скором прибытии подкреплений. Доставьте его Локрину.', 'etc_scroll_of_return_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2869', 'Paint of Kamuru', null, 'Портрет Камуру. Отправляйтесь в Пещеру Испытаний во владениях Орков и выясните, что с ним случилось.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2870', 'Necklace of Kamuru', null, 'Ожерелье, которое носил Камуру. Отнесите его Капитану Крото.', 'accessary_necklace_of_darkness_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2871', 'Paint of Teleport Device', null, 'Рисунок устройства для телепортации. Заберите этот прибор у Мастера Томы.', 'etc_recipe_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2872', 'Teleport Device', null, 'Устройство для телепортации, разработанное Мастером Томой. Отнесите его Арину.', 'etc_squares_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2873', 'Architecture of Cruma', null, 'Простое объяснение архитектуры Башни Крумы. Отнесите его команде, находящейся у входа в Башню Крумы.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2874', 'Report of Cruma', null, 'Отчет о результатах исследований Башни Крумы. Отнесите его Филару.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2875', 'Ingredients of Antidote', null, 'Соберите 10 Осиных Жал, 10 Паутин Болотного Паука и 10 порций Крови Пиявки и отнесите их Исследователю Лорейн.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2876', 'Stinger Wasp Needle', null, 'Жало осы. Соберите 10 таких и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2877', 'Marsh Spider\'s Web', null, 'Тонкая паутина. Соберите 10 таких и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'etc_skein_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2878', 'Leech Blood', null, 'Кровь, добытая при убийстве пиявки. Соберите 10 порций и отнесите их Исследователю Лорейн вместе с остальными ингредиентами.', 'etc_reagent_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2879', 'Mark of Warspirit', null, 'Знак, выдаваемый прошедшим Испытание вестника. Предмет для смены профессии.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2880', 'Vendetta Totem', null, 'Тотем, выдаваемый Оркам, готовым наказать предателей расы. Возьмите его и убейте Орков Тамлин.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2881', 'Tamlin Orc Head', null, 'Голова убитого Орка Тамлин. Соберите 13 таких и отнесите их Провидцу Сомаку.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2882', 'Warspirit Totem', null, 'Тотем, используемый в ритуале Духа Войны. Отнесите его Прародителю Мартанкусу в Пещеру Испытаний.', 'accessary_another_worlds_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2883', 'Orim\'s Contract', null, '\"Я согласен отдать тебе Останки Браки за 10 Глаз Порты, 10 Чешуй Экскуро и 10 Когтей Мордео.\"', 'etc_scroll_gray_i00', '0');
