INSERT INTO `ghtweb_all_items` VALUES ('2902', 'Racoy\'s Totem', null, 'Тотем, полученный от Провидца Ракоя. Отправляйтесь в Храм Эйнхасад в Глудио, чтобы узнать насчет Кируны.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2903', 'Vivyan\'s Letter', null, 'Письмо Жрицы Вивиан. Отнесите его Торговцу Сариену в южную часть Пустоши.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2904', 'Insect Diagram Book', null, 'Энциклопедия насекомых, которую Торговец Сариен отдал Вам в помощь. Возьмите ее с собой на охоту на Элитных Муравьев, чтобы найти останки Кируны.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('2905', 'Kiruna\'s Skull', null, 'Череп Кируны, древнего героя Орков. Отнесите его и остальные останки Провидцу Ракою.', 'etc_skull_white_i00', '0');
