INSERT INTO `ghtweb_all_items` VALUES ('3300', 'Talisman of Kadesh', null, 'Странный талисман, полученный после убийства Кадеша. Отнесите его к Снайперу Хамилю в Флоран.', 'accessary_red_cresent_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3301', 'Talisman of Snake', null, 'Талисман, связанный с духом тотема змеи, которому поклоняются Орки Брека. Отнесите его Префекту Вокиану в Гиран.', 'accessary_dragon_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3302', 'Mithril Clip', null, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'accessary_ring_of_knowledge_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3303', 'Stakato Chitin', null, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'etc_parasite_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3304', 'Reinforced Bowstring', null, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'etc_skein_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3305', 'Manashen\'s Horn', null, 'Основной материал, необходимый для восстановления Лука Полумесяца. Отнесите его вместе с остальными компонентами Магистру Гейну в Башню Слоновой Кости.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3306', 'Blood of Lizardman', null, 'Кровь, пролитая Ящером Лито. Когда соберете достаточное ее количество, появится Кадеш.', 'etc_reagent_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3307', 'Mark of Witchcraft', null, 'Знак, вручаемый тем, кто прошел Испытание колдуна. Необходим для смены профессии.', 'etc_skull_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3308', 'Orim\'s Diagram', null, 'Схема реликвий, которую дал Вам Орим Тень. Здесь изображены 6 драгоценных камней, необходимых для открытия Куба Аклантота.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3309', 'Alexandria\'s Book', null, 'Книга, которая содержит записи о том, кто купил Камни Аклантота: Магистр Айкер, Магистр Кайра, Торговец Лара.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3310', 'Iker\'s List', null, 'Список материалов, необходимых Магистру Айкеру: 20 клыков Жуткого Змея, 20 Оберегов Ящеров Лито и 20 Сердец Зачарованного Голема.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3311', 'Dire Wyrm Fang', null, 'Клык Жуткого Змея. Соберите 20 таких и отнесите Магистру Айкеру.', 'etc_fang_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3312', 'Leto Lizardman Charm', null, 'Оберег, полученный при убийстве Ящера Лито. Соберите 20 таких и отнесите Магистру Айкеру.', 'etc_totem_necklace_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3313', 'Enchanted Stone Golem Heartstone', null, 'Кристалл, найденный среди останков Зачарованного Каменного Голема. Соберите 20 таких и отнесите магистру Айкеру.', 'etc_stone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3314', 'Lara\'s Memo', null, 'Отчет о продажах Торговца Лары. Здесь написано, что Камень Аклантота был куплен человеком по имени Исмел.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3315', 'Nestle\'s Memo', null, 'Отчет о покупках Торговца Лары. Здесь написано, что Камень Аклантота был принесен Леопольдом из отряда Черного Льва.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3316', 'Leopold\'s Journal', null, 'Отрывок из дневника Леопольда. Здесь написано о 3 дезертирах, погибших в Пустоши и превратившихся в нежить.', 'etc_spellbook_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3317', 'Aklantoth 1st Gem', null, 'Драгоценный камень, полученный от Магистра Айкера. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3318', 'Aklantoth 2nd Gem', null, 'Драгоценный камень, полученный от Магистра Кайры. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_bead_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3319', 'Aklantoth 3rd Gem', null, 'Драгоценный камень, полученный при убийстве Безымянного Призрака. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_bead_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3320', 'Aklantoth 4th Gem', null, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3321', 'Aklantoth 5th Gem', null, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_bead_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3322', 'Aklantoth 6th Gem', null, 'Драгоценный камень, полученный при убийстве Скелета Наемника. Найдите 6 Камней Аклантота и отнесите их Ориму Тени.', 'etc_crystal_ball_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3323', '1st Brimstone', null, 'Знак, оставленный Принцем Дре Ванул Зеруэлем при его побеге.', 'etc_powder_orange_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3324', 'Orim\'s Instructions', null, 'Приказ Орима Тени. Вы должны найти Меч Оков и Кристалл Ловушку.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3325', 'Orim\'s 1st Letter', null, 'Письмо Орима Тени сэру Клаусу Васперу в Глудин с просьбой взять на время Меч Оков.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3326', 'Orim\'s 2nd Letter', null, 'Письмо Орима Тени Магистру Айкеру в Гиран с просьбой взять на время Кристалл Ловушку.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3327', 'Sir Vasper\'s Letter', null, 'Письмо сэра Клауса Васпера Вадину в Орен, в котором он дает разрешение использовать Меч Оков.', 'etc_scroll_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3328', 'Vadin\'s Crucifix', null, 'Святое распятие, данное Вадином. Идите с ним на охоту на Орков Тамлин.', 'accessary_earing_of_wisdom_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3329', 'Tamlin Orc Amulet', null, 'Амулеты, которые Орки Тамлин используют в своем колдовстве. Соберите 20 таких и отнесите Вадину.', 'etc_totem_necklace_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3330', 'Vadin\'s Sanctions', null, 'Письмо Вадина, разрешающее использовать Меч Оков. Отнесите его сэру Клаусу Васперу в Глудин.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3331', 'Iker\'s Amulet', null, 'Амулет, данный Магистром Айкером. Говорят, он оберегает от сил зла.', 'accessary_necklace_of_grace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3332', 'Soultrap Crystal', null, 'Кристалл, способный заманить в ловушку и запечатать душу монстра. Используйте его, чтобы поймать дух Принца Дре Ванул Зеруэля.', 'etc_gem_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3333', 'Purgatory Key', null, 'Ключ, которым нужно закрыть сундук Аклантота. Отнесите его Ориму Тени.', 'etc_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3334', 'Zeruel Bind Crystal', null, 'Кристалл, который содержит пойманную в ловушку душу Принца Дре Ванул Зеруэля. Отнесите его Ориму Тени.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3335', '2nd Brimstone', null, 'Знак, оставленный Принцем Дре Ванул Зеруэлем при его побеге из тела Рыбака Эверта.', 'etc_powder_orange_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3336', 'Mark of Summoner', null, 'Знак, вручаемый за прохождение Испытания призывателя. Необходим для смены профессии.', 'weapon_apprentices_rod_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3337', 'Leto Lizardman Amulet', null, 'Амулет, полученный после убийства Ящера Лито. Соберите 30 таких и отнесите их Торговцу Ларе.', 'etc_totem_necklace_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3338', 'Sac of Redspores', null, 'Красные споры, полученные из гигантских грибов. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3339', 'Karul Bugbear Totem', null, 'Тотем, полученный после убийства Людоеда Карул. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_totem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3340', 'Shards of Manashen', null, 'Осколок Манашен Горгульи. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3341', 'Breka Orc Totem', null, 'Тотем, который можно получить после убийства Орка Брека. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3342', 'Crimson Bloodstone', null, 'Камень, вложенный в Пленную Душу. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3343', 'Talons of Tyrant', null, 'Коготь убитого Тирана. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3344', 'Wings of Droneant', null, 'Крылья, полученные после убийства Элитного Муравья из Муравейника. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_feather_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3345', 'Tusk of Windsus', null, 'Клык убитого Вепря. Соберите 30 таких и отнесите их Торговцу Ларе.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3346', 'Fangs of Wyrm', null, 'Клык убитого Змея. Соберите 30 таких и отнесите Торговцу Ларе.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3347', 'Lara\'s 1st List', null, 'Соберите 30 Амулетов Ящеров Лито в Долине Ящеров и 30 Мешочков с Красными Спорами из Гигантских Грибов в Море Спор.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3348', 'Lara\'s 2nd List', null, 'Соберите 30 Тотемов Людоедов Карул в Долине Охотников и 30 Осколков Манашен в Кратере Башни Слоновой Кости.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3349', 'Lara\'s 3rd List', null, 'Соберите 30 Тотемов Орков Брека в Укреплении Бреки и 30 Камней Крови Пленных Душ в Долине Смерти.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3350', 'Lara\'s 4th List', null, 'Соберите 30 Когтей Тирана в Пустоши и 30 Клыков Вепря в Долине Смерти.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3351', 'Lara\'s 5th List', null, 'Соберите 30 Крыльев Элитных Муравьев в Муравейнике и 30 Клыков Змеев в Саду Цветов Горгон.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3352', 'Galatea\'s Letter', null, 'Письмо Великого Призывателя Галатеи для Торговца Лары из Диона.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3353', 'Beginner\'s Arcana', null, 'Карточка, используемая учениками призывателей. Нужна, чтобы участвовать в сражениях призывателей.', 'etc_ticket_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3354', 'Almors\'s Arcana', null, 'Карточка Призывателя Алморса. Доказательство победы в сражении. Отдайте ее Великому Призывателю Галатее.', 'shield_dark_dragon_shield_i01', '0');
