INSERT INTO `ghtweb_all_items` VALUES ('3390', 'Mark of Lord', null, 'Знак, вручаемый тем, кто прошел Испытание Верховного Шамана. Необходим для смены профессии.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('3391', 'Ordeal Necklace', null, 'Ожерелье, вручаемое тем, кто пытается пройти Испытание Верховного Шамана. Найдите 5 главарей различных племен и получите их одобрение.', 'accessary_another_worlds_necklace_i00', '0');
