INSERT INTO `ghtweb_all_items` VALUES ('3397', 'Manakia\'s Orders', null, 'Документ, содержащий указания Провидца Манакии. Вам необходимо охотиться на Шаманов и Владык Орков Брека и собрать у них 20 Клыков Орков Брека.', 'etc_scroll_gray_i00', '0');
