INSERT INTO `ghtweb_all_items` VALUES ('3947', 'Blessed Spiritshot: No Grade', null, 'Капсула, в которой заключена сила древнего духа. Значительно увеличивает Маг. Атк. Используется с оружием без ранга.', 'etc_spell_shot_white_i01', '0');
