INSERT INTO `ghtweb_all_items` VALUES ('3949', 'Blessed Spiritshot (C-Grade)', null, 'Капсула, в которой заключена сила древнего духа. Значительно увеличивает Маг. Атк. Используется с оружием Ранга C.', 'etc_spell_shot_green_i01', '0');
