INSERT INTO `ghtweb_all_items` VALUES ('3953', 'Recipe: Blessed Spiritshot D', null, 'Только для Гномов. Рецепт создания Благословенных Зарядов Духа: Ранг D. Требуется умение \"Создать Вещь\" 2-го уровня. Шанс создания: 100%.', 'etc_recipe_blue_i00', '5');
