INSERT INTO `ghtweb_all_items` VALUES ('4255', 'Trade Cargo', null, 'Груз, который был украден из фургонов Торговой Гильдии. Соберите 30 ящиков и отнесите их Стражу Вейсу.', 'etc_pouch_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4256', 'Agnes\'s Holy Symbol', null, 'Распятие богини Эйнхасад. Эту статуэтку оставила жрица Агнес после своей смерти. Отнесите ее вместе с Амулетом Агнес Жрецу Адониусу.', 'etc_statue_of_einhasad_bronze_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4257', 'Agnes\'s Rosary', null, 'Амулет Жрицы Агнес, оставшийся после ее смерти. Отнесите это вместе со Святым Знаком Агнес Жрецу Адонису.', 'etc_evil_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4258', 'Sinister Totem', null, 'Черный тотем, источающий злую ауру. Отнесите его Верховной Жрице Левиан.', 'etc_totem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4259', 'Bear Skin', null, 'Шкура медведя. Соберите 20 таких и отнесите их Бакалейщику Пано в Флоран.', 'etc_leather_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4260', 'Enku Orc\'s Head', null, 'Отрубленная голова Орка Энку. Соберите 100 таких и отнесите их Дженнифер.', 'etc_skull_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4261', 'Orc Heads Bouquet -1', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Понтифику Дрикусу от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4262', 'Orc Heads Bouquet -2', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Жрецу Мануэлю от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4263', 'Orc Heads Bouquet -3', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Главе Вуку Дрико от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4264', 'Orc Heads Bouquet -4', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Пророку Сомаку от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4265', 'Orc Heads Bouquet -5', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Префекту Доки от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4266', 'Orc Heads Bouquet -6', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Смотрителю Эндриго от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4267', 'Orc Heads Bouquet -7', null, 'Букет, сделанный из 100 голов Орков. Доставьте это Капитану Лукасу от имени Дженнифер. Она слишком застенчива, чтобы сделать это лично.', 'etc_flower_bouquet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4268', 'Jennifer\'s Box', null, 'Коробка, которую кто-то попросил доставить Леди Орку Дженнифер. Интересно, что там внутри?..', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4269', 'Articles of Dead Heroes', null, 'Вещи солдат, погибших во время экспедиции тысячу лет назад. Они были собраны во время охоты на Пещерных Слуг. Отнесите их Смотрителю Антараса Гильмору.', 'etc_squares_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4270', 'Old Key', null, 'Вещь мертвого солдата. Его потомок, сэр Кристоф Родемаи, живет в Гиране. Отнесите это ему.', 'etc_old_key_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4271', 'Old Hilt', null, 'Вещь мертвого солдата. Его потомок, Дуэлист Каен, живет в Орене. Отнесите это ему.', 'etc_hilt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4272', 'Totem Necklace', null, 'Вещь мертвого солдата. Его потомок, Понтифик Гарварентс, живет в Деревне Охотников. Отнесите это ему.', 'etc_totem_necklace_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4273', 'Einhasad Crucifix', null, 'Вещь мертвого солдата. Отнесите это Верховному Жрецу Храма Эйнхасад Орвену в Аден.', 'etc_magic_coin_silver_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4274', 'Victim\'s Arm Bone', null, 'Кость руки жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'etc_piece_bone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4275', 'Victim\'s Thigh Bone', null, 'Кость бедра жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'etc_piece_bone_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4276', 'Victim\'s Skull', null, 'Череп жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'etc_skull_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4277', 'Victim\'s Rib Bone', null, 'Кость ребра жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'etc_rib_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4278', 'Victim\'s Spine', null, 'Позвоночник жертвы, которую съел Крок. Соберите пять типов костей и отнесите их Ксеновии.', 'etc_piece_bone_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4279', 'Jar of Bones', null, 'Урна, в которой лежат кости всех жертв. Попросите Сумасшедшего Доктора Орфеуса воскресить их.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4280', 'Useless Bone Pieces', null, 'Бесполезные части костей, полученные после охоты на Кроков. Если Вы отнесете их к Орфеусу, возможно, Вы получите что-нибудь в награду...', 'etc_mithril_ore_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4281', 'Powder to Summon Dead Souls', null, 'Волшебный порошок, купленный у Магистра Ксеновии. Бросьте это вместе с костями жертв в урну сумасшедшего доктора.', 'etc_powder_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4282', 'Sack of the Dead', null, 'Мешок, содержащий душу жертвы. Добавляется в урну. Отнесите это Кузнецу Дороти.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4283', 'Frog Prince', null, 'Чего же Вы ждете? Вы обещали помочь мне! Освободите меня от этого проклятия немедленно! Я должен стать прежним как можно скорее!', 'etc_q_frog_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4284', 'Fly Powder', null, 'Порошок из сушеных мух. Используйте его, если потерпите неудачу в своей попытке вернуть лягушке прежний вид.', 'etc_powder_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4285', 'Calculator', null, 'Последняя модель вычислительной машины. Отнесите это Кузнецу Брюнону.', 'etc_calculator_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4286', 'Gemstone Beast\'s Crystal', null, 'Кристалл, полученный при убийстве Самоцветного Зверя. Соберите 10 таких и отнесите Кузнецу Сильвере.', 'etc_crystal_ball_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4287', 'Titan\'s Powerstone', null, 'Необычный камень, который был извлечен из трупа Гиганта. Отнесите его Магистру Ханелин.', 'etc_instrument_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4288', 'Hanellin\'s 1st Letter', null, 'Письмо, врученное Вам Ханелин. Отнесите его Магистру Харн в Деревню Темных Эльфов и получите у нее следующее задание.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4289', 'Hanellin\'s 2nd Letter', null, 'Письмо, врученное Вам Ханелин. Отнесите его Клаудии Атебальт в Аден и получите у нее следующее задание.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4290', 'Hanellin\'s 3rd Letter', null, 'Письмо, врученное Вам Ханелин. Отнесите его Мартиену в Гиран и получите у него следующее задание.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4291', '1st Key of Ark', null, 'Ключ, найденный на теле Стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4292', '2nd Key of Ark', null, 'Ключ, полученный при убийстве Элберота, стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'etc_old_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4293', '3rd Key of Ark', null, 'Ключ, полученный при убийстве Клыка Теней, стража ковчега. Используйте его, чтобы открыть ковчег и получить священный предмет.', 'etc_old_key_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4294', 'White Fabric', null, 'Большое полотно белой ткани, полученный от Магистра Ханелин. Убейте Шаманов и Повелителей Платинового Клана и пропитайте ткань их кровью.', 'etc_piece_of_cloth_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4295', 'Blooded Fabric', null, 'Ткань, впитавшая в себя кровь Ангелов и Платинового Клана. По словам Ханелин, чтобы бросить вызов Баюму, Вы должны обернуть ее вокруг своего тела.', 'etc_piece_of_cloth_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4296', 'Order of Gosta', null, 'Приказ, предписывающий охотиться на Ящеров Тасаба и Шаманов Ящеров Тасаба.', 'etc_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4297', 'Lizard Fang', null, 'Клык, полученный при убийстве Ящеров Тасаба и Шаманов Ящеров Тасаба', 'etc_molar_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4298', 'Barrel of League', null, 'Груз, который, по-видимому, был украден из фургона Ясона Хейна Ящерами Тасаба.', 'etc_wine_barrel_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4299', 'Operation Document - 1/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4300', 'Operation Document - 2/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4301', 'Operation Document - 3/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
