INSERT INTO `ghtweb_all_items` VALUES ('4305', 'Operation Document - 7/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4306', 'Operation Document - 8/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4307', 'Operation Document - 9/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4308', 'Operation Document - 10/10', null, 'Документ, найденный в грузе Торговой Гильдии. В нем содержится различная информация об Иннадриле. Как такое могло случиться?..', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4309', 'Completed Operation Order', null, 'Книга из 10 страниц заказов. Кому это отдать?..', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4310', 'Iason Heine\'s Bill', null, 'Чек, на котором указана сумма в 1000 аден. Если Вы отнесете его Кузнецу Роману в Иннадрил, то сможете купить различные ингредиенты.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4311', 'Gillian\'s Diary', null, 'Дневник Джиллиана. Последняя запись была сделана год назад.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4312', 'Gillian\'s Notes', null, 'Часть текста песни Джиллиана.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4313', 'Unfinished Music', null, 'Незаконченный текст песни, которую Джиллиан написал для своей возлюбленной.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4314', 'Gillian\'s Heart', null, 'Сердце, которое Джиллиан выбросил, чтобы забыть свою любовь. Верните его Призраку Джиллиана.', 'etc_bodypart_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4315', 'Gandi Tribe\'s Relic', null, 'Священный предмет племени Ганди, отобранный у Людоедов. Отнесите его Вождю Ганди Чианте в Дион.', 'etc_royal_seal_of_lord_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4316', 'Swan\'s Flute', null, 'Флейта, которую Бард Свен хочет подарить Музыканту Нанарин.', 'etc_dragon_flute_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4317', 'Swan\'s Letter', null, 'Любовное письмо, которое Свен хочет послать Нанарин вместе с флейтой. Отнесите его Музыканту Нанарин.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4318', 'Event Clothes', null, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'etc_ladys_dress_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4319', 'Nanarin\'s Flute', null, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'etc_dragon_flute_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4320', 'Sabrin\'s Black Beer', null, 'Подарок, который Нанарин посылает Барбадо. Отнесите его Барбадо.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4321', 'Stolen Black Beer', null, 'Темное пиво, украденное у Джонаса. Отнесите его Торговцу Сабрину.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4322', 'Stolen Event Clothes', null, 'Парадная одежда, украденная у Торговца Сони. Отдайте ее Стражу Ксаберу.', 'etc_ladys_dress_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4323', 'Clothes Chest Key', null, 'Ключ Барда Свена. Используйте его, чтобы открыть сундук с одеждой и вернуть украденное.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4324', 'Beer Chest Key', null, 'Ключ Барда Свена. Используйте этот ключ, чтобы открыть пивное хранилище и забрать черное пиво.', 'etc_old_key_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4325', 'Fairy Leaf', null, 'Лист Феи Мимю. Нужно положить его на шею феи, чтобы излечить рану, нанесенную дракончиком.', 'etc_leaf_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4326', 'Ratman Scavenger\'s Skull', null, 'Голова Крысолюда Падальщика, добытая по приказу Катари Соберите 10 таких и отнесите их Катари.', 'etc_pet_arms_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4327', 'Turek War Hound\'s Tail', null, 'Хвост Гончей Турек, пойманной по приказу Пиотура. Соберите 10 таких и отнесите их Пиотуру.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4328', 'Tyrant Kingpin\'s Heart', null, 'Сердце Главного Тирана. Отнесите его Старейшине Казиану.', 'etc_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4329', 'Trisalim Tarantula\'s Venom Sac', null, 'Ядовитая железа Тарантула Трисалим, убитого по приказу Магистра Джоан. Соберите 3 таких и отнесите их Магистру Джоан.', 'etc_poison_pouch_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4330', 'Penitent\'s Manacles', null, 'Тяжелый набор оков, сделанных по приказу Черного Судьи. Отнесите их Черному Судье.', 'etc_leash_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4331', 'Manual of Manacles', null, 'Заготовка Кузнеца - 1 шт., Сталь - 5 шт., Адамантитовый Слиток - 2 шт., Серебряный Слиток - 10 шт., Кокс - 10 шт.', 'etc_recipe_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4332', 'Tarlk Amulet', null, 'Знак, который можно получить при убийстве Людоеда или Василиска Тарлк. Соберите 30 таких и отнесите их Глашатаю Холла Клана.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4333', 'Contest Certificate', null, 'Свидетельство, дающее право охотиться на Василисков Тарлк в предварительном испытании Осады Холла Кланов.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4334', 'Ant\'s Ichor', null, 'Жидкость, извлеченная из Муравьев или Капитанов Муравьев. Соберите 20 порций и отнесите их Старейшине Казиану.', 'etc_reagent_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4335', 'Noble Ant\'s Nerve Tissue', null, 'Нервная ткань из головы Элитного Муравья. Отнесите ее Старейшине Казиану вместе с Сукровицей Муравья.', 'etc_bodypart_brain_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4336', 'Casian\'s Enzyme', null, 'Фермент, созданный Старейшиной Казианом. Найдите Личинок Муравьев, спящих в Муравейнике, и управляйте ими с помощью фермента.', 'etc_spell_shot_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4337', 'Alligator Leather', null, 'Кожа Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'etc_scale_of_medusa_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4338', 'Blue Back Alligator Leather', null, 'Кожа Синего Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'etc_scale_of_medusa_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4339', 'Jewel Studded Alligator Leather', null, 'Кожа Драгоценного Аллигатора, пойманного на Острове Аллигаторов. Можно продать Торговцу Энверуну.', 'etc_scale_of_medusa_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4340', 'Certificate of Approval to Create a Belt', null, 'Если Вы соберете достаточное количество Шкур Аллигаторов и отдадите их Кожевнику Версу, он сделает для Вас пояс из кожи аллигатора.', 'etc_recipe_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4341', 'Certificate of Approval to Create a Purse', null, 'Если Вы соберете достаточное количество Шкур Аллигаторов и отдадите их Кожевнику Версу, он сделает для Вас сумочку из кожи аллигатора.', 'etc_recipe_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4342', 'Water Crystal', null, 'Большой кристалл, который содержит энергию Воды. Возьмите его и найдите Сундук Воды.', 'etc_gem_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4343', 'Fire Crystal', null, 'Большой кристалл, который содержит энергию Огня. Возьмите его и найдите Сундук Огня.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4344', 'Wind Crystal', null, 'Большой кристалл, который содержит энергию Ветра. Возьмите его и найдите Сундук Ветра.', 'etc_gem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4345', 'Earth Crystal', null, 'Большой кристалл, который содержит энергию Земли. Возьмите его и найдите Сундук Земли.', 'etc_gem_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4346', 'Dark Crystal', null, 'Большой кристалл, который содержит энергию Тьмы. Возьмите его и найдите Сундук Тьмы.', 'etc_gem_clear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4347', 'Crystal of Light', null, 'Большой кристалл, который содержит энергию Света. Возьмите его и найдите Сундук Света.', 'etc_gem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4348', 'Jade Crystal', null, 'Нефритовый кристалл, найденный в Волшебной Долине. Соберите их и отнесите Бентли в Деревню Охотников.', 'etc_gem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4349', 'Bust of Ancient Goddess', null, 'Статуя богини, которая была создана древним скульптором Бероной в древние времена.', 'etc_holy_statue_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4350', 'The Work of the ancient sculptor Berona', null, 'Статуя, созданная древним скульптором Бероной. Еще не оценена антикварами.', 'etc_statue_of_einhasad_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4351', 'Ancient Statue of Goddess: Prototype', null, 'Статуя, созданная Бероной, древним скульптором, - опытный образец', 'etc_statue_of_einhasad_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4352', 'Ancient Statue of Goddess: Original', null, 'Статуя, созданная Бероной, древним скульптором, - оригинал.', 'etc_statue_of_einhasad_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4353', 'Ancient Statue of Goddess: Replica', null, 'Статуя, созданная современным скульптором, пытавшимся подражать Бероне.', 'etc_statue_of_einhasad_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4354', 'Ancient Statue of Goddess: Forgery', null, 'Подделка, созданная современным скульптором.', 'etc_statue_of_einhasad_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4355', 'Blue Eva', null, 'Особая монета.', 'etc_magic_coin_blue_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4356', 'Gold Einhasad', null, 'Особая монета.', 'etc_magic_coin_gold_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4357', 'Silver Shilen', null, 'Особая монета.', 'etc_magic_coin_silver_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4358', 'Bloody Pa\'agrio', null, 'Особая монета.', 'etc_magic_coin_blood_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4359', 'Barrel of Liquor', null, 'Очень тяжелая бочка, до краев наполненная восхитительным и ароматным ликером.', 'etc_wine_barrel_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4360', 'Precious Scarab', null, 'Прозрачный и сияющий скарабей. Можно продать по высокой цене.', 'etc_beetle_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4361', 'Simbelmyne', null, 'Любимый цветок Эльфов, который, как полагают, может лечить болезни.', 'etc_flower_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4362', 'Odd (looking) Doll', null, 'Странная статуя живого существа, похожего на беса. Любимый предмет Орков.', 'etc_totem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4363', 'Scarlet Dress', null, 'Очень красивое красное платье аденского стиля, сшитое для благородных леди.', 'etc_ladys_dress_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4364', 'Nebulite Orb', null, 'Кусок небулита сферической формы. Отнесите его Магическому Торговцу Семе в Академию Хардина.', 'etc_crystal_ball_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4365', 'Ectoplasm Liqueur', null, 'Экзотический ликер, приготовленный из эктоплазмы. Очень популярен среди ценителей.', 'etc_dragon_blood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4366', 'Prince\'s Trophy', null, 'Трофей, который принц Мальком выиграл на танцевальном турнире. Вы можете продать его в магазин или сохранить как сувенир.', 'etc_trophy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4367', 'Prince\'s Autobiography', null, 'Автобиография принца Малькома с его личной подписью. Можно продать в Торговой Лавке.', 'etc_spellbook_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4368', 'Prince\'s Bust', null, 'Статуя принца Малькома, сделанная из чистого золота. Весьма уродливая, но дорогая.', 'etc_holy_statue_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4369', 'Silk Handkerchief', null, 'Красивый носовой платок, украшенный цветочным узором и кружевами.', 'etc_kerchief_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4370', 'Luxurious Goblet', null, 'Роскошный кубок, созданный в период Империи Эльмореден.', 'etc_holy_grail_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4371', 'Scepter of Darkness', null, 'Скипетр, который излучает темную силу. На его ручке выгравировано: \"Великий Король Демонов\".', 'etc_imperial_scepter_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4372', 'Succubus Perfume', null, 'Духи, используемые дворянками Суккубов. Имеют очень сильный аромат, неприятный для Эльфов и Людей.', 'etc_dragons_blood_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4373', 'Succubus Mirror', null, 'Зеркало, используемое дворянками Суккубов, когда они наносят косметику.', 'etc_mirror_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4374', 'Heart of Darkness', null, 'Сердцевидный камень, который излучает темную силу. На нем выгравировано: \"Я люблю тебя, Меркенис!\".', 'etc_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4375', 'Royal Orc Totem', null, 'Тотем, сделанный из цельного куска красного гранита.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4376', 'Pearl Trodden/Trampled By A Wild Hog', null, 'Бусинка размером с грецкий орех, заляпанная грязью. Возможно, это жемчуг.', 'etc_crystal_ball_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4377', 'Boar\'s Tusk', null, 'Клык борова, похожий на бивень слона.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4378', 'Sweet Potato', null, 'Большая картошка, которую только что вытащили из земли. Поджарьте ее, и она станет очень вкусной.', 'etc_seed_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4379', 'Beast\'s Claws', null, 'Острые когти белого льва. По слухам, высоко ценятся среди коллекционеров.', 'etc_fang_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4380', 'Beast\'s Mane', null, 'Грива белого льва. По слухам, высоко ценится среди коллекционеров.', 'etc_metallic_fiber_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4381', 'Ginseng Root', null, 'Редкий медицинский препарат, изготавливаемый где-то далеко на востоке.', 'etc_ginseng_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4382', 'Honey Jar', null, 'Банка, содержащая сладкий мед.', 'etc_oil_pot_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4383', 'Bear\'s Gall', null, 'Желчь медведя, которая, как известно, очень эффективна для поддержания здоровья и хорошего самочувствия, так как обладает мистическими лечебными свойствами.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4384', 'Fresh Samon', null, 'Свежепойманный лосось.', 'etc_fish_seawater_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4385', 'Sushi Riceball', null, 'Суши из Шутгарта. Обладает восхитительным вкусом.', 'etc_meat_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4386', 'Avellan Spice', null, 'Экзотическая специя, которую привезли из Авеллы на востоке.', 'etc_powder_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4387', 'Lucky Rabbit Weed', null, 'Сорняк, который, как говорят, приносит удачу. Излюбленная пища кроликов.', 'etc_herb_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4388', 'Malcom\'s Check', null, 'Чек на большую сумму, подписанный принцем Малькомом. Может быть обналичен в хранилище Гирана.', 'etc_paper_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4389', 'Deposit Box Key', null, 'Ключ от частного сейфа в хранилище Гирана.', 'etc_old_key_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4390', 'Dwarven Royal Seal', null, 'Королевская печать, сделанная из нефрита. На ней выгравирована эмблема королевской семьи Гномов.', 'etc_royal_seal_of_lord_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4391', 'Dwarven Royal Crown', null, 'Золотая королевская корона. На ней выгравирована эмблема королевской семьи Гномов.', 'etc_ancient_crown_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4392', 'Dwarven Dance Manual', null, 'Учебник по танцам. С его помощью Вы легко сможете достичь вершин танцевального искусства!', 'etc_spellbook_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4393', 'Calculator', null, 'Позволяет выполнять простые вычисления.', 'etc_calculator_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4394', 'Hanellin\'s White Flower', null, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Желтый и Красный Цветки Ханелин.', 'etc_flower_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4395', 'Hanellin\'s Red Flower', null, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Белый и Желтый Цветки Ханелин.', 'etc_flower_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4396', 'Hanellin\'s Yellow Flower', null, 'Знак Ханелин. Отправляйтесь к ней в Аден вместе со своими товарищами, у которых есть Белый и Красный Цветки Ханелин.', 'etc_flower_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4397', 'Book of Saint', null, 'Книга Святого Солина. Отнесите это Магистру Ханелин вместе с Кровью Святого и Ветвью Святого.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4398', 'Blood of Saint', null, 'Кровь Святого Солина в стеклянной бутылке. Отнесите это Магистру Ханелин вместе с Книгой Святого и Ветвью Святого.', 'etc_dragons_blood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4399', 'Bough of Saint', null, 'Скипетр Святого Солина. Выглядит как обычная сухая ветка дерева. Отнесите это Магистру Ханелин вместе с Книгой Святого и Кровью Святого.', 'etc_branch_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4400', 'White Fabric', null, 'Большое полотно белой ткани, полученное у Магистра Ханелин. Она расскажет Вам, что делать дальше.', 'etc_piece_of_cloth_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4401', 'Green Dimensional Stone', null, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 1~3 этажи Башни Дерзости.', 'etc_gem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4402', 'Blue Dimensional Stone', null, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 4~6 этажи Башни Дерзости.', 'etc_gem_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4403', 'Red Dimensional Stone', null, 'Камень, активирующий пространственный вихрь, с помощью которого можно переместиться на 7~10 этажи Башни Дерзости.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4404', 'Green Dimensional Stone - Shard', null, 'Осколок Зеленого Камня Иных Миров. Соберите их и отнесите Исследователю Каплану.', 'etc_broken_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4405', 'Blue Dimensional Stone - Shard', null, 'Осколок Синего Камня Иных Миров. Соберите их и отнесите Исследователю Окли.', 'etc_broken_crystal_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4406', 'Red Dimensional Stone - Shard', null, 'Осколок Красного Камня Иных Миров. Соберите их и отнесите Исследователю Питгону.', 'etc_broken_crystal_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4407', 'Bill of Iason Heine', null, 'Счет, который можно обменять на 1000 аден у Кузнеца Романа из Иннадрила. Также на него можно купить разные материалы.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4408', 'Musical Score - Theme of Love', null, 'Посмертно выпущенная музыкальная композиция Джиллиана. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4409', 'Musical Score - Theme of Battle', null, 'Музыкальная композиция военного марша пламени. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4410', 'Musical Score - Theme of Journey', null, 'Музыкальная композиция Барда Свена. Если отнести это композитору, то для Вас смогут сделать музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4411', 'Echo Crystal - Theme of Journey', null, 'Музыкальный кристалл, который играет музыку на тему путешествий. Исчезает после использования.', 'etc_echo_crystal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4412', 'Echo Crystal - Theme of Battle', null, 'Музыкальный кристалл, который играет музыку на тему сражений.', 'etc_echo_crystal_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4413', 'Echo Crystal - Theme of Love', null, 'Музыкальный кристалл, который играет музыку на тему любви. Исчезает после использования.', 'etc_echo_crystal_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4414', 'Echo Crystal - Theme of Solitude', null, 'Музыкальный кристалл, который играет музыку на тему одиночества. Исчезает после использования.', 'etc_echo_crystal_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4415', 'Echo Crystal - Theme of the Feast', null, 'Музыкальный кристалл, который играет музыку на тему фестиваля. Исчезает после использования.', 'etc_echo_crystal_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4416', 'Echo Crystal - Theme of Celebration', null, 'Музыкальный кристалл, который играет музыку на тему праздника. Исчезает после использования.', 'etc_echo_crystal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4417', 'Echo Crystal - Theme of Comedy', null, 'Музыкальный кристалл, который играет музыку на тему комедии. Исчезает после использования.', 'etc_echo_crystal_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4418', 'Musical Score - Theme of Celebration', null, 'Праздничная музыкальная композиция. Если отнести это композитору, то можно получить музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4419', 'Musical Score - Theme of Comedy', null, 'Веселая музыкальная композиция. Если отнести это композитору, то можно получить музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4420', 'Musical Score - Theme of Solitude', null, 'Музыкальная композиция, составленная Нанарин. Если отнести это композитору, то можно получить музыкальный кристалл.', 'etc_musical_note_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4421', 'Musical Score - Theme of the Feast', null, 'Музыкальная композиция, составленная Барбадо. Если отнести это композитору, то можно получить музыкальный кристалл.', 'etc_musical_note_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4422', 'Dragon Bugle of Wind', null, 'Горн для призыва Дракона Ветра. Питомец забирает часть опыта, заработанного хозяином.', 'etc_bugle_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('4423', 'Dragon Bugle of Star', null, 'Горн для призыва Дракона Звезд. Питомец забирает часть опыта, заработанного хозяином.', 'etc_bugle_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('4424', 'Dragon Bugle of Twilight', null, 'Горн для призыва Дракона Сумерек. Питомец забирает часть опыта, заработанного хозяином.', 'etc_bugle_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('4425', 'Penitent\'s Manacles', null, 'Тяжелые наручники для призыва Чревоугодника. Чревоугодник поглощает весь опыт призывателя. Питается пищей для волков.', 'etc_leash_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('4426', 'Manacles of Penitent', null, 'Кандалы, оставшиеся после исчезновения Чревоугодника. Для повторения квеста отнесите их Черному Судье.', 'etc_leash_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4427', 'Alligator Leather Belt', null, 'Ремень из кожи Аллигатора, сделанный Кожевником Версом.', 'etc_prefect_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4428', 'Blue Alligator Leather Belt', null, 'Ремень, сделанный Кожевником Версом. Изготовлен из кожи редкого Синего Аллигатора.', 'etc_prefect_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4429', 'Bejeweled Leather Belt', null, 'Ремень, сделанный Кожевником Версом. Изготовлен из кожи Драгоценного Аллигатора.', 'etc_prefect_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4430', 'Alligator Leather Purse', null, 'Сумочка из кожи Аллигатора, сделанная Кожевником Версом.', 'etc_handbag_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4431', 'Blue Alligator Leather Purse', null, 'Сумочка из кожи Синего Аллигатора, сделанная Кожевником Версом.', 'etc_handbag_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4432', 'Bejeweled Purse', null, 'Сумочка из кожи Драгоценного Аллигатора, сделанная Кожевником Версом.', 'etc_handbag_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4433', 'Elemental Stone Powder', null, 'Порошок из Камня Стихии, полученный из каменной статуи в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'etc_powder_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4434', 'Elemental Stone Shards', null, 'Осколки Камня Стихии, полученные из каменных статуй в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'etc_broken_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4435', 'Elemental Stone Lump', null, 'Кусок Камня стихии, полученный из каменных статуй в Забытом Храме. Можно продать в магазин или отдать Магистру Нелл.', 'etc_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4436', 'Bentley\'s Request', null, 'Просьба найти и вернуть нефритовые кристаллы от обитателей Волшебной Долины, таких, как Мара, Утопленница, Сатир и др..', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4437', 'Carson\'s Request', null, 'Просьба отобрать работы древнего скульптора Бероны у Крысолюдов Хатар и Фавнов Ванор, обитающих около Кладбища.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('4438', 'Knuckle Duster Edge', null, 'Основной материал, используемый Гномами для создания Кастета. Можно продать в Торговой Лавке.', 'etc_sword_body_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('4439', 'Avadon Shield Fragment', null, 'Основной материал, используемый Гномами для создания Щита Авадона. Можно продать в Торговой Лавке.', 'etc_plate_silver_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('4440', 'Recipe: Knuckle Duster', null, 'Только для Гномов. Рецепт создания Кастета. Требуется умение \"Создать Вещь\" 5-го уровня. Шанс создания: 100%.', 'etc_recipe_yellow_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('4441', 'Recipe: Avadon Shield', null, 'Только для Гномов. Рецепт создания Щита Авадона. Требуется умение \"Создать Вещь\" 6-го уровня. Шанс создания: 100%.', 'etc_recipe_red_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('4442', 'Lottery Ticket', null, 'Лотерейный билет из Адена, который можно обналичить в любом месте продажи лотерейных билетов. Выигрышные номера объявляются каждую субботу в 19:00. Кто не играет, тот не выигрывает! Удачи!', 'etc_lottery_card_i00', '13');
INSERT INTO `ghtweb_all_items` VALUES ('4443', 'Monster Race Ticket - Single', null, 'Выигрышный билет в одиночном забеге Ипподрома Монстров. Обналичивается в кассе ипподрома.', 'etc_ticket_i00', '14');
INSERT INTO `ghtweb_all_items` VALUES ('4444', 'Monster Race Ticket - Double', null, 'Выигрышный билет в двойном забеге Ипподрома Монстров. Обналичивается в кассе гонок.', 'etc_ticket_i00', '14');
INSERT INTO `ghtweb_all_items` VALUES ('4445', 'Dye of STR <Str+1 Con-3>', null, 'Краска СИЛ. Отдайте 10 флаконов этой краски Мастеру Татуировок, и Вы сможете получить татуировку, изменяющую Ваши характеристики. Требования: Все классы после 1-й смены профессии, недоступно после 2-й смены профессии.', 'etc_str_hena_i00', '9');
