INSERT INTO `ghtweb_all_items` VALUES ('5221', 'Seed: Chilly Cobol', null, 'Семя Холодного Кобола. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 29-39 уровней.', 'etc_cobol_seed_i00', '10');
