INSERT INTO `ghtweb_all_items` VALUES ('5701', 'Seed: Alternative Red Codran', null, 'Семя Нового Красного Кодрана. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 44-54 уровней.', 'etc_codran_seed_i00', '11');
INSERT INTO `ghtweb_all_items` VALUES ('5702', 'Seed: Alternative Sea Codran', null, 'Семя Нового Морского Кодрана. Для получения плода вживите его в монстра в районе Иннадрила. Наилучшего результата можно достичь, если персонаж и монстр 44-54 уровней.', 'etc_codran_seed_i00', '11');
INSERT INTO `ghtweb_all_items` VALUES ('5703', 'Lucky Charm', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем ниже 20-го уровня.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5704', 'Keshanberk*Keshanberk', null, null, 'weapon_dual_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('5705', 'Keshanberk*Damascus', null, 'При модификации парных мечей их Ф. Атк. увеличивается в большей степени, нежели у одноручного оружия или кастетов. При модификации на +4 и выше: Макс. HP +25%. Наносит дополнительный урон в PvP.', 'weapon_dual_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('5706', 'Damascus*Damascus', null, 'При модификации парных мечей их Ф. Атк. увеличивается в большей степени, нежели у одноручного оружия или кастетов. При модификации на +4 и выше: Точность +6. Наносит дополнительный урон в PvP.', 'weapon_dual_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('5707', 'Record of Seven Signs', null, 'Документ, используемый для изучения текущей ситуации о ходе борьбы за Семь Печатей.', 'etc_ssq_scroll_i00', '0');
