INSERT INTO `ghtweb_all_items` VALUES ('5803', 'Lucky Charm (D-Grade)', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 20-39-го уровней.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5804', 'Lucky Charm (C-Grade)', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 40-51-го уровней.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5805', 'Lucky Charm (B-Grade)', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 52-60-го уровней.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5806', 'Lucky Charm (A-Grade)', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 61-75-го уровней.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5807', 'Lucky Charm (S-Grade)', null, 'При смерти от босса штраф на смерть не накладывается. Может использоваться только персонажем 76-го уровня или выше.', 'etc_charm_of_luck_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5808', 'Party Mask', null, 'Модный аксессуар, с помощью которого можно подчеркнуть свою индивидуальность.', 'etc_party_mask_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5809', 'Spellbook: Aqua Splash', null, 'Книга, необходимая для изучения умения \"Всплеск Воды\". Профессия: Певец Заклинаний.Необходимый уровень: 58.', 'etc_spell_books_element_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5810', 'Spellbook: Rain of Fire', null, 'Книга, необходимая для изучения умения \"Огненный Дождь\". Профессия: Властитель Огня.Необходимый уровень: 58.', 'etc_spell_books_element_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5811', 'Spellbook: Mass Slow', null, 'Книга, необходимая для изучения умения \"Массовое Замедление\". Профессия: Некромант.Необходимый уровень: 62.', 'etc_spell_books_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5812', 'Spellbook: Servitor Empowerment', null, 'Книга, необходимая для изучения умения \"Помощь Слуге\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 52.', 'etc_spell_books_summon_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5813', 'Spellbook: Servitor Cure', null, 'Книга, необходимая для изучения умения \"Излечить Слугу\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 40.', 'etc_spell_books_summon_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5814', 'Spellbook: Servitor Blessing', null, 'Книга, необходимая для изучения умения \"Благословение Слуги\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 62.', 'etc_spell_books_summon_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5815', 'Spellbook: Wild Magic', null, 'Книга, необходимая для изучения умения \"Дикая Магия\". Профессии: Мудрец Евы, Мудрец Шилен.Необходимый уровень: 62.', 'etc_spell_books_assistance_i00', '0');
