INSERT INTO `ghtweb_all_items` VALUES ('5858', 'Blessed Scroll of Escape: Clan Hall', null, 'Магический свиток, с помощью которого можно переместиться в холл клана. Если у Вас нет холла клана, эффекта не будет.', 'etc_scroll_of_return_agit_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5859', 'Blessed Scroll of Escape: Castle', null, 'Магический свиток, с помощью которого можно переместиться в замок. Если у Вас нет замка, эффекта не будет.', 'etc_scroll_of_return_castle_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('5860', 'Lienrik Egg', null, 'Яйцо Аспида, которое запросил Руд, продавец Товаров для Питомцев.', 'etc_dragon_egg_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5861', 'Lienrik Egg', null, 'Блестящее красное яйцо Аспида. Похоже на то, что просил продавец Товаров для Питомцев Руд. Но что-то тут не так…', 'etc_dragon_egg_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5862', 'Stone of Contract', null, 'Чтобы завладеть силой Тьмы, необходимо получить право владения этим предметом. Отнесите его Торговцу Галману в Долину Драконов.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5863', 'Alligator Tooth', null, 'Острый зуб аллигатора. Отнесите его Рабочему Склада Клаку в Хейн.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5864', 'Mysterious Map Piece', null, 'Потемневший кусок бумаги. Возможно, это часть карты.', 'etc_map_piece_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5865', 'Carnivore Spore', null, 'Кусок кожи, собранный со Споровых Зомби в Море Спор. Используется Магистром Гейном в Башне Слоновой Кости.', 'etc_pouch_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5866', 'Herbivorous Spore', null, 'Образец спор, собранный с Трухлявого Дерева в Море Спор. Используется Магистром Гейном в Башне Слоновой Кости.', 'etc_pouch_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5867', 'Jade Crystal', null, 'Нефритовый кристалл, собранный в Волшебной Долине. Отнесите его Рабочему Склада Сильве в Деревню Охотников.', 'etc_gem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5868', 'Snake Scale', null, 'Чешуя змеи с тел Фалибати и Змеев Кочевников. Отнесите ее Великому Мастеру Олтлину в Аден.', 'etc_scale_of_medusa_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5869', 'Remains of Aden Residents', null, 'Останки жителей Адена, убитых в период войны Адена и Эльмора. Соберите 60 штук и отнесите их Верховному Жрецу Орвену.', 'etc_ashes_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5870', 'Receipt of Supply', null, 'Документ, собранный из обрывков. Отнесите его Стражу Колману.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5871', 'Suspicious Document Piece', null, 'Часть документа, содержащая подозрительную информацию. Если собрать 5 частей, можно расшифровать документ.', 'etc_piece_of_report_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5872', 'Supply Items', null, 'Припасы, полученные при убийстве поставщиков Орков Тайк. Отнесите их Стражу Колману за вознаграждение.', 'etc_squares_wood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5873', 'Pirate\'s Treasure Chest', null, 'Сундук с сокровищами, добытый у последователей Закена. Отнесите его Смотрителю Склада Рандольфу в Гиран.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5874', 'Sairon\'s Silver Hair', null, 'Волосы Сайрона. Отнесите их Магистру Диетеру в Гиран.', 'etc_pouch_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5875', 'Titan Lamp', null, 'Лампа, изобретенная Гигантами. Не горит.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5876', 'Titan Lamp', null, 'Лампа, изобретенная Гигантами. В ней теплится огонь.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5877', 'Titan Lamp', null, 'Лампа, изобретенная Гигантами. Горит.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5878', 'Titan Lamp', null, 'Лампа, изобретенная Гигантами. Горит.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5879', 'Titan Lamp', null, 'Лампа, изобретенная Гигантами. Горит ярким пламенем.', 'etc_bead_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5880', 'Broken Titan Lamp', null, 'Сломанная лампа Гигантов. Отнесите ее Лорейн.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5881', 'Blade Stakato Fang', null, 'Клык, отрезанный у Опасного Стакато. Отнесите его Жрице Евы Рестине в Хейн.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5882', 'Flare Shard', null, 'Пламенные осколки из Забытого Храма. Отнесите их Магистру Неллу в Деревню Глудин.', 'etc_echo_crystal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5883', 'Freezing Shard', null, 'Осколки льда из Забытого Храма. Отнесите их Магистру Неллу в Деревню Глудин.', 'etc_echo_crystal_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5884', 'Cave Beast Tooth', null, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5885', 'Death Wave Light', null, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'etc_crystal_ball_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5886', 'Sealed Mysterious Stone', null, 'Галька, светящаяся странной аурой. Дает слабое свечение.', 'etc_dragon_egg_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5887', 'Mysterious Stone', null, 'Галька, светящаяся странной аурой. Дает сильное свечение.', 'etc_dragon_egg_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5888', 'Karik Horn', null, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5889', 'Cave Howler Skull', null, 'Ингредиент, используемый Шаманами Орков в их ритуалах. Отнесите его Провидцу Манакия.', 'etc_skull_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5890', 'Mysterious Book', null, 'Книга, добытая в Пещере Гигантов. Она написана на древнем языке, который невозможно прочитать.', 'etc_spellbook_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5891', 'Ancient Language Dictionary: Basic Level', null, 'Простой словарь ученых древних времен. С его помощью можно прочитать некоторые тексты Гигантов.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5892', 'Ancient Language Dictionary: Intermediate Level', null, 'Словарь ученых древних времен. С его помощью можно прочитать некоторые тексты Гигантов.', 'etc_spellbook_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5893', 'Leaf of Eucalyptus', null, 'Один из ингредиентов для производства вина. Соберите 80 штук и отнесите Стражу Харлану в Дион.', 'etc_herb_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5894', 'Stone of Chill', null, 'Магический камень, используемый Шаманами Орков Энку для заклинаний льда. Соберите 100 штук и отнесите Стражу Харлану в Дион.', 'etc_crystal_ball_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5895', 'Ritron\'s Fruit', null, 'Фрукт с жесткой кожурой и приятным запахом. Соберите 4 штуки и отнесите Магистру Ролланту в Дион.', 'etc_cobol_i05', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5896', 'Moon Face Flower', null, 'Говорят, этот цветок распускается только в лунном свете. Соберите 20 штук и отнесите Магистру Ролланту в Дион.', 'etc_flower_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5897', 'Leech Fluids', null, 'Флюиды личинок, обитающих в Топи Крума. Соберите 10 штук и отнесите Магистру Ролланту в Дион.', 'etc_reagent_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5898', 'Royal Membership', null, 'Мечта всех нумизматов! Отнесите ее Главному Кузнецу Вергара.', 'etc_royal_membership_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5899', 'Kail\'s Coin', null, 'Монета, которой владел Волшебник Кайл, помогавший Белефу. Отнесите ее Смотрителю Склада Соринту.', 'etc_magic_coin_blood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5900', 'Coin Collecting Album', null, 'Альбом для монет высокого качества, сделан из кожи.', 'etc_magic_book_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5901', 'Blood Offering', null, 'Кровь Монстра Подношения. Количество этих предметов определит Ваш счет.', 'etc_dragon_blood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5902', 'Scroll of Ancient Magic', null, 'Свиток, содержащий древнюю магию. Отнесите его Хранителю Портала Зиккурату.', 'etc_scroll_of_enchant_weapon_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5903', 'Ancient Ash Urn', null, 'Древняя урна, найденная в Башне Дерзости. Отнесите ее Провидцу Реве в Аден.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5904', 'Wesley\'s Mixing Stone', null, 'Драгоценный камень, отданный Уэсли. Этот предмет нужен для использования смесительной урны.', 'etc_gem_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5905', 'Magister\'s Mixing Stone', null, 'Камень, активирующий смесительную урну в подвале Башни Слоновой Кости.', 'etc_gem_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5906', '5th Anniversary Gift Box (10 Honey Rice Cake Set)', null, 'Подарок в честь 5 годовщины L2. Содержит 10 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5907', '5th Anniversary Gift Box (9 Honey Rice Cake Set)', null, 'Подарок в честь 5 годовщины L2. Содержит 9 Сладких Лепешек и 1 Знак Lineage II. Нельзя обменять или выбросить, можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('5908', 'Red Soul Crystal: Stage 13', null, 'Красный кристалл, поглощающий души. Уровень 13. Наполнившись, дарует особые свойства оружию. 26 MP будет затрачено при каждом его применении. Кристалл этого уровня может самостоятельно поглощать души.', 'etc_soul_stone_i00', '1');
