INSERT INTO `ghtweb_all_items` VALUES ('6396', 'Amulet: Chant of Eagle', null, 'Амулет, необходимый для изучения умения \"Напев Орла\". Профессия: Вестник Войны.Необходимый уровень: 48.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6397', 'Amulet: Chant of Vampire', null, 'Амулет, необходимый для изучения умения \"Напев Вампира\". Профессия: Вестник Войны.Необходимый уровень: 44.', 'etc_orcish_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6398', 'Spellbook: Body of Avatar', null, 'Книга, необходимая для изучения умения \"Инкарнация Тела\". Профессия: Епископ.Необходимый уровень: 48.', 'etc_spell_books_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6399', 'Badge of Rabbit', null, 'Значок, который указывает, что ранг его обладателя - \"кролик\". Без этого значка нельзя доказать ранг.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6400', 'Badge of Hyena', null, 'Значок, который указывает, что ранг его обладателя - \"гиена\". Без этого значка нельзя доказать ранг.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6401', 'Badge of Fox', null, 'Значок, который указывает, что ранг его обладателя - \"лиса\". Без этого значка нельзя доказать ранг.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6402', 'Badge of Wolf', null, 'Значок, который указывает, что ранг его обладателя - \"волк\". Без этого значка нельзя доказать ранг.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6403', 'Star Shard', null, 'Фестиваль Звездного Света Ивент – подарок с неба. Если выбросить, он образует маленький взрыв. Может использоваться как компонент для создания других видов фейерверка.', 'etc_fairy_fire_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6404', 'Gunpowder', null, 'Фестиваль Звездного Света Ивент – Черный порошок. Компонент, использующийся для создания большего фейерверка.', 'etc_powder_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6405', 'Magnesium', null, 'Фестиваль Звездного Света Ивент – химический состав, который производит сильную вспышку. Необходим для создания большого фейерверка.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6406', 'Firework', null, 'Фестиваль Звездного Света Ивент – Взрывчатое устройство, которое блестяще освещает небо.', 'etc_small_ultra_bomb_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6407', 'Large Firework', null, 'Фестиваль Звездного Света Ивент – Большое взрывчатое устройство, которое загорается, чтобы осветить небо.', 'etc_ultra_bomb_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6408', 'Formal Wear', null, 'Одежда для свадеб. Выглядит как подвенечное платье для персонажей женского пола и как смокинг для персонажей мужского пола.', 'armor_t2000_ul_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6409', '2006 Battle Tournament - CP Potion', null, 'Восстанавливает СР на 200.', 'etc_cp_potion_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('6410', '2006 Battle Tournament - Quick Healing Potion', null, 'Магическое зелье, которое быстро восстанавливает НР. Однако его эффект не длителен.', 'etc_potion_gold_i00', '3');
