INSERT INTO `ghtweb_all_items` VALUES ('6643', 'Old Golden Spice', null, 'Пища для созданий с Фермы Зверей. Когда монстры, способные развиваться, потребляют эту пищу, это дает различный эффект. Как только монстр достигает определенного уровня развития, он становится питомцем. Еще эта пища заставляет монстров оставлять после смерти только адены и предметы.', 'etc_pouch_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6644', 'Old Crystal Spice', null, 'Пища для созданий с Фермы Зверей. Когда монстры, способные развиваться, потребляют эту пищу, это дает различный эффект. Как только монстр достигает определенного уровня развития, он становится питомцем. Еще эта пища заставляет монстров оставлять после смерти только очки опыта.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6645', 'Beast Soulshot', null, 'Призрачный свет благословляет питомца/слугу и временно повышает его силу атаки. Количество потребляемых зарядов души можно узнать в окне информации о питомце/слуге (используется в инвентаре хозяина).', 'etc_beast_soul_shot_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6646', 'Beast Spiritshot', null, 'Призрачный свет благословляет питомца/слугу и временно повышает его Маг. Атк. Количество потребляемых зарядов души можно узнать в окне информации о питомце/слуге (используется в инвентаре хозяина).', 'etc_beast_spirit_shot_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6647', 'Blessed Beast Spiritshot', null, 'Призрачный свет благословляет питомца/слугу и временно повышает его силу магической атаки. Количество потребляемых зарядов души можно узнать в окне информации о питомце/слуге (используется в инвентаре хозяина).', 'etc_blessed_beast_spirit_shot_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6648', 'Baby Buffalo Panpipe', null, 'Свирель для призыва Детеныша Буйвола. Он будет отбирать 5% опыта призывателя.', 'etc_buffalo_panpipe_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('6649', 'Baby Cougar Chime', null, 'Свирель для призыва Детеныша Кугуара. Он будет отбирать 5% опыта призывателя.', 'etc_cougar_chime_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('6650', 'Baby Kookaburra Ocarina', null, 'Свирель для призыва Детеныша Кукабарры. Он будет отбирать 5% опыта призывателя.', 'etc_kukaburo_ocarina_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('6651', 'Noblesse Gate Pass', null, 'Свидетельство, которое в настоящее время не используется. Покупается в магазинах.', 'etc_nobless_teleport_coupon_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6652', 'Scroll: Protection of Valakas', null, 'Увеличивает сопротивление к Атакам Валакаса передними лапами.', 'etc_blesscharm_ward_val_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('6653', 'Scroll: Flames of Valakas', null, null, 'etc_aidcharm_cancel_deathfire_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('6654', 'Scroll: Flames of Valakas', null, 'Снимает аномальное состояние, вызванное огненным дыханием Валакаса.', 'etc_aidcharm_cancel_valbreath_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('6655', 'Scroll: Slay Valakas', null, 'Увеличивает вашу Физ. Атк. В битве против Валакаса.', 'etc_blesscharm_slay_val_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('6656', 'Earring of Antharas', null, 'Дает следующие эффекты: MP +37, увеличение сопротивления кровотечению на 40%, увеличение шанса вызвать кровотечение цели на 40%, увеличение эффективности лечения, увеличение Ярости Вампира, увеличение сопротивления оглушению/аномальному состоянию на 30%, увеличение шанса вызвать оглушение/аномальное состояние цели на 30%, уменьшение расхода MP и увеличение сопротивления атакам земли. Если персонаж надевает две таких серьги, то эффект проявится только у одной из них.', 'accessory_earring_of_antaras_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6657', 'Necklace of Valakas', null, 'Дает следующие эффекты: MP +50, увеличение сопротивления к усыплению на 40%, HP +445, увеличение шанса усыпления на 40%, уменьшение времени отката умений, увеличение Физ. Атк. и Маг. Атк. эффект дикой магии, увеличение эффекта повреждения щита и увеличение сопротивления атакам огня.', 'accessory_necklace_of_valakas_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6658', 'Ring of Baium', null, 'Дает следующие эффекты: MP +21, увеличение сопротивления отравлению на 40%, увеличение шанса отравления на 40%, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления удержанию на 30%, увеличение шанса удержания на 30%, увеличение Скор. Атк. и Скор. Маг. Если персонаж надевает два таких кольца, то эффект проявится только у одного из них.', 'accessory_ring_of_baium_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6659', 'Earring of Zaken', null, 'Дает следующие эффекты: MP +31, увеличение сопротивления кровотечению на 30%, увеличение шанса вызвать кровотечение цели на 30%, увеличение эффективности лечения, эффект Ярости Вампира, увеличение сопротивления шоку/аномальному состоянию на 20%, увеличение шанса вызвать шок/аномальное состояние цели на 20%. Если персонаж надевает две таких серьги, то эффект проявится только у одной из них, а при ношении данной серьги вместе с Серьгой Бессмертного Закена применяются только эффекты последней.', 'accessory_earring_of_zaken_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6660', 'Ring of Queen Ant', null, 'Дает следующие эффекты: MP +21, увеличение сопротивления отравлению на 30%, увеличение шанса отравления на 30%, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления удержанию на 20%, увеличение шанса удержания на 20%. Если персонаж надевает два таких кольца, то эффект проявится только у одного из них.', 'accessory_ring_of_queen_ant_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('6661', 'Earring of Orfen', null, 'Дает следующие эффекты: MP +31, увеличение сопротивления кровотечению на 20%, увеличение шанса вызвать кровотечение цели на 20%, увеличение эффективности лечения. Если персонаж надевает две таких серьги, то эффект проявится только у одной из них.', 'accessory_earring_of_orfen_i00', '0');
