INSERT INTO `ghtweb_all_items` VALUES ('7150', 'Silver Spear', null, 'Награда, которая дана семье за высокие заслуги членом королевской семьи Эльмора. Декоративное копье, в бою бесполезно.', 'weapon_winged_spear_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7151', 'Suspicious Totem Doll', null, 'Кукла-тотем. Вы получили ее, охотясь на темных магов согласно инструкциям Служанки Лидии. Отнесите это к таинственному магу и задайте ему пару вопросов.', 'etc_totem_necklace_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7152', 'Flower Bouquet', null, 'Букет Цветов. Дориан просил, чтобы вы возложили его на могильном камне на юге.', 'etc_flower_bouquet_i01', '0');
