INSERT INTO `ghtweb_all_items` VALUES ('7528', 'Spinneret', null, 'Анатомическая структура паука с указанием, откуда берется паутина.', 'etc_squares_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7529', 'Investigative Report', null, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Магистром Джастином.', 'etc_spell_books_red_i00', '0');
