INSERT INTO `ghtweb_all_items` VALUES ('7533', 'Investigative Report', null, 'Документ, полученный от Торговца Информацией Миста. Содержит результаты расследования, запрошенного Верховным Жрецом Грегори.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7534', 'Ice Cold Flower', null, 'Ледяной Кристалл, завернутый в чешую рыбы, от которого веет холодом. Созданный рукой настоящего мастера, он похож на цветок.', 'etc_flower_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7535', 'Pure Ice', null, 'Кусок чистейшего льда, созданного из очищенной воды. Говорят, он содержит силу богов с самого сотворения мира.', 'etc_echo_crystal_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7536', 'Bitter Cold Beer', null, 'Пиво, которое запросил Кузнец Фейн. Одно прикосновение, и кажется, будто ваши пальцы замерзают.', 'etc_oil_pot_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7537', 'Multiple Course Meal', null, 'Изысканная пища, которую запросил Управляющий Арены. Говорят, ей питались дуэлисты с древних времен для повышения выносливости в бою.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7538', 'Dead Souls Fish Soup', null, 'Суп, который должен содержать все полезные вещества рыбы, из которой приготовлен. Согласно легенде, от типа рыбы зависит, будет ли съевший его больше или меньше.', 'etc_fish_seawater_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7539', 'Bitter Cold Vodka', null, 'Легендарный напиток, производимый из соединения огня и льда. Холодный на губах, он становится обжигающим в желудке.', 'etc_luxury_wine_c_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7540', 'Silver Crystal', null, 'Тип кристалла, хранящего свадебную музыку.', 'etc_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7541', 'Red Crystal', null, 'Тип кристалла, хранящего музыку на день рождения.', 'etc_crystal_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7542', 'Vampire\'s Heart', null, 'Сердце, вырванное из тела Вампира. Оно все еще бьется.', 'etc_bodypart_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7543', 'Zombie\'s Brain', null, 'Кусок мозга нежити из Леса Неупокоенных. Может содержать воспоминания о моменте смерти.', 'etc_bodypart_brain_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7544', 'Rib Bone of a Black Magus', null, 'Кость, оставшаяся на месте смерти Черного Мага. Возможно она использовалось для изменения внешнего вида Мага.', 'etc_rib_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7545', 'Zombie\'s Liver', null, 'Печень, продолжающая гнить и исторгать ужасающий запах. Известна как средоточие магических свойств нежити.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7546', 'Top Quality Meat', null, 'Кусок мяса высокого качества, полученный с туши зверя нужного возраста. С каждого зверя можно получить только один такой кусок.', 'etc_meat_of_monstereye_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7547', 'Young Wild Beast Meat', null, 'Кусок мяса, полученный с туши молодого зверя. Несмотря на приятный запах, его вкус недостаточно хорош.', 'etc_meat_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7548', 'Map Piece', null, 'Обрывок карты Монстроглаза', 'etc_map_piece_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7549', 'Yellow Map', null, 'Карта с обозначением следов монстров. Отнесите ее Капитану Наемников Софье.', 'etc_map_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7550', 'Map Piece', null, 'Обрывок карты, полученный с призраков в Землях Казненных.', 'etc_map_piece_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7551', 'Ivory Colored Map', null, 'Карта со странной информацией. Кстати, как-то недавно Торговец Галладучи жаловался, что до него не дошла одна из карт…', 'etc_map_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7552', 'Broken Gemstone Fragment', null, 'Кусок драгоценного камня, полученный с Ящера Мэль.', 'etc_broken_crystal_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7553', 'Gold Colored Gemstone', null, 'Сфера золотого цвета, которую ищет Верховный Жрец Дрикус.', 'etc_gem_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7554', 'Scroll of Escape: Talking Island Village', null, 'Магический свиток, с помощью которого можно переместиться на Говорящий Остров.', 'etc_scroll_of_return_i00', '0');
