INSERT INTO `ghtweb_all_items` VALUES ('7561', 'Fishing Manual', null, 'Руководство по технике рыбалки. Двойное нажатие позволит его прочитать.', 'etc_spellbook_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7562', 'Dimensional Diamond', null, 'Кристалл, наполненный магической силой. Необходим для телепортации. Вы можете обменять их у любого Хранителя Портала на Свитки Телепорта в различные города.', 'etc_gem_clear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('7563', 'Galladucci\'s Order (Document)', null, 'Документ с заказом Галадуччи. Отнесите его Торговцу Гентлеру в Лавку Магии.', 'etc_piece_of_paper_white_i00', '0');
