INSERT INTO `ghtweb_all_items` VALUES ('7985', 'Mercenary Posting Ticket (Teleporter3)', null, 'Позволяет телепортироваться во внешний двор замка, к западным воротам внешней части замка, на площадь или к стражам. Размещается в Руне внутри замка.', 'mticket_teleporter_fix_i00', '8');
INSERT INTO `ghtweb_all_items` VALUES ('7986', 'Mercenary Posting Ticket (Teleporter4)', null, 'Позволяет телепортироваться во внешний двор, в западную часть внешнего замка, к восточным воротам внешнего двора или к стражам. Размещается в Руне внутри замка.', 'mticket_teleporter_fix_i00', '8');
INSERT INTO `ghtweb_all_items` VALUES ('7987', 'Mercenary Posting Ticket (Teleporter5)', null, 'Позволяет телепортироваться во внешний двор, в западную часть внешнего замка, к восточным воротам внешнего двора или на площадь. Размещается в Руне внутри замка.', 'mticket_teleporter_fix_i00', '8');
INSERT INTO `ghtweb_all_items` VALUES ('7988', 'Greater Mercenary Posting Ticket (Sword/Stationary)', null, 'Руна/Мечники/Неподвижно. Используется, чтобы вызвать наемников. Недоступно, если Печатью Раздора владеют Мятежники Заката.', 'mticket_sword_fix_i00', '8');
