INSERT INTO `ghtweb_all_items` VALUES ('8030', 'Hot Spring Nectar', null, 'Используется во время сражения за Холл Клана Горячих Источников. Этот предмет может быть использован на Йети Горячих Источников. Не может быть обменян или выброшен.', 'etc_hot_spring_nectar_i00', '0');
