INSERT INTO `ghtweb_all_items` VALUES ('8034', 'Rainbow Springs Clan Hall War Decree', null, 'Это свидетельство позволяет принять участие в битве за Холл Клана Горячего Источника. Это награда за рыбалку в Годдарде.', 'etc_hs_agit_war_joining_certificate_i00', '0');
