INSERT INTO `ghtweb_all_items` VALUES ('8181', 'Academy Circlet', null, 'Диадема, которая выдается выпускникам Академии. При смерти персонажа 40~75 уровней снижает штраф на опыт на 50%. Можно повторно купить у кузнеца Глудио Пинтера.', 'accessory_academy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8182', 'Circlet of Rune', null, 'Розовая Диадема. Носится Лордом Замка Руна и членами клана, но не союзниками. Позволяет использовать Умения Резиденции. Нельзя обменять/выбросить.', 'accessory_pledge_cap1_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8183', 'Circlet of Schuttgart', null, 'Диадема Молота и Факела. Носится Лордом Замка Шутгарта и членами клана, но не союзниками. Позволяет использовать Умения Резиденции. Нельзя обменять/выбросить.', 'accessory_pledge_cap1_i07', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8184', 'Party Hat', null, 'Забавный головной аксессуар. Требует две ячейки головных уборов.', 'accessory_party_hat_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8185', 'Feathered Hat', null, 'Широкополая шляпа с пером. Требует две ячейки головных уборов.', 'accessory_archer_hat_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8186', 'Artisan\'s Goggles', null, 'Большие очки для защиты глаз. Требует две ячейки головных уборов.', 'accessory_dwarf_goggle_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8187', 'Demon Horns', null, 'Головной аксессуар для ивента Helloween 2006.', 'accessory_hair_cornu_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8188', 'Little Angel Wings', null, 'Головной аксессуар в виде маленького белого крыла.', 'accessory_hair_ring_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8189', 'Fairy Antennae', null, 'Миловидный головной аксессуар в виде антенок со звездочками.', 'accessory_hair_feeler_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8190', 'Demonic Sword Zariche', null, 'Смертоносный магический меч, сделанный Дьяволом Бремноном собственноручно. Всегда жаждет крови.', 'weapon_unique_zariche_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8191', 'Necklace of Frintezza', null, 'Увеличивает MP на 42. Увеличивает сопротивление к усыплению/параличу/шоку на 15%. Увеличивает шанс усыпления/паралича/шокирования цели на 15%. Увеличивает сопротивление к отравлению/кровотечению на 25%. Увеличивает шанс отравить/пустить кровь на 25%. Уменьшает время отката умений. Обладает эффектом отражения части урона. Увеличивает сопротивление тьме.', 'accessory_necklace_of_frintessa_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8192', 'Soul Breaking Arrow', null, 'Двойной щелчок по стреле временно прерывает музыкальную тему Фринтезы. Нельзя выбросить. Исчезает при входе в Пещеру Последнего Императора.', 'etc_destory_soul_arrow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8193', 'Fisherman\'s Potion - Green', null, 'Понижая уровень умения рыболовства это зелье позволяет поймать зеленую рыбу (уровень 1-3). Если использовать зелье, предназначенное для более высокого уровня рыболовства, то эффекта не последует.', 'etc_oblivion_green_i00', '0');
