INSERT INTO `ghtweb_all_items` VALUES ('8542', 'Newbie Travel Token', null, 'Этот значок помогает начинающим путешественникам бродить по различным местам. Персонажи до 20 уровня могут купить его в Гильдии Новичков для путешествия между Деревней Говорящего Острова, Деревней Темных Эльфов, Эльфийской Деревней, Деревней Гномов, Деревней Орков и Деревней Камаэль.', 'etc_coins_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8543', 'Bead Parcel', null, 'Отдайте эту посылку Начальнику Склада Яшени из Шутгарта.', 'accessary_mage_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8544', 'Timora Orc\'s Head', null, 'Отрезанная голова Орка Тиморы, предателя своего племени, который примкнул к Оркам Рагна.', 'etc_skull_red_i00', '0');
