INSERT INTO `ghtweb_all_items` VALUES ('8546', 'Horn of Baar Dre Vanul', null, 'Безупречно гладкий рог, добытый у Баала Дре Ванул, обитающего в южной части Плато Бессмертия.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8547', 'Old Box', null, 'Старая коробка, которую вы выудили во время рыбалки в Горячих Источниках. Если вы дважды щелкните по ней, то, возможно, получите Сертификат участия в войне за холл клана в Горячих Источниках.', 'etc_box_of_adventure_1_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8548', 'Hot Springs Lure', null, 'Наживка для ловли старой коробки в Горячих Источниках Годдарда. Уровень мастерства рыболовства: 20 и выше.', 'etc_bait_i02', '16');
