INSERT INTO `ghtweb_all_items` VALUES ('8554', 'Recipe: Red Mask of Victory (100%)', null, 'Доступно любой расе. Рецепт изготовления Маски Духов. Требует умения Создание Обычных Предметов 4 уровня.', 'etc_recipe_green_i00', '5');
