INSERT INTO `ghtweb_all_items` VALUES ('8556', 'Dewdrop of Destruction', null, 'Щелчок по Росе Разрушения приводит к исчезновению портрета. Нельзя выбросить, но при входе в Гробницу Последнего Императора исчезает сама по себе.', 'etc_lesser_potion_red_i00', '0');
