INSERT INTO `ghtweb_all_items` VALUES ('8616', 'Spellbook: Summon Friend', null, 'Книга, необходимая для изучения умения \"Призвать Друга\". Профессии: Колдун, Последователь Стихий, Последователь Тьмы.Необходимый уровень: 56.', 'etc_party_sommons_i00', '0');
