INSERT INTO `ghtweb_all_items` VALUES ('8618', 'Ancient Book: Divine Inspiration (Modern Language Version)', null, 'Возвращает забытые навыки. Эта книга была переиздана после перевода на современный язык. (Может использоваться только персонажами уровня 52 или выше.)', 'etc_add_buffslot_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8619', 'Ancient Book: Divine Inspiration (Original Language Version)', null, 'Возвращает забытые навыки. Эта книга была издана для древних учеников с обучающей целью. В ней содержится больше информации, чем в современной версии. (Может использоваться только персонажами уровня 61 или выше.)', 'etc_add_buffslot_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8620', 'Ancient Book: Divine Inspiration (Manuscript)', null, 'Возвращает забытые навыки. Это рукописная копия книги. По содержанию не отличается от оригинала. (Может использоваться только персонажами уровня 76 или выше.)', 'etc_add_buffslot_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8621', 'Ancient Book: Divine Inspiration (Original Version)', null, 'Возвращает забытые навыки. Кто не знает древний язык, тот ничего не поймет из этой книги. (Может использоваться только персонажами уровня 76 или выше.)', 'etc_add_buffslot_i03', '0');
