INSERT INTO `ghtweb_all_items` VALUES ('8778', 'Mantarasa Egg', null, 'Этот мистический предмет может лечить любые заболевания. Его можно добыть в Потерянном Гнезде на Первобытном Острове.', 'etc_dragon_egg_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8779', 'Ornithomimus Claw', null, 'Этот коготь динозавра нужен Шаману Элроки Каракавею для проведения особого ритуала.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8780', 'Deinonychus Bone Fragment', null, 'Обломок кости динозавра нужен Шаману Элроки Каракавею для проведения особого ритуала.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8781', 'Epitaph of Wisdom', null, 'Эта эпитафия может быть добыта из Чута Каиму Колонны Мудрости в Потерянном Гнезде.', 'etc_ancient_tablet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8782', 'Gazkh Fragment', null, 'Это обломок топора Газха, который Шилен дала воинам племени Элроки много лет назад.', 'etc_piece_of_gazk_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8783', 'Bone Powder', null, 'Этот прах древнего воина племени Элроки может быть получен после проведения мемориальной службы над Могилой Воина.', 'etc_powder_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8784', 'Gazkh', null, 'Этот древний топор, Газх, может быть восстановлен Каменной Статуей Шилен. Он необходим в битве с Сэйлреном.', 'etc_head_of_gazk_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('8785', 'Dinosaur Fang Necklace', null, 'Это ожерелье являлось знаком отличия древних членов племени Элроки, напавших на верфь.', 'etc_ketra_friendship_1_i00', '0');
