INSERT INTO `ghtweb_all_items` VALUES ('9135', 'A-/ S- Grade Item Set Box (Magic Use)', null, 'Щелкнув по предмету дважды, вы получите Магический Предмет Ранга S. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'etc_box_of_adventure_1_i00', '0');
