INSERT INTO `ghtweb_all_items` VALUES ('9138', 'Santa\'s Hat', null, 'Праздничная шапка Деда Мороза. Действует только до конца события. Требует две ячейки головных уборов.', 'accessory_santas_cap_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9139', 'Santa\'s Hat', null, 'Праздничная шапка Деда Мороза. Действует только до конца события.', 'accessory_santas_cap_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9140', 'Salvation Bow', null, 'Послать сердечко с любовью. Позволяет использовать активное умение Счастье. Предупреждение: если использовать это умение на монстра, он нападет на вас.', 'weapon_krono_bow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9141', 'Redemption Bow', null, 'Предмет ивента. Послать сердечко с любовью выбранному мутанту. Позволяет использовать Активные умения Выстрел в Сердце и Двойное Выстрел в Сердце.', 'weapon_krono_bow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9142', 'Apiga', null, 'Деньги проклятых созданий. Отдайте их в магическую лабораторию за вознаграждение.', 'etc_pig_adena_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9143', 'Golden Apiga', null, 'Редкие деньги проклятых созданий. В зависимости от их количества вы можете попытать счастья в лотерее. Нельзя обменять/выбросить.', 'etc_pig_adena_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9144', 'Pirate\'s Booty', null, 'Щелкнув по предмету дважды, вы получите шанс приобрести Золотую Апигу. Если вам не повезет, то вы не получите ничего. (Этот предмет можно использовать только в том случае, если вы загружены не более чем на 80% и имеете минимум 10 свободных ячеек в инвентаре.)', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9145', 'Little Angel Wings (Event)', null, 'Головной аксессуар в виде маленького белого крыла. Изготовлен специально для ивента, Нельзя обменять/выбросить.', 'accessory_hair_ring_i00', '0');
