INSERT INTO `ghtweb_all_items` VALUES ('9156', 'Blessed Scroll of Escape Event', null, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение. Награда за ивент.', 'etc_scroll_of_return_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('9157', 'Blessed Scroll of Resurrection Event', null, 'Магический свиток, воскрешающий мертвого персонажа с полным восстановлением очков опыта. Вознаграждение за ивент.', 'etc_scroll_of_resurrection_i01', '1');
