INSERT INTO `ghtweb_all_items` VALUES ('9568', 'Dark Energy', null, 'Инкрустированная в оружие, она увеличивает его атаку тьмы на определенный процент. Инкрустированная в броню, она увеличивает ее сопротивление свету на определенный процент. Может быть инкрустирована до 12-го уровня; ниже ее сила будет утрачена. Также возможно усиление до 3-х способностей при инкрустации в броню. Невозможно получение способностей, противоположных друг другу.', 'etc_crystal_ball_silver_i00', '25');
INSERT INTO `ghtweb_all_items` VALUES ('9569', 'Holy Energy', null, 'Инкрустированная в оружие, она увеличивает его атаку света на определенный процент. Инкрустированная в броню, она увеличивает ее сопротивление тьме на определенный процент. Может быть инкрустирована до 12-го уровня; ниже ее сила будет утрачена. Также возможно усиление до 3-х способностей при инкрустации в броню. Невозможно получение способностей, противоположных друг другу.', 'etc_crystal_ball_silver_i00', '25');
INSERT INTO `ghtweb_all_items` VALUES ('9570', 'Red Soul Crystal - Stage 14', null, 'Красный кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'etc_soul_stone_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('9571', 'Blue Soul Crystal - Stage 14', null, 'Синий кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'etc_soul_stone_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('9572', 'Green Soul Crystal - Stage 14', null, 'Зеленый кристалл, поглощающий души. Уровень 14. Наполнившись, дарует особые свойства оружию.', 'etc_soul_stone_i02', '1');
INSERT INTO `ghtweb_all_items` VALUES ('9573', 'Life Stone -  Level 80', null, 'Обычный минерал, окаменевший благодаря чьей-то физической или магической силе. Ключевой компонент для зачарования оружия для персонажей 80-го уровня и выше.', 'etc_mineral_general_i03', '0');
