INSERT INTO `ghtweb_all_items` VALUES ('9761', 'Frozen Cell Samples', null, 'Мастер Джастин просил это для изучения жизненной энергии.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9762', 'Orders', null, 'Эти приказы Гноллов можно найти в пустынном лагере. Собирайте их вместе с организационными структурами и отнесите Мастеру Камаэль Сионе.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9763', 'Organization Chart', null, 'Эти организационные структуры Гноллов можно найти в пустынном лагере. Собирайте их вместе с приказами и отнесите Мастеру Камаэль Сионе.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9764', 'Gobie\'s Orders', null, 'Основываясь на документах Гноллов, эти приказы описывают стратегию защиты от них. Отнесите Мастеру Камаэль Гоби.', 'etc_paper_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9765', 'Letter to the Humans', null, 'Это письмо написано союзниками людей из Камаэль, его нужно доставить Капитану Батису в Город Глудио.', 'etc_letter_envelope_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9766', 'Humans\' Reply', null, 'Это письмо от Капитана Батиса нужно доставить Мастеру Гоби.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9767', 'Letter to the Dark Elves', null, 'Письмо, написанное союзниками Темных Эльфов из Камаэль. Нужно доставить его Великому Мастеру Тобиасу в Глудио.', 'etc_letter_envelope_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9768', 'Dark Elves\' Reply', null, 'Письмо Великого Мастера Тобиаса, которое нужно доставить Мастеру Камаэль Гоби.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9769', 'Report to Sione', null, 'Этот доклад, написанный Гоби в связи с переговорами между Людьми и Темными Эльфами, нужно доставить Мастеру Сионе.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9770', 'Empty Soul Crystal', null, 'Офицер Гноллов Так может быть заточен в этот кристалл.', 'etc_bead_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9771', 'Tak\'s Captured Soul', null, 'Офицер Гноллов Так заточен в этот кристалл. Отдайте его Мастеру Гоби для допроса.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9772', 'Steelrazor Evaluation', null, 'Рекомендация \"Стилрейзора\", особого отряда Камаэль. Отдайте его любому Великому Мастеру Камаэль для смены профессии на Надзирателя.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9773', 'Enmity Crystal', null, 'Магистр Клейтон ищет этот материал. Если вы принесете ему достаточное количество, он вознаградит вас информацией.', 'etc_broken_crystal_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9774', 'Enmity Crystal Core', null, 'Этот магический предмет сделан из Кристалла Враждебности. Отдайте его Кузнецу Пойтану в Дионе.', 'etc_gem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9775', 'Manuscript Page', null, 'Хранитель Склада Хольвас ищет эти страницы. Соберите их и отдайте ему.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9776', 'Encoded Page on the Ancient Race', null, 'Зашифрованный документ о новых расах. По словам Хольваса, расшифровать его может Великий Мастер Камаэль Мельдина.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9777', 'Kamael Inquisitor Trainee Mark', null, 'Покажите это Сельсии, Начальнику Разведки Камаэль, и получите задание для смены профессии.', 'etc_jewel_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9778', 'Fragment of Attack Orders', null, 'Фрагмент приказа об атаке, взятого с тела убитого Грандиса. Соберите все фрагменты, чтобы узнать, кто отдал приказ об атаке.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9779', 'Grandis\' Attack Orders', null, 'Собранный приказ об атаке. Из его содержания ясно, что атака была спланирована Магистром Башни Слоновой Кости Гаюсом. Давайте-ка навестим Гаюса…', 'etc_map_piece_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9780', 'Manashen\'s Talisman', null, 'Обломки талисмана, добытые убийством Манашенов. Соберите все обломки и узнаете, кто управляет Манашенами.', 'etc_mark_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9781', 'Research on the Giants and the Ancient Race', null, 'Этот документ гигантов содержит информацию об исследованиях тайной расы. Он находился у миньона Белефа, Багровой Герцогини. Отдайте его Сельсии.', 'etc_spellbook_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9782', 'Kamael Inquisitor Mark', null, 'Знак, доказывающий, что Вы успешно прошли испытание Инквизитора. Покажите ее любому Великому Мастеру Камаэль, чтобы стать Арбалетчиком.', 'etc_jewel_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9783', 'Echo Crystal of Free Thought', null, 'Изначально этот кристалл принадлежал Матери всех Ведьм. Он может помочь ведьме вернуть утраченную память.', 'etc_echo_crystal_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9784', 'Parme\'s Letter', null, 'Письмо от Ведьмы Водного Дракона должно быть доставлено Жрецу Карнису.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9785', 'Refined Crystal Sample', null, 'Этот магический материал нужен Чародею, посланному в Башню Слоновой Кости для обозревания Острова Ада. Отдайте это ему и попробуйте с ним поговорить.', 'etc_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9786', 'Stabilized Ectoplasm', null, 'Этот материал нужен Хардину для изучения магии превращений. Доставьте это ему, чтобы помочь в его экспериментах.', 'etc_potion_clear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9787', 'Ectoplasm', null, 'Этот материал необходим для создания стабилизирующей эктоплазмы, которая используется в магии превращений.', 'etc_lesser_potion_clear_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9788', 'Hardin\'s Instructions', null, 'Эта инструкция по магии превращений написано Хардином. Ее нужно доставить Магистру Клейтону в Дион.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9789', 'Glass Jaguar Crystal', null, 'Один из материалов, о которых говорил Хардин. Доставьте его Магистру Клейтону.', 'etc_oriharukon_ore_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9790', 'Blank Sealbook', null, 'Пустая запечатанная книга, в которой можно хранить силу магии превращений. Отнесите ее Хардину.', 'etc_spell_books_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9791', 'Transformation Sealbook: Onyx Beast', null, 'Запечатанное письмо, содержащее силу магии превращений. Если вы отдадите его Магу Превращений на 2-м этаже Башни Слоновой Кости, то он сможет превратить вас.', 'BranchSys2.etc_sb_transform_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9792', 'Warehouse Manifest', null, 'Отчет о материалах, хранящихся на складе Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'etc_paper_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9793', 'Grocery Store Manifest', null, 'Отчет о товарах в торговой лавке Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9794', 'Weapon Shop Manifest', null, 'Отчет о запасах оружия в магазине Деревни Камаэль. Отдайте его Снабженцу Маркелле.', 'etc_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9795', 'Supply Report', null, 'Отчет Снабженца Маркеллы. Нужно доставить его Помощнику Иерарха Кэске.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9796', 'Hills of Gold Monster Claw', null, 'Коготь монстра, найденного в Золотых Холмах. Отдайте его Снабженцу Маркелле.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9797', 'Dungeon Leader Mark', null, 'Знак отличия лидера монстров, обитающих в подземелье. Доставьте его Управляющему Крепости Тюремного Лагеря Монстров.', 'etc_plan_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9798', 'Fragment of the Dungeon Leader Mark', null, 'Обломок знака отличия лидера монстров, обитающих в Подземелье. Доставьте его Управляющему Крепости Тюремного Лагеря Монстров.', 'etc_plan_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9799', 'Wolf Tail', null, 'Этот хвост покрыт роскошным мехом.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9800', 'Ranku\'s Blueprint', null, 'Чертеж, принадлежащий Ранку. Отнесите его Мэтресу.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9801', 'Demon Prince\'s Blueprint', null, 'Чертеж, принадлежащий Принцу Демонов. Отнесите его Мэтресу.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9802', 'Safe Key', null, 'Ключ, изготовленный Кузнецом Ноэлем, нужно отдать Начальнику Склада Моне.', 'etc_old_key_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9803', 'Sealed Document', null, 'Документ, предназначенный для Помощника Иерарха Кэски.', 'etc_roll_of_paper_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9804', 'Wyrm Heart', null, 'Сердце Змея, о котором просил Кекропус.', 'etc_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9805', 'Kekropus\' Recommendation', null, 'Рекомендательное письмо от Кекропуса. Отнесите его Битусу в Гиран.', 'etc_roll_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9806', 'Soul Breaker Certificate', null, 'Свидетельство Палача. Покажите его любому Великому Мастеру, чтобы стать Палачом.', 'etc_roll_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9807', 'Wolf Tail', null, 'Хвост волка, о котором просил Перван.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9808', 'Muertos Claw', null, 'Коготь, полученный при убийстве Муэрто. Соберите 10 таких и отдайте Кекропусу.', 'etc_fang_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9809', 'Grey Keltir Tooth', null, 'Клык монстра. Отнесите его Зверолову Виксону.', 'etc_fang_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9810', 'Black Wolf Tooth', null, 'Клык монстра. Отнесите его Зверолову Виксону.', 'etc_fang_ivory_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9811', 'Fortress Certificate', null, 'Используйте это для получения припасов у Надзирателя Тюремного Лагеря.', 'etc_lesser_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9812', 'Castle Certificate', null, 'Используйте это для получения припасов у Надзирателя Тюремного Лагеря.', 'etc_lesser_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9813', 'Orc Officer', null, null, 'weapon_monster_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('9814', 'Memento Mori', null, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'etc_raid_a_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9815', 'Dragon Heart', null, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'etc_raid_b_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9816', 'Earth Egg', null, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'etc_raid_c_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9817', 'Nonliving Nucleus', null, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'etc_raid_d_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9818', 'Angelic Essence', null, 'Добывается у Рейдового Босса. Этот Кристалл Жизни можно обменять на что-нибудь полезное.', 'etc_raid_e_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9819', 'Combat flag', null, 'Этот флаг нужно повесить на флагшток во время Битвы за Крепость. Вы не можете атаковать и использовать атакующие умения, когда несете его, но можете использовать умения флага.', 'weapon_fort_flag_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9820', 'Shadow Item: Clan Oath Helm', null, 'Теневой предмет заключает в себе отраженную мощь Шлема Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'armor_helmet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9821', 'Shadow Item: Clan Oath Armor', null, 'Теневой предмет заключает в себе отраженную мощь Доспеха Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'armor_t1001_ul_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9822', 'Shadow Item: Clan Oath Gauntlets', 'Heavy Armor', 'Теневой предмет содержит в себе отраженную мощь Рукавиц Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'armor_t1001_g_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9823', 'Shadow Item: Clan Oath Sabaton', 'Heavy Armor', 'Теневой предмет содержит в себе отраженную мощь Солеретов Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'armor_t1001_b_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9824', 'Shadow Item: Clan Oath Brigandine', null, 'Теневой предмет содержит в себе отраженную мощь Панциря Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'armor_t1002_ul_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9825', 'Shadow Item: Clan Oath Leather Gloves', 'Light Armor', 'Теневой предмет содержит в себе отраженную мощь Кожаных Перчаток Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'armor_t1002_g_i00', '0');
