INSERT INTO `ghtweb_all_items` VALUES ('9827', 'Shadow Item: Clan Oath Aketon', null, 'Теневой предмет содержит в себе отраженную мощь Накидки Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить. Полный доспех, который могут использовать только члены и выпускники Академии.', 'armor_t1003_ul_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('9828', 'Shadow Item: Clan Oath Padded Gloves', 'Robe', 'Теневой предмет содержит в себе отраженную мощь Пластинчатых Перчаток Клятвы. Нельзя обменять, выбросить, кристаллизовать и улучшить.', 'armor_t1003_g_i00', '0');
