INSERT INTO `ghtweb_all_items` VALUES ('10114', 'Sealed Dynasty Sigil Piece', null, 'Основной материал, используемый Гномами для создания Запечатанного Символа Династии. Можно продать в Торговой Лавке.', 'etc_plate_silver_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('10115', 'Recipe: Sealed Dynasty Sigil (60%)', null, 'Только для Гномов. Рецепт создания Запечатанного Символа Династии. Требуется умение \"Создать Вещь\" 9-го уровня. Шанс создания: 60%.', 'etc_recipe_black_i00', '5');
