INSERT INTO `ghtweb_all_items` VALUES ('10117', 'Chaotic Sealed Dynasty Sigil', null, 'Редкий предмет, Запечатанный Символ Династии, нуждается в полировке. Можно полировать у Кузнеца Маммона.', 'armor_dynasty_sigil_i01', '0');
