INSERT INTO `ghtweb_all_items` VALUES ('10129', 'Scroll of Escape: Fortress', null, 'Магический свиток, с помощью которого можно переместиться в крепость. Если у Вас нет крепости, Вы переместитесь в ближайшее поселение.', 'etc_scroll_of_return_castle_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10130', 'Blessed Scroll of Escape: Fortress', null, 'Магический свиток, с помощью которого можно быстро переместиться в крепость.', 'etc_scroll_of_return_castle_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10131', 'Transformation Scroll: Onyx Beast', null, 'Свиток, превращающий вас на 30 минут в Ониксового Зверя.', 'etc_scroll_white_i00', '1');
