INSERT INTO `ghtweb_all_items` VALUES ('10139', 'Agathion Bracelet', null, 'Браслет для призыва Агатиона Радужного Холла Клана. Теневой предмет, который Нельзя обменять/выбросить. Эффект длится 700 мин.', 'etc_rbracelet_aga_agit_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10140', 'Blessed Ring of Escape', null, 'Благословенный свиток Возврата, доступен в течение 120 мин. Время перезарядки: 60 секунд. Эффект не суммируется с дополнительными кольцами такого же типа.', 'accessary_ring_of_mana_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10141', 'Grey Talisman - Yeti Transform', null, 'Может на время превратить вас в Йети. При снятии предмета трансформация отменяется. Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'etc_talisman_i07', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10142', 'Grey Talisman - Buffalo Transform', null, 'Может на время превратить вас в Буйвола. При снятии предмета трансформация отменяется. Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'etc_talisman_i07', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10143', 'Battleground Spell - Shield Master', null, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Благословения Щита Ур. 6 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10144', 'Battleground Spell - Wizard', null, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Проницательности Ур. 1 и Воодушевления Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10145', 'Battleground Spell - Healer', null, 'Эффекты Легкой Походки Ур. 2, Шита Ур. 3, Магического Барьера Ур. 2, Проницательности Ур. 1 и Воодушевления Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10146', 'Battleground Spell - Dagger Master', null, 'Эффекты Легкой Походки Ур. 2, Могущества Ур. 3, Магического Барьера Ур. 2, Фокусировки Ур. 1 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10147', 'Battleground Spell - Bow Master', null, 'Эффекты Легкой Походки Ур. 2, Могущества Ур. 3, Магического Барьера Ур. 2, Наведения Ур. 1 и Ускорения Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10148', 'Battleground Spell - Berserker', null, 'Эффекты Духа Берсерка Ур. 2 и Чистоты Ур. 1 могут быть получены на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_scroll_white_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10149', 'Battleground Blessed Scroll of Escape', null, 'Магический свиток, с помощью которого можно переместиться в ближайшее поселение. Используется только при осаде или битве за Крепость.', 'etc_scroll_of_return_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10150', 'Battleground Blessed Scroll of Resurrection', null, 'Воскрешает мертвого персонажа и полностью восстанавливает его опыт. Используется только при Осаде или Битве за Крепость.', 'etc_scroll_of_resurrection_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10151', 'Battleground Transform Spell', null, 'При использовании превращает вас в Фею на определенное время. Можно использовать только на поле боя при Осаде или Битве за Крепость. Не действует, если вы уже превращены.', 'etc_trans_4f_s_b_01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10152', 'Battle Health Recovery Potion', null, 'При использовании восстанавливает HP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'etc_super_hp_potion_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('10153', 'Battle Mana Recovery Potion', null, 'При использовании восстанавливает MP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'etc_super_mp_potion_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('10154', 'Battle CP Recovery Potion', null, 'При использовании восстанавливает СP. Не действует на персонажей ниже 52 уровня. Используется только при Осаде или Битве за Крепость.', 'etc_super_cp_potion_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('10155', 'Mental Strengthening Potion', null, 'Увеличивает сопротивление удержанию и усыплению на определенный промежуток времени. Доступно только при Осаде и Воине за Крепость.', 'etc_lesser_potion_yellow_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10156', 'Medusa\'s Potion', null, 'Временно делает неуязвимым. Доступно только при Осаде и Воине за Крепость.', 'etc_lesser_potion_yellow_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10157', 'Instant Haste Potion', null, 'Немедленно увеличивает Скорость. Доступно только при Осаде и Воине за Крепость.', 'etc_lesser_potion_yellow_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10158', 'Grey Talisman of Upper Grade Fishing', null, 'Дарует Мастерство Рыболова высокого ранга (Ур.24). Эффект не сочетается с дополнительным талисманом аналогичного типа. Этот предмет нельзя продать или выбросить.', 'etc_talisman_i07', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10159', 'Capture Rope', null, 'Обездвиживает цель. Используется только при и Осаде или Битвы за Крепость.', 'etc_braided_hemp_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10160', 'Cursed Red Soul Crystal - Stage 14', null, 'Красный кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'etc_broken_crystal_red_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10161', 'Cursed Blue Soul Crystal - Stage 14', null, 'Синий кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'etc_broken_crystal_blue_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10162', 'Cursed Green Soul Crystal - Stage 14', null, 'Зеленый кристалл с проклятием тьмы, уровень 14. Отдайте его Легендарному Кузнецу Шадаи на Острове Ада для обработки.', 'etc_broken_crystal_green_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('10163', 'Wolf Collar', null, 'Ожерелье для призыва волков. Питомец забирает часть опыта, заработанного хозяином.', 'etc_prefect_belt_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('10164', 'Animal Slayer\'s List', null, 'Уничтожайте Багровых Пауков в Лесу Мимира.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10165', 'Bloody Red Claw', null, 'Окровавленный коготь. Соберите 50 таких и отдайте Мартину, Управляющему Питомцами Города Глудин.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10166', 'Hot Springs CP Potion', null, 'При использовании восстанавливает CP.', 'etc_hot_spring_mineral_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('10167', 'Pig Lollipop', null, 'Магический леденец с хрюшкой. Если использовать его для атаки, он будет визжать. На короткое время превращает персонажа в свинью. Этот предмет нельзя продать или выбросить, но можно положить на хранение. Памятный предмет 4-й годовщины игры.', 'etc_pig_candy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10168', 'Dynasty Leather Armor', 'Enchanter', 'Профессии: Апостол, Деспот, Глас Судьбы, Арбитр.', 'armor_t92_ud_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10169', 'Enchanter Circlet (Kamael only)', null, 'Только для Камаэль. Головной аксессуар для Зачарователей после 2-й или 3-й смены профессии. Нельзя носить в состоянии подкласса. Требует две ячейки головных уборов.', 'accessary_weapon_master_circlet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10170', 'Baylor\'s Earring', null, 'Сопротивление тьме +30, MP+31.', 'accessary_dynasty_earing_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10171', 'Seed: Dark Coda', null, 'Семя Темной Коды. Для получения плода вживите его в монстра в районе Адена. Наилучшего результата можно достичь, если персонаж и монстр 5-15 уровней.', 'etc_coda_seed_i00', '10');
