INSERT INTO `ghtweb_all_items` VALUES ('10175', 'Goblin Circlet (Event)', null, 'Диадема в форме гоблина золотого цвета. Этот предмет изготовлен только для ивента и не может быть обменян или выброшен.', 'accessory_taiwan_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10176', 'White Half Mask', null, 'Мистический аксессуар, закрывающий половину лица. Нельзя продать или выбросить.', 'accessory_half_face_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10177', 'Black Half Mask', null, 'Мистическая черная маска. Хотите знать, где ее вторая половина? Нельзя продать или выбросить. Памятный предмет 4-й годовщины игры.', 'Accessary_black_half_mask_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10178', 'Sweet Fruit Cocktail', null, 'Коктейль, приготовленный из редких фруктов, дарует временные эффекты Могущества, Щита, Легкой Походки, Фокусировки, Смертельного Шепота, Наведения, Благословения Щита, Благословения Тела, Ускорения и Ярости Вампира.', 'etc_fruit_cocktail_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10179', 'Fresh Fruit Cocktail', null, 'Коктейль, приготовленный из редких фруктов, дарует временные эффекты Духа Берсерка, Благословения Тела, Магического Барьера, Щита, Легкой Походки, Благословения Души, Воодушевления, Проницательности и Чистоты.', 'etc_fruit_cocktail_i01', '3');
