INSERT INTO `ghtweb_all_items` VALUES ('10327', 'Evil Weapon', null, 'Это оружие можно добыть только у злых духов, созданных в Литейной Монстров.', 'etc_sting_b_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10328', 'Stolen Cargo', null, 'Груз, украденный у Смотрителя Склада Сонина из Деревни Флоран. Возвращайтесь к Сонину.', 'etc_wine_barrel_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10329', 'Hate Crystal', null, 'Важный предмет, который требуется Бакалейщику Пано в Деревне Флоран.', 'etc_stone_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10330', 'Old Treasure Map', null, 'Важный предмет, который требуется Капитану Алексу в Деревне Флоран.', 'etc_map_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10331', 'Sonin\'s Credentials', null, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Пано и Алекса.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10332', 'Pano\'s Credentials', null, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Сонина и Алекса.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10333', 'Alex\'s Credentials', null, 'Отнесите это Жрецу Шегфилду в Деревню Дион вместе с грамотами Пано и Сонина.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10334', 'Badge - Temple Executor', null, 'Отнесите это Верховному Жрецу Сильвиану вместе со свидетельством Храма Эйнхасад и значком Миссионера Храма.', 'etc_jewel_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10335', 'Giants\' Experimental Tool Fragment', null, 'Реликвия Гигантов, найденная у монстров и отступников в Топях Крума. Отдайте ее Продавцу Книг Заклинаний Роуку.', 'etc_mechanic_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10336', 'Giants\' Experimental Tool', null, 'Созданные Гигантами инструменты для опытов. Можно использовать для приманки отступников в Топях Крумы.', 'etc_instrument_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10337', 'Giants\' Technology Report', null, 'Доказательство смерти предателя, убитого в Топях Крума. Отдайте Продавцу Книг Заклинаний Роуку.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10338', 'Rouke\'s Report', null, 'Отчет Роука. Отнесите его Жрице Гливке.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10339', 'Badge - Temple Missionary', null, 'Отнесите это Верховному Жрецу Сильвиану вместе со свидетельством Храма Эйнхасад и значком Палача Храма.', 'etc_jewel_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10340', 'Report Fragment', null, 'Фрагмент отчета об исследовании, принадлежавший пропавшему исследователю храма. Отдайте Верховному Жрецу Сильвиану.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10341', 'Temple Manifesto', null, 'Манифест Храма, описывающий только права.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10342', 'Relics of the Dark Elf Trainee', null, 'Вещь ученика Темных Эльфов, убитого во время тренировки. Отдайте Темному Эльфу Ангусу.', 'etc_oil_pot_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10343', 'Angus\' Recommendation', null, 'Значок, данный Ангусом в знак благодарности. Покажите его Жрице Пупине.', 'etc_paper_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10344', 'Pupina\'s Recommendation', null, 'Рекомендация, дающая право общаться с проповедниками. Покажите ее Проповеднику Сла.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10345', 'Records Chest Key Fragment', null, 'Обломок ключа Ящера Тасаба. Если вы отнесете его Смотрителю Склада Мии, она обменяет его на Ключ от Сундука с Записями.', 'etc_old_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10346', 'Records Chest', null, 'Ящик с Записями Ящера Тасаба. Отдайте его Смотрителю Склада Мии, чтобы посмотреть содержимое.', 'etc_squares_wood_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10347', 'Dark Crystal', null, 'Ингредиент для изготовления Темного Оксида. Отдайте мастеру Ксеновии.', 'etc_debris_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10348', 'Dark Oxide', null, 'Субстанция, необходимая Ксеновии для экспериментов.', 'etc_dragons_blood_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10349', 'Cryptogram of the Goddess Sword', null, 'Секретный документ сделки с Мечом Богини, который Ева, Богиня Озера, даровала Лионелю. Принесите его Рабочему Склада Клаку.', 'etc_plan_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10350', 'Predecessor\'s Report', null, 'Отчет об исследованиях, в котором описана смерть Сумрачного Лиса. Отдайте его Начальнику Склада Натулсу.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10351', 'Cryptogram of the Angel Search', null, 'Разметка местонахождения ангелов, открытых Исследовательским агентством Сумрачного Лиса. Зашифровано как Криптограмма. Расшифруйте ее с помощью Верховного Жреца Раймонда в Городе Глудио.', 'etc_piece_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10352', 'Prophecy Fragment', null, 'Пророчество – Путь Бога. Когда фрагменты пророчества будут собраны, они откроют вам местонахождение Падших Ангелов.', 'etc_piece_of_report_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10353', 'Fallen Angel Blood', null, 'Доказательство уничтожения падших Ангелов. Доставьте его Верховному Жрецу Раймонду.', 'etc_reagent_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10354', 'Sealed Prophecy - Path of the God', null, 'Запечатанное пророчество, рассказывающее о местонахождении ангела. Отнесите его Великому Мастеру Тобиасу в Глудио.', 'etc_spellbook_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10355', 'Prophecy - Path of the God', null, 'Запечатанное пророчество, рассказывающее о местонахождении ангела. Попросите Старейшину Казиана расшифровать его.', 'etc_spellbook_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10356', 'Empty Sound Crystal', null, 'Звуковой Кристалл для хранения послания ангелов. Пока на нем ничего не записано.', 'etc_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10357', 'Angel Medicine', null, 'Лекарство, сделанное Казианом для лечения ангела. Отдайте Падшему Ангелу.', 'etc_lesser_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10358', 'Angel\'s Message', null, 'Звуковой кристалл, хранящий послание ангела. Отнесите его Великому Мастеру Тобиасу в Глудио.', 'etc_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10359', 'Metallograph', null, 'Металлическое устройство, добытое в Башне Крума. Возможно, это записывающее устройство эпохи Гигантов.', 'etc_ancient_tablet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10360', 'Broken Metal Pieces', null, 'Обрывок карты, добытый в Башне Крума.', 'etc_broken_tablet_fragment_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10361', 'Nikola\'s Map', null, 'Карта, показывающая место, которое ищет Николя.', 'etc_painting_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10362', 'Loraine\'s Certificate', null, 'Свидетельство о получении Металлографа, который Лорейн добыла в Башне Крума. Сохраните его и возвращайтесь к ней позже.', 'etc_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10363', 'Metallograph', null, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство эпохи Гигантов.', 'etc_ancient_tablet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10364', 'Broken Metal Pieces', null, 'Обломки Металлографа, добытые в Башне Крума.', 'etc_broken_tablet_fragment_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10365', 'Nikola\'s Map', null, 'Карта, показывающая место, которое ищет Николя.', 'etc_painting_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10366', 'Metallograph - Research Report', null, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство, использующееся в Лаборатории Башни Крума.', 'etc_ancient_tablet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10367', 'Leto Lizardman Accessory', null, 'Украшение, которое носят Ящеры Лито. Оно нужно Торговцу Чертежами Луке.', 'etc_chain_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10368', 'Metallograph', null, 'Металлограф, добытый в Башне Крума. Должно быть, это записывающее устройство эпохи Гигантов.', 'etc_ancient_tablet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10369', 'Broken Metal Pieces', null, 'Обломки Металлографа, добытые в Башне Крума.', 'etc_broken_tablet_fragment_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10370', 'Metallograph - Decipher Pattern', null, 'Лука суммировал содержимое, списанное с металлической пластинки. Отдайте ее назад Лорейн.', 'etc_ssq_scroll_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10371', 'Repaired Metallograph', null, 'Дороти отремонтировала металлограф.', 'etc_broken_tablet_fragment_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10372', 'Red Stone', null, 'Предмет, который Мэтрес просил ему принести в качестве доказательства смерти монстров. О его истинном назначении он вам ничего не сказал.', 'etc_bead_red_i00', '0');
