INSERT INTO `ghtweb_all_items` VALUES ('10461', 'Icarus Stinger', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Зазубренного Меча Икара<Свойство Кристалла Души>Шанс Крит. Атк. увеличен на 111. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_icarus_stinger_i01', '6');
