INSERT INTO `ghtweb_all_items` VALUES ('10681', 'Naga Storm {PvP}', 'Back Blow', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 37 при атаке цели со спины. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_naga_storm_i01', '4');
