INSERT INTO `ghtweb_all_items` VALUES ('10700', 'Г‰clair Bijou {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры <Свойство Кристалла Души>Увеличивает Скор. Атк. на 6%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_greed_stinger_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('10701', 'Eclair Bijou {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры <Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_greed_stinger_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('10702', 'Eclair Bijou {PvP}', 'Critical Poison', 'Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры. <Свойство Кристалла Души>Дает 6% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_greed_stinger_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('10703', 'Durendal {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Ипоса. <Свойство Кристалла Души> Увеличивает шанс Крит. Атк. на 61. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_death_bringer_i00', '4');
