INSERT INTO `ghtweb_all_items` VALUES ('10746', 'Sarunga {PvP}', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Дракона<Свойство Кристалла Души> Уменьшает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_sarnga_i01', '5');
