INSERT INTO `ghtweb_all_items` VALUES ('10748', 'Sarunga {PvP}', 'Critical Slow', 'Эксклюзивное оружие Камаэль: Конверсия Лука Дракона. <Свойство Кристалла Души> Дает шанс наложить Замедление при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_sarnga_i01', '5');
INSERT INTO `ghtweb_all_items` VALUES ('10749', 'Tallum Blade*Dark Legion\'s Edge {PvP}', null, 'При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше Макс. HP увеличивает на 15% и Макс. MP увеличивает на 20% и Макс. CP увеличивает на 30%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'weapon_dual_sword_i00', '5');
