INSERT INTO `ghtweb_all_items` VALUES ('10866', 'Energy Ore', null, 'Энергетическая руда, обнаруженная в шахтах восточного региона. Используется в качестве ингредиента в преобразователе энергии, созданном Мару.', 'etc_crystal_white_i00', '0');
