INSERT INTO `ghtweb_all_items` VALUES ('10868', 'Helvetia\'s Antidote', null, 'Противоядие, купленное у Хельветии. Отдайте Марку', 'etc_potion_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10869', 'Contaminated Kasha Spider Venom', null, 'Яд Паука Кхаши создан Кхашей, злым духом разложения и смерти. Соберите яд и отнесите Торговцу Кунай', 'etc_potion_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('10870', 'Great Sword - Lightning', null, 'Редкий предмет, увеличивает шанс Крит. Атк.Дает возможность получить одно из следующих особых свойств: Здоровье, Крит. Урон или Фокусировка.', 'weapon_great_sword_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10871', 'Great Sword - Lightning', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%.', 'weapon_great_sword_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10872', 'Great Sword - Lightning', 'Critical Damage', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 247 при Крит. Атк.', 'weapon_great_sword_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10873', 'Great Sword - Lightning', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 68.', 'weapon_great_sword_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10874', 'Great Axe - Thunder', null, 'Редкий предмет, увеличивает силу Крит. Атк.Дает возможность получить одно из следующих особых свойств: Ярость Крит. Оглушение или Легкость.', 'weapon_great_axe_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10875', 'Great Axe - Thunder', 'Anger', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Уменьшает Макс. HP на 15%, и увеличивает Физ. Атк. на 28.', 'weapon_great_axe_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10876', 'Great Axe - Thunder', 'Critical Stun', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души> Дает 27% шанс колдовства Оглушение при Крит. Атк.', 'weapon_great_axe_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10877', 'Great Axe - Thunder', 'Light', 'Редкий предмет, увеличивает силу Крит. Атк.<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%.', 'weapon_great_axe_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10878', 'Sword of Limit*Sword of Limit - Destruction', null, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 127.', 'weapon_dual_sword_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10879', 'Sword of Limit*Sword of Delusion - Destruction', null, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Макс. HP на 25%.', 'weapon_dual_sword_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10880', 'Sword of Limit*Sword of Nightmare - Destruction', null, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 54.', 'weapon_dual_sword_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10881', 'Sword of Limit*Tsurugi - Destruction', null, 'Редкий предмет, увеличивает Физ. Атк.  При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Скор. Атк. на 5%.', 'weapon_dual_sword_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('10882', 'Innominate Victory - Lightning', null, 'Редкий предмет, увеличивает шанс Крит. Атк.Эксклюзивное оружие Камаэль: Большой Меч Дает возможность получить одно из следующих особых свойств: Здоровье, Крит. Урон или Фокусировка.', 'weapon_nameless_victory_i00', '3');
