INSERT INTO `ghtweb_all_items` VALUES ('12883', 'Г‰clair Bijou - Landslide {PvP}', 'Health', 'Редкий предмет, дает шанс оглушить при атаке.Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_greed_stinger_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('12884', 'Г‰clair Bijou - Landslide {PvP}', 'Critical Poison', 'Редкий предмет, дает шанс оглушить при атаке.Эксклюзивное оружие Камаэль: Конверсия Клинка Сирры<Свойство Кристалла Души>Дает 15% шанс отравить цель при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_greed_stinger_i01', '4');
