INSERT INTO `ghtweb_all_items` VALUES ('12888', 'Tallum Blade*Damascus - Landslide {PvP}', null, 'Редкий предмет, при атаке с определенной вероятностью оглушает цель.При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов повысится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Скор. Атк. на 8%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'weapon_dual_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('12889', 'Themis\' Tongue - Cleverness {PvP}', 'Mana Up', 'Редкий предмет, увеличивает скорость восстановления MР<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'weapon_tongue_of_themis_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('12890', 'Themis\' Tongue - Cleverness {PvP}', 'Mental Shield', 'Редкий предмет, увеличивает скорость восстановления MР.<Свойство Кристалла Души>Дает 50% шанс наложения Ментального Щита при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'weapon_tongue_of_themis_i01', '4');
INSERT INTO `ghtweb_all_items` VALUES ('12891', 'Themis\' Tongue - Cleverness {PvP}', 'Magic Focus', 'Редкий предмет, увеличивает скорость восстановления MР.<Свойство Кристалла Души>Дает 20% шанс наложения Фокусировки при использовании благотворного умения на цель. Наносит дополнительный урон в PvP, дает шанс повысить Скор. Маг., когда персонаж атакован.', 'weapon_tongue_of_themis_i01', '4');
