INSERT INTO `ghtweb_all_items` VALUES ('12940', 'Dynasty Knife - Great Gale {PvP}', 'Critical Damage', 'Редкий предмет, увеличивает Скор. Атк.<Свойство Кристалла Души>Увеличивает Физ. Атк. на 559 при Крит. Атк. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_dynasty_dagger_i01', '5');
INSERT INTO `ghtweb_all_items` VALUES ('12941', 'Dynasty Dual Sword - Earth {PvP}', null, 'Редкий предмет, увеличивает Макс. HP.При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 109 и Увеличивает Макс. HP на 10%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'weapon_dual_sword_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('12942', 'Dynasty Rapier - Earth {PvP}', 'Focus', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_dynasty_rapier_i01', '5');
INSERT INTO `ghtweb_all_items` VALUES ('12943', 'Dynasty Rapier - Earth {PvP}', 'Health', 'Редкий предмет, увеличивает Макс. HP.Эксклюзивное оружие Камаэль: Конверсия Меча Династии<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для вас и членов вашей группы.', 'weapon_dynasty_rapier_i01', '5');
