INSERT INTO `ghtweb_all_items` VALUES ('13740', 'Gludio Water Resistance Necklace', null, 'Ожерелье, которым награждается Хранитель Глудио. Защита от Воды +26. Нельзя обменять/выбросить.', 'accessary_inferno_necklace_i00', '0');
