INSERT INTO `ghtweb_all_items` VALUES ('13769', 'Artificial Regeneration Incubator', null, 'Устройство для создания макета, с помощью которого можно привлечь монстра, атакованного Колонией Гнилой Плоти. Можно использовать в подземелье Семени Бессмертия. Используется Подмастерьем, Ремесленником, Кузнецом, Мастером. Нельзя обменять/выбросить.', 'immo_lifeseed_decoy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13770', 'Shadow Item - Shield of Yehan Miakesh', null, 'Теневой предмет, защищающий от Света, принадлежал последнему герою древнего королевства Грация. Используется в сражении с монстрами Колонии Гнилой Плоти в Семени Бессмертия. Нельзя обменять, выбросить, улучшить или добавить дополнительные функции. Можно использовать только в подземелье Семени Бессмертия. Нельзя обменять, выбросить, кристаллизовать и улучшить. Профессии: Рыцарь Феникса, Рыцарь Ада, Храмовник Евы, Храмовник Шилен.', 'immo_branded_shield_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13771', 'Strong Alkaline Ointment', null, 'Мазь, прекрасно защищающая кожу от ожогов при работе с реагентами. Применяется для ослабления действия Отрицательных Эффектов. Применяется только в подземелье Коррозии.', 'etc_potion_of_acumen2_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13772', 'Life Aid Bandage', null, 'Бинт, прекрасно защищающий кожу от повреждений. Увеличивает защиту от Отрицательных Эффектов. Можно использовать только в подземелье Семени Бессмертия.', 'etc_piece_of_cloth_white_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13773', 'Scent of Preservation', null, 'Бальзам, используемый в древней Грации для сохранения останков. Быстро останавливает кровотечение. Можно использовать только в подземелье Семя Бессмертия.', 'etc_potion_red_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13774', 'Scent of Exorcism', null, 'Бальзам, используемый в древней Грации для лечения одержимых. Быстро нейтрализует действие сильных ядов. Можно использовать только в подземелье Семени Бессмертия.', 'etc_holy_grail_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('13775', 'Miracle Cure of Resuscitation', null, 'Эликсир, используемый в церемониях древней Грации. Быстро останавливает кровотечение, нейтрализует действие яда, ослабляет действие отрицательных эффектов. Используется только в подземелье Семени Бессмертия.', 'etc_cp_potion_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13776', 'Structure Scarab', null, 'Амулет, использовавшийся аристократами древней Грации. Способен воскресить персонажа. Используется только в подземелье Семени Бессмертия. Нельзя обменять/выбросить.', 'etc_beetle_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13777', 'Jewel Ornamented Duel Supplies', null, 'Сверкающая коробка. Уже по внешнему виду понятно, что в ней что-то есть.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13778', 'Mother-of-Pearl Ornamented Duel Supplies', null, 'Переливающаяся всеми цветами радуги коробка. Выглядит очень многообещающе.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13779', 'Gold-Ornamented Duel Supplies', null, 'На эту сияющую коробку больно смотреть. Даже если продать ее одну, можно получить много денег.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13780', 'Silver-Ornamented Duel Supplies', null, 'Коробка, на изготовление которой ушло много серебра. Поверхность сияет, словно зеркало.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13781', 'Bronze-Ornamented Duel Supplies', null, 'Коробка не выглядит ни ржавой, ни старой.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13782', 'Non-Ornamented Duel Supplies', null, 'Обычная коробка. Неизвестно, есть ли что-нибудь внутри.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13783', 'Weak-Looking Duel Supplies', null, 'Маленькая коробка, открыть которую не составит труда.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13784', 'Sad-Looking Duel Supplies', null, 'Маленькая коробка, в которой, кажется, нет ничего полезного.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13785', 'Poor-Looking Duel Supplies', null, 'При взгляде на эту старую коробку и в голову не придет, что внутри может храниться что-либо ценное.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13786', 'Worthless Duel Supplies', null, 'Коробка, которую даже не хочется открывать. Непонятно, зачем ее вообще сделали.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13787', 'Bond', null, 'Предмет используется для блокировки.', 'block_bond', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13788', 'Land Mine', null, 'Предмет используется для блокировки.', 'block_boom', '3');
INSERT INTO `ghtweb_all_items` VALUES ('13789', 'Red Boing Hammer', null, 'Предмет используется для выхода из блокировки.', 'weapon_bbyong_hammer_a_i00', '2');
INSERT INTO `ghtweb_all_items` VALUES ('13790', 'Blue Boing Hammer', null, 'Предмет используется для выхода из блокировки.', 'weapon_bbyong_hammer_b_i00', '2');
INSERT INTO `ghtweb_all_items` VALUES ('13791', 'Small Red Boing Hammer', null, 'Предмет используется для выхода из блокировки.', 'weapon_bbyong_hammer_c_i00', '2');
INSERT INTO `ghtweb_all_items` VALUES ('13792', 'Small Blue Boing Hammer', null, 'Предмет используется для выхода из блокировки.', 'weapon_bbyong_hammer_d_i00', '2');
INSERT INTO `ghtweb_all_items` VALUES ('13793', 'Kratei\'s Cube Name Hiding Scroll', null, 'Свиток, позволяющий скрыть свое имя во время битвы в Кубе Кратеи.', 'transform_towu_scroll_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13794', 'Transformed Object: Handy\'s Block Checker Transformation Scroll Blue', null, 'Свиток Трансформации для отмены блокировки.', 'block_scroll_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13795', 'Transformed Object: Handy\'s Block Checker Transformation Scroll Red', null, 'Свиток Трансформации для отмены блокировки.', 'block_scroll_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13796', 'Freed Soul', null, 'Особый предмет из Семени Бессмертия', 'freed_soul_essense_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13797', 'Tear of a Freed Soul', null, 'Пустая/Заряженная ценность Семени Бессмертия.', 'etc_madicine_bottle_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('13798', 'Portion of a Soul', null, 'Дополнительная ценность Семени Бессмертия.', 'soul_facet_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('13799', 'Treasure Sack of the Ancient Giants', null, 'Мешок, полный древних ценностей. Открывается двойным щелчком мыши.', 'BranchSys2.etc_ancient_treasure_sack_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13800', 'Transformation Scroll: Frog', null, 'Свиток Трансформации в лягушку. Выдан Секретным Агентом Коллином. Позволяет получить драгоценность от Короля Лягушек Озера Нарсилл.', 'etc_q_frog_green_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('13801', 'Transformation Scroll: Young Child', null, 'Свиток Трансформации в ребенка. Выдан Секретным Агентом Коллином. Позволяет получить сладости от Бабушки Тез Озера Нарсилл.', 'weapon_apprentices_rod_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('13802', 'Native\'s Hood', null, 'Капюшон аборигена, выданный Секретным Агентом Коллином. Надев капюшон, можно превратиться в аборигена и, поговорив с аборигеном Кудой, получить броню аборигена Озера Нарсилл.', 'armor_leather_helmet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13803', 'Native\'s Tunic', null, 'Куртка аборигена, выданная Секретным Агентом Коллином. Надев куртку, можно превратиться в аборигена и, поговорив с аборигеном Кудой, получить броню аборигена Озера Нарсилл.', 'armor_t34_u_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13804', 'Native\'s Trousers', null, 'Штаны аборигена, выданные Секретным Агентом Коллином. Надев штаны, можно превратиться в аборигена и, поговорив с аборигеном Кудой, получить броню аборигена Озера Нарсилл.', 'armor_t34_l_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13805', 'Guards of the Dawn Helmet', null, 'Шлем стражника, выданный Секретным Агентом Коллином. Надев его вместе со штанами и курткой стражника, можно превратиться в стражника.', 'armor_leather_helmet_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13806', 'Guards of the Dawn Tunic', null, 'Куртка стражника, выданная Секретным Агентом Коллином. Надев ее вместе со штанами и шлемом стражника, можно превратиться в стражника.', 'armor_t08_u_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13807', 'Guards of the Dawn Trousers', null, 'Штаны стражника, выданные Секретным Агентом Коллином. Надев их вместе со шлемом и курткой стражника, можно превратиться в стражника.', 'armor_t08_l_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13808', 'Elmoreden Holy Water', null, 'Святая Вода Эльморедена, выдаваемая стражником короля. Позволяет открыть дверь Некрополя, жара Лилим.', 'etc_holy_water_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('13809', 'Court Magician\'s Magic Staff', null, 'Волшебная палочка придворного волшебника. При наличии навыка отмены магии может открыть двери Некрополя Апостолов.', 'weapon_apprentices_rod_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13810', 'High Priest Orven\'s Letter', null, 'Письмо Верховного Жреца Орвена, рассказывающее о тяжелой ситуации в Грации. Нужно доставить командующему Кецерусу.', 'etc_letter_envelope_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13811', 'Keucereus\' Introduction - Seed of Infinity', null, 'Письмо Кецеруса для Офицера Тефиоса. Найдите его в Семени Бессмертия. Семя Бессмертия расположено на северо-западе от Базы Альянса Кецеруса.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13812', 'Keucereus\' Introduction - Seed of Destruction', null, 'Письмо Кецеруса для Сержанта Аленоса. Найдите его в Семени Бессмертия. Семя Бессмертия расположено на северо-западе от Базы Альянса Кецеруса.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13813', 'Croop\'s Introduction', null, 'Расписка Крупа. Нужно передать стражнику ворот Орена Гектору и отчитаться перед Джейкобом.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13814', 'Jacob\'s Necklace', null, 'Ожерелье, снятое с тела Джейкоба. Необходимо отдать Смотрителю Склада Орена Крупу.', 'accessary_necklace_of_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13815', 'Croop\'s Letter Requesting a Memorial Service', null, 'Просьба Крупа о погребении Джейкоба. Необходимо передать Верховному Жрецу Орена Холлинту.', 'etc_scroll_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13816', 'Deadman\'s Herb', null, 'Трава мертвых, собранная в Волшебной Долине. Нужно доставить жрецу Кейну в Орен.', 'etc_herb_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13817', 'Priest Cain\'s Investigation Report', null, 'Секретный доклад жреца Кейна. Необходимо доставить сэру Атебальту в Орене.', 'etc_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13818', 'Athebaldt\'s Introduction', null, 'Письмо сэра Атебальта. Необходимо доставить его к озеру Нарсилл и отдать секретному агенту Коллину.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13819', 'Native\'s Glove', null, 'Броня, полученная от аборигена Куды. Необходимо отнести Секретному Агенту Коллину.', 'armor_short_leather_gloves_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13820', 'Frog King\'s Bead', null, 'Драгоценность, полученная от Короля Лягушек. Необходимо отнести Секретному Агенту Коллину.', 'etc_crystal_ball_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13821', 'Grandma Tess\' Candy Pouch', null, 'Сладости, полученные от Бабушки Тез. Необходимо отнести Секретному Агенту Коллину.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13822', 'Guards of the Dawn Identity Card', null, 'Удостоверение, выданное госпожой Клаудией. Необходимо для того, чтобы пройти к секретному Оракулу Рассвета.', 'etc_royal_membership_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13823', 'Emperor Shunaiman\'s Contract', null, 'Контракт императора Шунаймана с торговцем Маммона. Необходимо передать госпоже Клаудии.', 'etc_crest_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13824', 'Ancient Seal Stone of Mammon', null, 'Древняя печать, полученная от торговца Маммона. Письмо о встрече с императором Шунайманом. Необходимо доставить госпоже Клаудии.', 'etc_water_rune_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13825', 'Grail of Einhasad', null, 'Снимает печать со всех Некрополей и Катакомб. Необходимо отнести императору Шунайману.', 'etc_holy_grail_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13826', 'Blood of the Emperor', null, 'Кровь императора, которая может запустить механизмы печати Некрополя. Используется на механизмах.', 'etc_lesser_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13827', 'Iason\'s Introduction', null, 'Письмо Ясона Хейна о встрече с Францем. Необходимо отнести Орвену, Верховному жрецу Орена.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13828', 'Prayer: Emperor\'s Key', null, 'Ключ императора, переданный Верховным жрецам Рассвета.', 'etc_spell_books_element_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13829', 'Mysterious Hand-written Text', null, 'Копия древней рукописи, написанной неизвестным лицом.', 'weapon_apprentices_spellbook_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13830', 'Tomlan Kamos\' Cellular Tissue', null, 'Образец ткани Томлана Камуса, мутация Канеуса. Необходимо передать Ромеру, магистру Глудио.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13831', 'Ol Ariosh\'s Cellular Tissue', null, 'Образец ткани Ола Ариоша, мутация Канеуса. Необходимо передать Ромеру, магистру Глудио.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13832', 'Crimson Hatu Otis\' Cellular Tissue', null, 'Образец ткани Багрового Хату Отиса, мутация Канеуса. Необходимо передать Мириену, магистру Диона.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13833', 'Seer Flouros\' Cellular Tissue', null, 'Образец ткани Пророка Флауруса, мутация Канеуса. Необходимо передать Мириену, магистру Диона.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13834', 'Blade Otis\' Cellular Tissue', null, 'Образец ткани Клинка Отиса, мутация Канеуса. Необходимо передать Миневии, магистру Хейна.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13835', 'Weird Bunei\'s Cellular Tissue', null, 'Образец ткани Астрального Бунея, мутация Канеуса. Необходимо передать Миневии, магистру Хейна.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13836', 'Kaim Abigore\'s Cellular Tissue', null, 'Образец ткани Кайма Абигора, мутация Канеуса. Необходимо передать Ровии, магистру Орена.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13837', 'Knight Montagnar\'s Cellular Tissue', null, 'Образец ткани Рыцаря Монтагнара, мутация Канеуса. Необходимо передать Ровии, магистру Орена.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13838', 'Venomous Storace\'s Cellular Tissue', null, 'Образец ткани Ядовитого Стораса, мутация Канеуса. Необходимо передать Атраксии, магистру Шутгарта.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13839', 'Kel Bilette\'s Cellular Tissue', null, 'Образец ткани Кела Билетте, мутация Канеуса. Необходимо передать Атраксии, магистру Шутгарта.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13840', 'White Allosce\'s Cellular Tissue', null, 'Образец ткани Белого Алосце, мутация Канеуса. Необходимо передать Каяну, магистру Руны.', 'etc_bodypart_liver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13841', 'Dragonkin Charm', null, 'Специальный предмет Семени Разрушения.', 'etc_feather_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13842', 'Tiat Two-Handed Weapon', null, 'Двуручное оружие Диады.', 'weapon_monster_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13843', 'Draconic Peltast Weapon', null, 'Оружие Пестальта.', 'weapon_doomed_dagger_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13844', 'Star Stone Extraction Scroll', null, 'Свиток, помогающий новичкам собирать Части Звездных Камней.', 'scroll_of_verification_i06', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13845', 'Attribute Master Yin\'s Sword', null, 'Оружие для уничтожения злых духов. Содержит в себе силу огня. Действует 10 минут. Повышает атаку огнем на 10. Нельзя обменять/выбросить.', 'weapon_long_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('13846', 'Seal of Binding', null, 'Печать, появляющаяся после запуска механизмов печати. Служит доказательством запуска. Необходимо отнести императору Шунайману.', 'etc_royal_seal_of_lord_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13847', 'Piece of Doubt', null, 'Таинственная скульптура, от которой веет злом.', 'etc_statue_of_einhasad_bronze_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13848', 'Headless Knight\'s Armor', null, 'Броня, снятая с Безголового Рыцаря - святого мученика.', 'armor_t62_u_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13849', 'Mandragora Root', null, 'Особый ингредиент из Диона.', 'etc_ginseng_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13850', 'Bloody Axe Black Epaulette', null, 'Значок, снятый с Кровавого Жреца.', 'etc_badge_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13851', 'Nebulite Orb', null, 'Небулитовая Сфера, нужная магам Башни Слоновой Кости.', 'etc_crystal_ball_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13852', 'Inspector Medibal\'s Document', null, 'Документы исследователя Медиваля, описывающие Семя Разрушения. Необходимо отнести их Солдату Элю на Базу Альянса Кецеруса.', 'etc_roll_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13853', 'Destroyed Darkness Fragment Powder', null, 'Порошок из тел злобный созданий тьмы. Необходимо отнести боевому магу Артиусу на Базу Альянса Кецеруса.', 'etc_powder_black_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13854', 'Destroyed Light Fragment Powder', null, 'Порошок, полученный из очищенного порошка тьмы. Его необходимо отнести Боевому Магу Артиусу.', 'etc_powder_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13855', 'Sacred Light Fragment', null, 'Осколок, излучающий свет. Похоже, им можно нанести урон Тиаде. Нельзя обменять/выбросить.', 'etc_piece_holy_light', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13856', 'Rider\'s Mark', null, 'Ошейник, полученный после укрощения дракона. Необходимо показать инженеру-гному Лекону на Базе Альянса Кецеруса.', 'etc_evil_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13857', 'Lekon\'s Certificate', null, 'Удостоверение Лекона, подтверждающее успешное завершение полета над Грацией.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13858', 'Extracted Coarse Red Star Stone', null, 'Обломок, оставшийся после неудачного извлечения Звездного Камня. Излучает красный свет.', 'low_star_stone_piece_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13859', 'Extracted Coarse Blue Star Stone', null, 'Обломок, оставшийся после неудачного извлечения Звездного Камня. Излучает синий свет.', 'low_star_stone_piece_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13860', 'Extracted Coarse Green Star Stone', null, 'Обломок, оставшийся после неудачного извлечения Звездного Камня. Излучает зеленый свет.', 'low_star_stone_piece_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13861', 'Reckless Soul Piece - Water', null, 'Частичка стихии, появившаяся после битвы с Духом Воды. Необходимо показать Учителю Инь.', 'etc_bead_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13862', 'Reckless Soul Piece - Air', null, 'Частичка стихии, появившаяся после битвы с Духом Ветра. Необходимо показать Учителю Ян.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13863', 'Freed Soul Fragment', null, 'Предмет, найденный в Семени Бессмертия. Можно обменять на Ядро Освобожденной Души у Контрабандиста Кокрана на Базе Альянса Кецеруса.', 'etc_debris_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13864', 'Seal of Tiat', null, 'Печать, полученная после победы над Тиадой. Символ ее могущества и силы. Контрабандист Кокран на Базе Альянса Кецеруса обменяет ее на специальный предмет.', 'tiat_seal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13865', 'Dragonkin Charm Fragment', null, 'Драконий тотем, найденный в Семени Разрушения. Контрабандист Кокран на Базе Альянса Кецеруса обменяет его на Драконий амулет.', 'etc_totem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13866', 'Restless Soul', null, 'Часть души, найденная в Семени Бессмертия. Контрабандист Кокран на Базе Альянса Кецеруса обменяет ее на ценный предмет.', 'soul_facet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13867', 'Tiat Charm', null, 'Часть Дыхания Тиады, найденная в Зоне Семян Разрушения. Контрабандист Кокран на Базе Альянса Кецеруса обменяет ее на ценный предмет.', 'tiat_breath_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13868', 'Yehan Klodekus\' Badge', null, 'Знак Йохана Клодекуса, ставшего Темным Рыцарем под влиянием магии Семени Бессмертия.', 'etc_badge_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13869', 'Yehan Klanikus\' Badge', null, 'Знак Йохана Кланикуса, ставшего Темным Рыцарем под влиянием магии Семени Бессмертия.', 'etc_badge_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13870', 'Lich Crystal', null, 'Кристалл, полученный после смерти Кохеменеса, который стал личем, поддавшись магии Семени Бессмертия.', 'etc_crystal_ball_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13871', 'Vulture\'s Golden Feather', null, 'Сияющее золотое перо Грифа. Покажите его инженеру-гному Лекону на Базе Альянса Кецеруса и получите награду.', 'etc_feather_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13872', 'Swallowed Skull', null, 'Часть останков, проглоченных монстрами Семени Разрушения. Соберите все останки и отнесите их солдату Орви в Ставку Кецеруса.', 'etc_skull_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13873', 'Swallowed Sternum', null, 'Часть останков, проглоченных монстрами Семени Разрушения. Соберите все останки и отнесите их солдату Орви в Ставку Кецеруса.', 'etc_rib_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13874', 'Swallowed Bones', null, 'Часть останков, проглоченных монстрами Семени Разрушения. Соберите все останки и отнесите их солдату Орви в Ставку Кецеруса.', 'etc_piece_bone_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13875', 'Deadman\'s Remains', null, 'Останки скелетов и зомби. Соберите все останки и отнесите их Боевому Магу Артиусу.', 'etc_piece_bone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13876', 'Banshee Queen\'s Eye', null, 'Глаз, вытащенный из Баньши. Его нужно отнести боевому магу Артиусу.', 'etc_eyeball_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13877', 'Drake\'s Flesh', null, 'Мясо Дрейка. Собрав необходимое количество, отнесите его солдату Денису в Ставку Кецеруса.', 'etc_meat_of_monstereye_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13878', 'Rotten Blood', null, 'Маленький сосуд с кровью сомнительного происхождения, полученный от Дениса. Предположительно, вызывает ярость у Дрейков и приманивает их.', 'etc_potion_scarlet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13879', 'Bait for Drakes', null, 'Приманка, сделанная из мяса Дрейка и свернувшейся крови. Поможет в локации Семя Разрушения  привлечь к себе Вестника Разрушения Диуса.', 'drake_wing_lure_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('13880', 'Variant Drake Wing Horns', null, 'Рога с головы Дрейка. Можно отдать их солдатам Денису и Фленосу в Ставке Кецеруса и получить награду.', 'etc_horn_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13881', 'Attribute Master Yang\'s Sword', null, 'Оружие для уничтожения опасного духа. Даже легкое прикосновение к этому предмету позволяет почувствовать заключенную в нем силу огня. Действует 10 минут. Повышает атаку землей на 10. Нельзя обменять/выбросить.', 'weapon_long_sword_i00', '4');
INSERT INTO `ghtweb_all_items` VALUES ('13882', 'Dynasty Dual Daggers', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Наносит дополнительный урон в РvР. Предмет используется Кинжальщиками, достигшими 81-го уровня.', 'dual_dagger_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('13883', 'Icarus Dual Daggers', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Наносит дополнительный урон в РvР. Предмет используется Кинжальщиками, достигшими 81-го уровня.', 'dual_dagger_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('13884', 'Vesper Dual Daggers', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Наносит дополнительный урон в РvР. Предмет используется Кинжальщиками, достигшими 81-го уровня.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('13885', 'Sealed Arcana Sigil', null, 'Запечатанный Символ Арканы. Снять печать можно у Кузнеца Маммона.', 'arcana_sigil_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13886', 'Sealed Dynasty Sigil', null, 'Запечатанный Символ Династии. Снять печать можно у Кузнеца Маммона.', 'armor_dynasty_sigil_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13887', 'Sealed Vesper Sigil', null, 'Запечатанный Символ Венеры. Снять печать можно у Кузнеца Маммона.', 'armor_verper_sigil_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13888', 'Sealed Lord\'s Cloak', null, null, 'feud_load_cloak_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13889', 'Holy Spirit\'s Cloak - Kamael exclusive', null, 'Плащ Святого Духа для персонажей высокого уровня. +30 к защите от магии тьмы. Если надет полный комплект Венеры или Династии, открывается дополнительная ячейка для плаща. Используется Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'vesper_cloack_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13890', 'Holy Spirit\'s Cloak', null, 'Плащ Святого Духа для персонажей высокого уровня. +30 к защите от магии тьмы. Если надет полный комплект доспехов Династии или выше, открывается дополнительная ячейка для плаща. Нельзя зачаровать и улучшить.', 'vesper_cloack_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13891', 'Holy Spirit\'s Cloak - Light Armor exclusive', null, 'Плащ Святого Духа для персонажей высокого уровня. +30 к защите от магии тьмы. Если надет полный комплект Венеры или Династии, открывается дополнительная ячейка для плаща. Используется Кинжальщиками, Лучниками. Не подходит Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'vesper_cloack_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13892', 'Holy Spirit\'s Cloak - Robe exclusive', null, 'Плащ Святого Духа для персонажей высокого уровня. +30 к защите от магии тьмы. Если надет полный комплект Венеры или Династии, открывается дополнительная ячейка для плаща. Используется Целителями, Чародеями, Волшебниками и Призывателями. Не подходит Камаэль. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'vesper_cloack_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13893', 'Sealed Holy Spirit\'s Cloak', null, 'Запечатанный Плащ Святого Духа. После снятия печати добавляется защита от магии тьмы +30. Печать можно снять у Ольфа Каноре или Ольфа Адамса. До этого надеть ее нельзя. Нельзя модифицировать, придать стихийные свойства и зачаровать.', 'sealed_vesper_cloack_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13894', 'Cloth Belt', null, 'Дает одно из особых свойств после использования Заклепки или Кошеля Ранга С.', 'armor_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13895', 'Leather Belt', null, 'Дает одно из особых свойств после использования Заклепки или Кошеля Ранга B.', 'armor_belt_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13896', 'Iron Belt', null, 'Дает одно из особых свойств после использования Заклепки, Кошеля, Магической Заклепки или Магического Украшения Ранга A.', 'armor_belt_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('13897', 'Mithril Belt', null, 'Дает одно из особых свойств после использования Заклепки, Кошеля, Магической Заклепки или Магического Украшения Ранга S.', 'armor_belt_i03', '0');
