INSERT INTO `ghtweb_all_items` VALUES ('14151', 'Vesper Pincer', 'Haste', 'Эксклюзивное оружие Камаэль: конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается на 11%. Наносит дополнительный урон в PvP. При модификации на +4 и выше для Вас и членов Вашей группы активируется эффект, который при Крит. Атк. с определенной вероятностью увеличивает Физ. Атк., Маг. Атк., мощность лечения, а также уменьшает расход МР на использование умений.', 'weapon_vesper_pincer_i01', '7');
