INSERT INTO `ghtweb_all_items` VALUES ('14361', 'Blood Stained Cloth', null, 'Ткань, впитавшая в себя кровь Ангелов из Платинового Клана. Она нужна Магистру Каспару.', 'etc_piece_of_cloth_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14362', 'White Cloth', null, 'Белая Ткань, которую дал Магистр Каспар. Ее нужно пропитать кровью Ангелов из Платинового Клана в Башне Дерзости.', 'etc_piece_of_cloth_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14363', 'Icarus Sawsword {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость. Наносит дополнительный урон в PvP.', 'weapon_icarus_sowsword_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14364', 'Icarus Disperser {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Уклонение или Крит. Урон. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_icarus_disperser_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14365', 'Icarus Spirit {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Проницательность, Увеличение Маны или Конверсия. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_spirits_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14366', 'Icarus Heavy Arms {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_heavy_arms_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14367', 'Icarus Trident {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Ярость, Крит. Оглушение или Легкость. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_trident_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14368', 'Icarus Hammer {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Ярость, Здоровье или Риск. Фокусировка. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_hammer_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14369', 'Icarus Hand {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Риск. Уклонение, Фокусировка или Ускорение. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_icarus_knuckle_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14370', 'Icarus Hall {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Увеличение Маны, Конверсия или Проницательность. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_stick_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14371', 'Icarus Spitter {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Экономия, Наведение или Фокусировка. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_spiter_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14372', 'Icarus Stinger {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Зазубренного Меча ИкараДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умения для Вас и членов Вашей группы. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_icarus_stinger_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14373', 'Icarus Wingblade {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук ИкараДает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость. Наносит дополнительный урон в PvP. При атаке цели дает шанс уменьшить ее дальность стрельбы из лука/арбалета или сопротивление стихиям.', 'weapon_icarus_wing_blade_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14374', 'Icarus Shooter {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Лука ИкараДает возможность получить одно из следующих особых свойств: Экономия, Наведение или Фокусировка. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_shooter_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14375', 'Icarus Dual Sword {PvP}', null, 'При модификации Парных мечей, двуручного меча, двуручного дробящего оружия и кастетов Физ. Атк. возрастает на большее значение, чем у одноручных мечей. При модификации 4 уровня и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'weapon_dual_sword_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14376', 'Icarus Sawsword {PvP}', 'Focus', '<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_icarus_sowsword_i01', '6');
