INSERT INTO `ghtweb_all_items` VALUES ('14404', 'Icarus Stinger {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Зазубренного Меча Икара<Свойство Кристалла Души>Макс. HP увеличен на 25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при Крит. Атк. дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умений персонажа и других членов группы. Наносит дополнительный урон в PvP.', 'weapon_icarus_stinger_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14405', 'Icarus Stinger {PvP}', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Зазубренного Меча Икара<Свойство Кристалла Души>Лимит веса увеличен на 20%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при Крит. Атк. дает шанс увеличить Физ. Атк., Маг. Атк. и мощность лечения, уменьшает расход MP при использовании умений персонажа и других членов группы. Наносит дополнительный урон в PvP.', 'weapon_icarus_stinger_i01', '6');
