INSERT INTO `ghtweb_all_items` VALUES ('14408', 'Icarus Wingblade {PvP}', 'Light', 'Эксклюзивное оружие Камаэль: Конверсия Тяжелых Рук Икара<Свойство Кристалла Души>Лимит веса увеличен на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_wing_blade_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14409', 'Icarus Shooter {PvP}', 'Cheap Shot', 'Эксклюзивное оружие Камаэль: Конверсия Лука Икара<Свойство Кристалла Души>Понижает расход MP на 12% при использовании умения. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_icarus_shooter_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14410', 'Icarus Shooter {PvP}', 'Guidance', 'Эксклюзивное оружие Камаэль: Конверсия Лука Икара<Свойство Кристалла Души>Точность увеличена на 5.32. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_icarus_shooter_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14411', 'Icarus Shooter {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Лука Икара<Свойство Кристалла Души>Шанс Крит. Атк. увеличен на 116. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_icarus_shooter_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14412', 'Icarus Dual Sword - Destruction {PvP}', null, 'Редкий предмет, увеличивает Физ. Атк.При модификации Физ. Атк. парных мечей, двуручных мечей, двуручного дробящего оружия и кастетов увеличится больше, чем для одноручных мечей. При модификации на +4 и выше увеличивает Крит. Атк. на 109 и Макс. HP увеличивает на 10%. Наносит дополнительный урон в PvP и дает шанс снизить дальность выстрела из лука/арбалета противника при получении урона.', 'weapon_dual_sword_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14413', 'Icarus Disperser - Confusion {PvP}', null, 'Редкий предмет, увеличивает Уклонение.Дает возможность получить одно из следующих особых свойств: Фокусировка, Уклонение или Крит. Урон. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_disperser_i00', '6');
