INSERT INTO `ghtweb_all_items` VALUES ('14450', 'Icarus Hand - Destruction {PvP}', 'Rsk. Evasion', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Увеличивает Уклонение на 6.8 при HP 60% и ниже. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_knuckle_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14451', 'Icarus Hand - Destruction {PvP}', 'Focus', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 106. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_knuckle_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14452', 'Icarus Hand - Destruction {PvP}', 'Haste', 'Редкий предмет, увеличивает Физ. Атк.<Свойство Кристалла Души>Скор. Атк. увеличивает приблизительно на 10%. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_icarus_knuckle_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14453', 'Icarus Heavy Arms - Lightning {PvP}', null, 'Редкий предмет, увеличивает шанс Крит. Атк.Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье или Легкость. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_heavy_arms_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14454', 'Icarus Heavy Arms - Lightning {PvP}', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает шанс Крит. Атк. на 111. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_heavy_arms_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14455', 'Icarus Heavy Arms - Lightning {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_heavy_arms_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14456', 'Icarus Heavy Arms - Lightning {PvP}', 'Light', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Увеличивает грузоподъемность на 20%. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_icarus_heavy_arms_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14457', 'Icarus Hall - Hail {PvP}', null, 'Редкий предмет, увеличивает Маг. Атк.Дает возможность получить одно из следующих особых свойств: Увеличение Маны, Конверсия или Проницательность. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_stick_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14458', 'Icarus Hall - Hail {PvP}', 'Mana Up', 'Редкий предмет, увеличивает Маг. Атк.<Свойство Кристалла Души>Увеличивает Макс. MP на 30%. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_stick_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14459', 'Icarus Hall - Hail {PvP}', 'Conversion', 'Редкий предмет, увеличивает Маг. Атк.<Свойство Кристалла Души>Увеличивает Макс. MP на 60% и Макс. HP уменьшает на 40%. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_stick_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14460', 'Icarus Hall - Hail {PvP}', 'Acumen', 'Редкий предмет, увеличивает Маг. Атк.<Свойство Кристалла Души>Увеличивает Скор. Маг. на 15%. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_icarus_stick_i01', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14461', 'Icarus Dual Daggers {PvP}', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 81 уровня и выше. Наносит дополнительный урон в PvP. С некоторой вероятностью снимает у противника 1 положительный эффект или снижает его защиту щитом.', 'dual_dagger_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('14462', 'Vesper Dual Sword {PvP}', null, 'При модификации Физ. Атк. парных мечей, двуручного меча, двуручного дробящего оружия и кастетов возрастает больше, чем у одноручных мечей. При модификации на +4 и выше увеличивается Крит. Атк. на 109 и Макс. HP на 10%. Увеличивается урон в PvP и с определенным шансом при использовании луков/арбалетов уменьшается дистанция.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14463', 'Vesper Cutter {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, Здоровье. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_vesper_cutter_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14464', 'Vesper Slasher {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, Здоровье. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_vesper_slasher_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14465', 'Vesper Buster {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Проницательность, Увеличение Маны, Магические Оковы. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_vesper_burster_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14466', 'Vesper Shaper {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Крит. урон, Поглощение НР, Ускорение. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_vesper_shaper_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14467', 'Vesper Fighter {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье, Крит. Оглушение. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_vesper_fighter_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14468', 'Vesper Stormer {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Наведение, Ускорение. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_stormer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14469', 'Vesper Avenger {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Регенерация НР, Поглощение НР, Здоровье. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_avenger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14470', 'Vesper Retributer {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Регенерация НР, Поглощение НР, Здоровье. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_vesper_retributer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14471', 'Vesper Caster {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Проницательность, Регенерация МР, Увеличение Маны. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_vesper_caster_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14472', 'Vesper Singer {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Воодушевление, Регенерация МР, Магические Оковы. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_vesper_singer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14473', 'Vesper Thrower {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Экономия, Крит. Замедление, Фокусировка. Наносит дополнительный урон в PvP. При атаке цели дает шанс уменьшить ее дальность стрельбы из лука/арбалета или сопротивление стихиям.', 'weapon_vesper_thrower_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14474', 'Vesper Pincer {PvP}', null, 'Эксклюзивное оружие Камаэль: конверсия Резака ВенерыДает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, ЗдоровьеПри модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы. Наносит дополнительный урон в PvP. При атаке цели дает шанс уменьшить ее дальность стрельбы из лука/арбалета или сопротивление стихиям.', 'weapon_vesper_pincer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14475', 'Vesper Shooter {PvP}', null, 'Эксклюзивное оружие Камаэль: конверсия Броска ВенерыДает возможность получить одно из следующих особых свойств: Экономия, Крит. Замедление, Фокусировка. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'weapon_vesper_schutze_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14476', 'Vesper Nagan {PvP}', null, 'Эксклюзивное оружие Камаэль: конверсия Эспадона ВенерыДает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, Здоровье. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить повреждения.', 'weapon_vesper_nagen_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14477', 'Vesper Dual Daggers {PvP}', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом. Предмет используется Кинжальщиками, достигшими 81 уровня.', 'dual_dagger_i00', '7');
