INSERT INTO `ghtweb_all_items` VALUES ('14507', 'Vesper Singer {PvP}', 'Magic Hold', '<Свойство Кристалла Души>В 20% применяет колдовство Корень Дриады при использовании вредоносного Умения на цель. Наносит дополнительный урон в PvP. С некоторой вероятностью увеличивает Скор. Маг. при получении повреждений.', 'weapon_vesper_singer_i01', '7');
