INSERT INTO `ghtweb_all_items` VALUES ('14509', 'Vesper Thrower {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. увеличивается на 133. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_vesper_thrower_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14510', 'Vesper Thrower {PvP}', 'Critical Slow', '<Свойство Кристалла Души>Существует 33% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP и дает шанс при атаке увеличить Скор. Атк. лука/арбалета.', 'weapon_vesper_thrower_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14511', 'Vesper Pincer {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.Модифицированное на 4 и более, при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_vesper_pincer_i01', '7');
