INSERT INTO `ghtweb_all_items` VALUES ('14739', 'Event - Fresh Milk', null, 'Парное молоко. Попробовав его, можно ощутить эффекты Силы, Ускорения, Проницательности, Воодушевления, Легкой Походки, Ярости Вампира, Духа Берсерка, Щита, Фокусировки, Шепота Смерти, Наведения, Чистоты, Дикой Магии и Концентрации.', 'etc_fresh_milk_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('14740', 'Event - Save the Cow Event Pack', null, 'Можно получить на один аккаунт раз в 12 часов. Щелкните два раза по предмету, чтобы получить необходимые для ивента Свиток Призыва и Лекарство Купидона. Возможен обмен.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14741', 'Event - Vitality Replenishing Herb Tea 5 minutes', null, 'Выпив этуот отвар, Вы ощутите ее тонизирующий эффект, который будет действовать в течение указанного времени. Можно обменивать.', 'etc_hot_spring_sulfur_i00', '3');
