INSERT INTO `ghtweb_all_items` VALUES ('14801', 'Gludio Guard Earring', null, 'Серьга, которой награждается Гвардеец Глудио. Оглушающая атака +15%, Защита от кровотечения +15%, Защита от Воды +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14802', 'Dion Guard Earring', null, 'Серьга, которой награждается Гвардеец Диона. Удерживающая атака +15%, Защита от отравления +15%, Защита от Святости +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14803', 'Giran Guard Earring', null, 'Серьга, которой награждается Гвардеец Гирана. Кровопускающая атака +15%, Защита от паралича +15%, Защита от Ветра +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14804', 'Oren Guard Earring', null, 'Серьга, которой награждается Гвардеец Орена. Парализующая атака +15%, Защита от удержания +15%, Защита от Тьмы +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14805', 'Aden Guard Earring', null, 'Серьга, которой награждается Гвардеец Адена. Ментальная атака +15%, Защита от оглушения +15%, Защита от Земли +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14806', 'Innadril Guard Earring', null, 'Серьга, которой награждается Гвардеец Иннадрила. Усыпляющая атака +15%, Защита от оглушения +15%, Защита от Воды +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14807', 'Goddard Guard Earring', null, 'Серьга, которой награждается Гвардеец Годдарда. Оглушающая атака +15%, Защита от усыпления +15%, Защита от Огня +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14808', 'Rune Guard Earring', null, 'Серьга, которой награждается Гвардеец Руны. Отравляющая атака +15%, Защита от удержания +15%, Защита от Огня +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14809', 'Schuttgart Guard Earring', null, 'Серьга, которой награждается Гвардеец Шутгарта. Удерживающая атака +15%, Защита от устрашения +15%, Защита от Ветра +10, Макс. CP +5%. Нельзя обменять/выбросить.', 'accessory_earring_of_domi_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14810', 'Blue Talisman - Buff Cancel', null, 'Снимает положительные эффекты с противников, находящихся неподалеку. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'etc_talisman_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14811', 'Blue Talisman - Buff Steal', null, 'Забирает положительный эффект противника. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'etc_talisman_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14812', 'Red Talisman - Territory Guard', null, 'Увеличивает Макс. СР, восстанавливает уровень СР. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'etc_talisman_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14813', 'Blue Talisman - Lord\'s Divine Protection', null, 'Уменьшает урон, получаемый во время PvP. При использовании двух талисманов эффект не меняется. Теневой предмет. Нельзя обменять/выбросить.', 'etc_talisman_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14814', 'White Talisman -  All Resistance', null, 'Увеличивает сопротивление ко всем стихиям. При использовании двух талисманов эффект не суммируется. Теневой предмет. Нельзя обменять/выбросить.', 'etc_talisman_i06', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14815', 'Territory Health Recovery Potion', null, 'Восстанавливает уровень HP. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'etc_super_hp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('14816', 'Territory Mana Recovery Potion', null, 'Восстанавливает уровень MP. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'etc_super_mp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('14817', 'Territory CP Recovery Potion', null, 'Восстанавливает уровень СР. Не действует при использовании персонажами ниже 61-го уровня. Использование доступно исключительно на поле битвы.', 'etc_super_cp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('14818', 'Enriched Pet Food for Wolves', null, 'Восстанавливает уровень сытости Питомца.', 'etc_pouch_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14819', 'Guardian\'s Dragon Bugle', null, 'Горн, необходимый для призыва Ездового Дракона Хранителя. Питомец забирает часть опыта, заработанного хозяином.', 'etc_bugle_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('14820', 'Skull Key of Suffering', null, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Зал Страданий.', 'etc_skeleton_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14821', 'Skull Key of Erosion', null, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Зал Гибели.', 'etc_skeleton_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14822', 'Skull Key of the Heart', null, 'Ключ, который необходим нежити высшего уровня для свободного перемещения по Семени Бессмертия. Позволяет войти в Источник Бессмертия.', 'etc_skeleton_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14823', 'Soul Extraction Device', null, 'Устройство, позволяющее извлечь души из монстров. Доступно исключительно в Семени Бессмертия.', 'etc_lantern_i00', '0');
