INSERT INTO `ghtweb_all_items` VALUES ('14848', 'Protection Soul\'s Pendant', null, 'Амулет, защищенный от притязаний злых духов. В середине его находится ядро, излучающее красный свет.', 'ect_charm_of_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14849', 'Kahman\'s Supply Box', null, 'Ящик припасов, полученный от Кахмана. Дважды кликнув на нем, можно посмотреть, что хранится внутри.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14850', 'Droph\'s Support Items', null, 'Подарок, полученный у Дрогфа за истребление Хекатонов Прайм. Дважды кликнув на нем, можно посмотреть, что хранится внутри.', 'etc_jewel_box_i00', '0');
