INSERT INTO `ghtweb_all_items` VALUES ('14853', 'Cave Exploration Text 3 Sheet', null, 'Книга, в которой записан секрет Хекатонов Прайм.', 'etc_cave_page_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14854', 'Recipe - Spiteful Soul Energy', null, 'Квестовый рецепт. Необходим для изготовления Энергии Души. Необходимо умение \"Создать Вещь\" 2-го уровня.', 'etc_recipe_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14855', 'Spiteful Soul Energy', null, 'Душа, полученная у Главаря Злобных Душ. Соберите их и отнесите Бальтазару.', 'etc_crystal_ball_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14856', 'Spiteful Soul Vengeance', null, 'Сфера, полученная у Главаря Злобных Душ. Не наполненная энергией, она никому не нужна.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14857', 'Shell of Monsters', null, 'Панцирь, полученный во время сражения с монстрами недалеко от Пещеры Гигантов. Отнесите его Магистру Ханелин.', 'etc_bark_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14858', 'Scout\'s Note', null, 'Записка, найденная при осмотре трупа Разведчика. Необходимо отнести Капитану Наемников Пирсу.', 'etc_piece_of_report_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14859', 'Stakato Queen\'s Fang', null, 'Клык, полученный у Королевы Стакато Шиид. Необходимо отнести Наемнику Кахману.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14860', 'Box Containing the Flame of the Holy Spirit', null, 'Ящик, таящий в себе благословенный огонь. Необходимо отнести Смотрителю Маяка Торранту в Логово Зла.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14861', 'Cursed Burial Items', null, 'Украшение, созданное злыми духами.', 'etc_totem_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14862', 'Flauen\'s Letter', null, 'Письмо Хранителя Портала Хейна - Флоена. Отнеся это Ясону Хейну, можно подробнее узнать о предстоящем задании.', 'etc_letter_envelope_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14863', 'Letter to Helvetica', null, 'Документ с обещанием Ясона Хейна о готовности выслать помощь. Необходимо отнести разработчику Гельдремов Гаке на Поля Безмолвия.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14864', 'Letter to Athenia', null, 'Документ с обещанием Ясона Хейна о готовности выслать помощь. Необходимо отнести на Шепчущие Поля Повелителю Духов Минеру.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14865', 'Certificate of Support', null, 'Документ, полученный у Гаки, разработчика Гельдремов. Необходим для получения дополнительной миссии.', 'etc_letter_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14866', 'Certificate of Support', null, 'Документ, полученный у Минера, Повелителя Духов. Необходим для получения дополнительной миссии.', 'etc_letter_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14867', 'Damaged Torch Fragment', null, 'Обломок, оставшийся после разрушения Алтаря Огня, находившегося в окрестностях Лагеря Поклонения Огню. Соберите их и отнесите Гаке, разработчику Гельдремов.', 'etc_charcoal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14868', 'Guardian Spirit Fragment', null, 'Частица, полученная во время охоты на Хранителей Огня и Духов Огненной Защиты. Соберите их и отнесите Гаке, разработчику Гельдремов.', 'etc_crystal_ball_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14869', 'Destroyed machine piece', null, 'Обломок одной из составных частей Измельчителя Мусора. Соберите их и отнесите Повелителю Духов, Минеру.', 'etc_plate_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14870', 'Enchanted Golem Shard', null, 'Осколок Гельдрема, полученный во время охоты. Отнесите его Повелителю Огня Минеру.', 'etc_plate_glay_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14871', 'Mucrokian Hide', null, 'Доказательство победы над Макронианами. Отнесите это Конт Тэн Саузену в Укрепление Разработчиков Гельдремов.', 'etc_leather_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14872', 'Awakened Mucrokian Hide', null, 'Доказательство победы над Зараженными Макронианами. Отнесите это Счетчику в Укрепление Разработчиков Гельдремов.', 'etc_leather_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14873', 'Mucrokian Hide', null, 'Доказательство победы над Макронианами. Отнесите это Участнику Ритуала Поклонения Огню Ауту.', 'etc_leather_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14874', 'Fallen Mucrokian Hide', null, 'Доказательство победы над Измененными Макронианами. Отнесите это Участнику Ритуала Поклонения Огню Ауту.', 'etc_leather_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14875', 'Mineral Fragment', null, 'Осколок, полученный в бою на территории Мифрилового Рудника. Возьмите его и отнесите в Деревню Гномов Представителю Гильдии Серой Колонны Филару.', 'etc_debris_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14876', 'Evidence of Migration', null, 'Документ, свидетельствующий об успешной поездке к Крысолюдам. Возьмите его и отнесите Командиру Грабителей Могил Канемике.', 'etc_paper_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14877', 'Replenished Power Bead', null, 'Бусина Алтаря Люсьена, необходимый для поддержания энергетического запаса границ. Необходимо отнести это в каждый из Алтарей Люсьена для усиления границ между мирами.', 'etc_crystal_ball_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14878', 'Discharged Power Bead', null, 'Разряженная Бусина. Является свидетельством выполнения задания. После подзарядки всех Алтарей Люсьена необходимо отнести в Деревню Гномов Жрецу Земли Дайчиру.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14879', 'Stakato Fang', null, 'Клык, полученный во время сражения со Стакато в Гнезде Стакато. Отнесите это Наемнику Кахману и докажите свои способности.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14880', 'Dirty Bead', null, 'Бусина, полученная в битве со Стакато. Эту непонятную вещь необходимо отнести Кинтайджину.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14881', 'Soul Core Containing Evil Spirit', null, 'Ядро, наполненное злой энергией. Излучает слабый фиолетовый свет.', 'etc_evil_soul_core_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14882', 'Ragna Orc\'s Amulet', null, 'Игрушка, используемая Орками Рагна для управления другими существами. Возьмите ее и отнесите Смотрителю Маяка Торранту.', 'etc_totem_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14883', 'Hisilrome\'s Heart', null, 'Сердце, полученное после сражения с Хисилромой.', 'etc_bodypart_heart_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('14884', 'Gludio Supply Box - Magic Rune Clip', 'Grade S, A', 'Сундук с гербом Глудио. Открыв его, можно получить Магическую Заколку высокого Ранга.', 'etc_box_of_adventure_1_i00', '0');
