INSERT INTO `ghtweb_all_items` VALUES ('15381', 'Herdsman\'s Love Scroll', null, 'Свиток, с помощью которого можно модифицировать Радужное Одеяние Веги. Увеличивает Физ. Защ. и Маг. Защ. Безопасная модификация до +3. При неудаче предмет исчезает. При модификации на +4 и выше увеличивает СИЛ, ВЫН, ИНТ, ДУХ. Использовать можно только во время Ивента Праздник Ткачихи, после ивента исчезает.', 'event_altair_enchant_scroll_i00', '20');
INSERT INTO `ghtweb_all_items` VALUES ('15382', 'Vitality Belt Enchant Scroll', null, 'Свиток, с помощью которого можно модифицировать Пояс Энергии. Увеличивает Физ. Защ. и Маг. Защ., Эффект Поддержания Энергии, Снижение времени для повторного использования. Безопасная модификация до +3, При неудаче предмет исчезает. При модификации на +4 и выше увеличивает время действия Поддержания Энергии и снижает время повторного использования. Можно использовать только во время ивента Пояс Энергии, после ивента исчезает.', 'event_energy_enchant_scroll_i00', '20');
