INSERT INTO `ghtweb_all_items` VALUES ('15425', 'Hero\'s Treasure Box', 'Event', 'Упаковка: Комплект снаряжения - 30 дн. Внутри находятся предметы: Купон на Ожерелье Питомца и Точка Возвращения Героя. Нельзя обменять/выбросить/уничтожить.', 'event_hero_treasure_box_i00', '0');
