INSERT INTO `ghtweb_all_items` VALUES ('15428', '6th Anniversary Party Earring (Event)', '30-day limited period', 'Увеличивает MP на 31, сопротивление шоковым и ментальным атакам, вызывающим аномальные статусы, на 20%. Имеет эффект Ярости Вампира. Эффект не суммируется. Срок действия: 30 дн. Нельзя обменять/выбросить/уничтожить.', 'event_six_party_earing_i00', '0');
