INSERT INTO `ghtweb_all_items` VALUES ('15430', 'Event - Halloween Candy', 'Event', 'Сладкая Конфета Хэллоуина. Можно обменять у Скульди на Коробку Игрушек Хэллоуина.', 'ev_hallowinday_candy_i00', '0');
