INSERT INTO `ghtweb_all_items` VALUES ('15488', 'Maguen Pet Collar', null, 'С помощью этого Рога можно призвать питомца Магвена, который питается пищей для волков и забирает некое количество опыта у хозяина.', 'etc_marguene_pet_collar_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15489', 'Elite Maguen Pet Collar', null, 'С помощью этого Рога можно призвать питомца Элитного Магвена, который питается пищей для волков и забирает некое количество опыта у хозяина.', 'etc_elite_marguene_pet_collar_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15490', 'Maguen Collection Box', null, 'Кажется, внутри что-то есть. Попробуйте открыть.', 'etc_marguene_collection_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15491', 'Elite Maguen Collection Box', null, 'Кажется, внутри что-то есть. Попробуйте открыть.', 'etc_elite_marguene_collection_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15492', 'Sel Mahum Salmon Porridge', null, 'Любимая Каша с Лососем Ксель-Махум. Выглядит аппетитно, а пахнет еще лучше.', 'etc_salmon_soup_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15493', 'Fantasy Mushroom Pouch', null, 'Споры Ядовитого Гриба, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'etc_pouch_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15494', 'Sticky Mushroom Pouch', null, 'Споры Клейкого Гриба, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'etc_pouch_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15495', 'Vitality Plant Leaf', null, 'Лист целебного растения, растущего в Долине Ящеров. Более подробную информацию можно получить у Члена Гильдии Исследователей Гарри в Долине Ящеров.', 'etc_leaf_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15496', 'Seer Ugoros Pass', null, 'Аттестат Члена Гильдии Исследователей Джанни из Долины Ящеров свидетельствует о том, что Вы очень опытный воин. Теперь Вы можете отправиться к Провидцу Тантаар Югору. Нужно показать аттестат Привратнику Батракусу.', 'etc_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15497', 'High-Grade Lizard Scale', null, 'Чешуя Ящера, найденная после уничтожения Провидца Тантаар Югора. Отнесите ее Торговцу Анкуми в Долину Ящеров.', 'etc_godad_fish_scale_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15498', 'Middle-Grade Lizard Scale', null, 'Чешуя Ящера, найденная после уничтожения Провидца Тантаар Югора. Отнесите ее Торговцу Анкуми в Долину Ящеров.', 'etc_innadrile_fish_scale_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15499', 'Vial of Tanta Blood', null, 'Бутыль с кровью Ящеров Тантаар, обитающих в Долине Ящеров. Отнесите ее Члену Гильдии Исследователей Лаки в Долину Ящеров.', 'etc_dragons_blood_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15500', 'Sel Mahum Diary', null, 'Дневник, в котором описаны повседневные дела Ксель-Махум. Отнесите его Стражу Стэну в Город Орен.', 'etc_spell_books_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15501', 'Sel Mahum Cookbook Page', null, 'Часть Кулинарной Книги, которую носят с собой повара Ксель-Махум. Отнесите ее Стражу Стэну в Город Орен.', 'etc_hidden_2nd_page_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15502', 'Sel Mahum Cookbook', null, 'Кулинарная Книга, которую носят с собой повара Ксель-Махум. Отнесите ее Стражу Стэну в Город Орен.', 'etc_spell_books_assistance_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15503', 'Shiny Salmon', null, 'Очень аппетитный лосось с ярко блестящей чешуей. Отнесите его Стражу Стэну в Город Орен.', 'etc_tuna_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15504', 'Gray Salmon', null, 'На вид вполне съедобный лосось. Отнесите его Стражу Стэну в Город Орен.', 'etc_tuna_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15505', 'Sickly Salmon', null, 'Выглядит неаппетитно. Отнесите его Стражу Стэну в Город Орен.', 'etc_tuna_i08', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15506', 'Salmon Lure', null, 'Наживка для лосося. Без нее поймать лосося невозможно.', 'etc_bait_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15507', 'Foul Fruit', null, 'Неизвестный плод с отвратительным вкусом. Если добавить его в Кашу с Лососем, можно ее основательно испортить.', 'etc_codran_i06', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15508', 'Sel Mahum Training Diary', null, 'Кропотливо заполненный Дневник Тренировок Ксель-Махум. Отнесите его Стражу Пинапсу в Город Орен.', 'etc_spellbook_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15509', 'Sel Mahum Training Timetable', null, 'Лист с Расписанием Тренировок Ксель-Махум. Отнесите его Стражу Пинапсу в Город Орен.', 'etc_plan_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15510', 'Golem Corps Log', null, 'Лист бумаги с непонятными записями отряда големов. Нужно собрать все записи.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15511', 'Golem Corps Collection', null, 'Сборник непонятных записей отряда големов. Отнесите его Коллекционеру Гутенхагену, находящемуся в Руинах Павла.', 'etc_roll_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15512', 'Seed of Annihilation Orders', null, 'Приказ командира Базы Альянса Кецеруса Ковальдира. Отправляйтесь в Пристань Семени Уничтожения и передайте приказ Офицеру Клемису.', 'etc_letter_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15513', 'Gracian Soldier Tag', null, 'Знак отличия, подобранный в Семени Уничтожения с тела Солдата Грации. Отнесите этот знак Офицеру Клемису. Найти его можно в Пристани Семени Уничтожения.', 'etc_ticket_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15514', 'Cold Resistance Potion', null, 'Особое зелье, созданное в Гильдии Зинии для защиты от проклятия Снежной Королевы. Необходимо для освобождения Крегора, подверженного опасности.', 'etc_cp_potion_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15515', 'Seal Breaker - 5th Floor', null, 'Камень Отмены Границы, необходимый для встречи с Принцем Демонов на 5 этаже Башни Вечности Стальной Цитадели. Разрушается после одного использования.', 'etc_crystal_cave_crystal_i0', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15516', 'Seal Breaker - 10th Floor', null, 'Камень Отмены Границы, необходимый для встречи с Ранку на 10 этаже Башни Вечности Стальной Цитадели. Разрушается после одного использования.', 'etc_crystal_cave_crystal_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15517', 'Seal Components Part 1', null, 'Компонент Границы, полученный после уничтожения Космического Разведчика в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'etc_debris_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15518', 'Seal Components Part 2', null, 'Компонент Границы, полученный после уничтожения Космического Наблюдателя в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'etc_stone_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15519', 'Seal Components Part 3', null, 'Компонент Границы, полученный после уничтожения Космического Жреца в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'etc_synthetic_cokes_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15520', 'Seal Components Part 4', null, 'Компонент Границы, полученный после уничтожения Космического Повелителя в Башне Вечности. Соединив его с остальными компонентами, можно создать Камень Отмены Границы.', 'event_cubic_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15521', 'Broken Golem Shard', null, 'Осколок, полученный во время охоты на големов.', 'etc_plate_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15522', 'Shabby Necklace', null, 'Блеклое Ожерелье, которое Страж Антараса Теодрик дает только тем, кто действительно сможет уничтожить Антараса. Говорят, если уничтожить Антараса, ожерелье изменится.', 'armor_neck01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15523', 'Miracle Necklace', null, 'Предмет, в который превратилось Блеклое Ожерелье после уничтожения Антараса. Отнесите его Стражу Антараса Теодрику.', 'accessary_necklace_of_protection_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15524', 'Poor Necklace', null, 'Дешевое Ожерелье, которое Страж Валакаса Клейн дает только тем, кто действительно сможет уничтожить Валакаса. Говорят, если уничтожить Валакаса, ожерелье изменится.', 'armor_neck02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15525', 'Valor Necklace', null, 'Предмет, в который превратилось Дешевое Ожерелье после уничтожения Валакаса. Отнесите его Стражу Валакаса Клейну.', 'accessary_necklace_of_valor_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15526', 'Tattered Monk Clothes', null, 'Лохмотья Монаха, полученные после уничтожения монахов в Монастыре Безмолвия. Отнесите их Гремори. Найти его можно в Монастыре Безмолвия.', 'etc_leather_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15527', 'Mark of Splendor', null, 'Доказательство уничтожения Главы Флиндов Анаиса по просьбе Жреца Гремори. Если отнести его Гремори, он даст хорошую награду.', 'etc_potion_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15528', 'Mark of Darkness', null, 'Доказательство уничтожения Главы Флиндов Анаиса по просьбе Жреца Гремори. Но вместо Знака Сияния Вам в руки попал Знак Тьмы. Если отнести его Гремори, он лишь посмеется.', 'etc_potion_yellow_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15529', 'Priest Dominic\'s Letter', null, 'Секретное письмо, которое Жрец Доминик попросила передать Гремори. Войдите в Монастырь Безмолвия и отдайте его Жрецу Гремори.', 'etc_piece_of_paper_gray_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15530', 'Monk Scripture', null, 'Манускрипт, полученный после уничтожения монахов в Монастыре Безмолвия. Отнесите его Жрецу Гремори.', 'etc_magic_book_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15531', 'Sel Mahum Mane', null, 'Шерсть, полученная во время уничтожения Махумов, атакующих Ферму Диких Зверей. Отправляйтесь на Ферму Диких Зверей и передайте шерсть Келае.', 'etc_mane_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15532', 'Veal', null, 'Мясо, полученное после уничтожения очень молодого зверя. Пахнет аппетитно, но на вкус не очень. Отправляйтесь на Ферму Диких Зверей и отдайте его Пастуху Тунатуну.', 'etc_meat_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15533', 'Innocence Jewel', null, 'Белый самоцвет. Такие самоцветы выплевывают дикие звери, пока не вырастут. Если долго смотреть на него, вспоминаются давние времена.', 'etc_crystal_ball_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15534', 'Prime Meat', null, 'Хорошее мясо, полученное после уничтожения взрослого зверя. Говорят с одного зверя можно получить только один кусок мяса. Соберите мясо и отправляйтесь на Ферму Диких Зверей к Пастуху Тунатуну.', 'etc_meat_of_monstereye_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15535', 'Concentrated Spirit Energy', null, 'Концентрированная Энергия Жизни, полученная в Семени Уничтожения. Если отправиться на Базу Альянса Кецеруса к Контрабандисту Кокрану, он обменяет ее на что-нибудь ценное.', 'etc_oil_pot_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15536', 'Spirit Stone Dust', null, 'Порошок Осколка Камня Души, полученный в Семени Бессмертия. Если отправиться на Базу Альянса Кецеруса к Контрабандисту Кокрану, он обменяет его на Осколок Камня Души.', 'etc_pouch_brown_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15537', 'Strongbox of Promise', null, 'Маленький сейф, полученный во время уничтожения монахов в Монастыре Безмолвия. Щелкнув по сейфу дважды, можно посмотреть содержание квеста. Начальный квестовый предмет.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15538', 'Book of Silence', null, 'Древнее Писание, которое находилось в Сейфе Клятвы. Чтобы вернуть эту книгу владельцу, сначала нужно узнать, кто он. Отправляйтесь в Замок Руна и попросите помощи у Управляющего Библиотекой Мудрецов Софии.', 'high_kamael_skill_book_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15539', 'Book of Silence', null, 'Управляющий Библиотекой Мудрецов София рассказала Вам о хозяине этой книги. Теперь нужно вернуть писание ему.', 'high_kamael_skill_book_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15540', 'Unlit Torchlight', null, 'Предмет, необходимый для получения Сундука с Сокровищами в Потайной Комнате в Монастыре Безмолвия.', 'weapon_club_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('15541', 'Red Soul Crystal - Stage 17', null, 'Красный кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'etc_soul_stone_i00', '1');
INSERT INTO `ghtweb_all_items` VALUES ('15542', 'Blue Soul Crystal - Stage 17', null, 'Синий кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'etc_soul_stone_i01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('15543', 'Green Soul Crystal - Stage 17', null, 'Зеленый кристалл, поглощающий души. Уровень 17. Наполнившись, дарует особые свойства оружию. Тратит 26 МР при каждом использовании. Кристалл этого уровня может самостоятельно поглощать души.', 'etc_soul_stone_i02', '1');
INSERT INTO `ghtweb_all_items` VALUES ('15544', 'Eternal Core Sword', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.', 'weapon_incessantcore_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15545', 'Mamba Edge', null, 'Дает возможность получить одно из следующих особых свойств: Поглощение HP, Ускорение, Крит. Урон.', 'weapon_mambaedge_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15546', 'Eversor Mace', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Регенерация HP, Поглощение HP.', 'weapon_expowder_mace_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15547', 'Contristo Hammer', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Поглощение HP, Регенерация HP.', 'weapon_pereztear_hammer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15548', 'Lava Saw', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.', 'weapon_lavamond_saw_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15549', 'Jade Claw', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Крит. Оглушение, Фокусировка.', 'weapon_jademice_claw_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15550', 'Demitelum', null, 'Дает возможность получить одно из следующих особых свойств: Наведение, Ускорение, Здоровье.', 'weapon_ghostcleaner_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15551', 'Sacredium', null, 'Дает возможность получить одно из следующих особых свойств: Регенерация MP, Увеличение Маны, Проницательность.', 'weapon_sacredumors_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15552', 'Cyclic Cane', null, 'Дает возможность получить одно из следующих особых свойств: Регенерация MP, Магические Оковы, Воодушевление.', 'weapon_psyskilt_cane_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15553', 'Archangel Sword', null, 'Дает возможность получить одно из следующих особых свойств: Проницательность, Магические Оковы, Увеличение Маны.', 'weapon_archangel_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15554', 'Recurve Thorne Bow', null, 'Дает возможность получить одно из следующих особых свойств: Фокусировка, Крит. Замедление, Экономия.', 'weapon_recurvethorne_bow_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15555', 'Heavenstare Rapier', null, 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой СущностиДает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_heavenstair_rapier_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15556', 'Pyseal Blade', null, 'Эксклюзивное оружие Камаэль: Конверсия Пылающей ПилыДает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.', 'weapon_pyseal_blade_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15557', 'Thorne Crossbow', null, 'Эксклюзивное оружие Камаэль: Конверсия Лука Изогнутых ШиповДает возможность получить одно из следующих особых свойств: Фокусировка, Крит. Замедление, Экономия.', 'weapon_thorne_crossbow_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15558', 'Periel Sword', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Фокусировка, Ускорение.', 'weapon_periwing_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('15559', 'Skull Edge', null, 'Дает возможность получить одно из следующих особых свойств: Поглощение HP, Ускорение, Крит. Урон.', 'weapon_skulledge_i00', '7');
