INSERT INTO `ghtweb_all_items` VALUES ('15561', 'Devilish Maul', null, 'Дает возможность получить одно из следующих особых свойств: Здоровье, Поглощение HP, Регенерация HP.', 'weapon_evildeity_maul_i00', '7');
