INSERT INTO `ghtweb_all_items` VALUES ('15974', 'Gemtail Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Очарования<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_gemtail_rapier_i01', '7');
