INSERT INTO `ghtweb_all_items` VALUES ('16016', 'Heavenstare Rapier {PvP}', 'Focus', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_heavenstair_rapier_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16017', 'Heavenstare Rapier {PvP}', 'Haste', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_heavenstair_rapier_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16018', 'Heavenstare Rapier {PvP}', 'Health', 'Эксклюзивное оружие Камаэль: Конверсия Меча Неиссякаемой Сущности<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_heavenstair_rapier_i01', '7');
