INSERT INTO `ghtweb_all_items` VALUES ('16025', 'Necklace of Freya', null, 'Увеличивает сопротивление воде на 10, кровотечению на 20%, параличу на 15%, шокирующим эффектам на 15%, усыплению на 15%, сокращает время перезарядки магических умений на 5%. Отражает 4% урона в ближнем бою, увеличивает макс. MP на 50, восстановление MP на 0.23, сопротивление ментальным атакам на 10%.', 'accessary_queen_of_ice_necklace_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('16026', 'Blessed Necklace of Freya', null, 'Увеличивает сопротивление воде на 15, кровотечению на 25%, параличу 20%, шокирующим эффектам на 20%, усыплению 20%, сокращает время перезарядки магических умений на 5%. Отражает 4% урона в ближнем бою, увеличивает макс. MP на 50, восстановление MP на 0.46, сопротивление ментальным атакам на 10%, силу исцеляющей магии на 15.6, ДУХ  +2, ВЫН +1, СИЛ -1, уменьшает расход MP магических умений на 5%.', 'accessary_queen_of_ice_necklace_i00', '0');
