INSERT INTO `ghtweb_all_items` VALUES ('16088', 'Vesper Thrower - Clairvoyance', 'Critical Slow', 'Редкий предмет, увеличивающий дальность атаки, <Свойство Кристалла Души>Дает 33% вероятности наложения эффекта Замедления на цель при Крит. Атк. Наносит дополнительный урон в PvP.', 'weapon_vesper_thrower_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16089', 'Vesper Pincer - Thunder', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_vesper_pincer_i01', '7');
