INSERT INTO `ghtweb_all_items` VALUES ('16136', 'Vesper Buster - Cleverness {PvP}', null, 'Редкий предмет, увеличивает скорость восстановления MP.Дает возможность получить одно из следующих особых свойств: Проницательность, Увеличение Маны, Магические Оковы. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_burster_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16137', 'Vesper Shaper - Gale {PvP}', null, 'Редкий предмет, увеличивает Скор. Атк.Дает возможность получить одно из следующих особых свойств: Крит. Удар, Поглощение HP, Ускорение. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_shaper_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16138', 'Vesper Fighter - Gale {PvP}', null, 'Редкий предмет, увеличивающий Скор. Атк..Дает возможность получить одно из следующих особых свойств: Фокусировка, Здоровье, Крит. Оглушение. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_fighter_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16139', 'Vesper Stormer - Thunder {PvP}', null, 'Редкий предмет, увеличивает шанс Крит. Атк..Дает возможность получить одно из следующих особых свойств: Здоровье, Наведение, Ускорение. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_stormer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16140', 'Vesper Avenger - Landslide {PvP}', null, 'Редкий предмет, усиливающий эффект оглушения при атаке.Дает возможность получить одно из следующих особых свойств: Регенерация HP, Поглощение HP, Здоровье. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_avenger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16141', 'Vesper Retributer - Gale {PvP}', null, 'Редкий предмет, увеличивающий Скор. Атк..Дает возможность получить одно из следующих особых свойств: Регенерация HP, Поглощение HP, Здоровье. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_retributer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16142', 'Vesper Caster - Cleverness {PvP}', null, 'Редкий предмет, увеличивает скорость восстановления MP.Дает возможность получить одно из следующих особых свойств: Проницательность, Регенерация MP, Увеличение Маны. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_caster_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16143', 'Vesper Singer - Hail {PvP}', null, 'Редкий предмет, увеличивающий Маг. Атк.Дает возможность получить одно из следующих особых свойств: Воодушевление, Регенерация MP, Магические Оковы. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_singer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16144', 'Vesper Thrower - Clairvoyance {PvP}', null, 'Редкий предмет, увеличивающий дальность атаки.Дает возможность получить одно из следующих особых свойств: Экономия, Крит. Замедление, Фокусировка. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_thrower_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16145', 'Vesper Pincer- Thunder {PvP}', null, 'Редкий предмет, увеличивает шанс Крит. Атк..Эксклюзивное оружие Камаэль: Конверсия Резака ВенерыДает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, Здоровье.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умения для вас и членов вашей группы. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_pincer_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16146', 'Vesper Shooter - Clairvoyance {PvP}', null, 'Редкий предмет, увеличивающий дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Броска ВенерыДает возможность получить одно из следующих особых свойств: Экономия, Крит. Замедление, Фокусировка. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_schutze_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16147', 'Vesper Nagan - Gale {PvP}', null, 'Редкий предмет, увеличивает Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Эспадона ВенерыДает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка, Здоровье. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'weapon_vesper_nagen_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16148', 'Vesper Dual Daggers - Gale', null, 'Редкий предмет, увеличивает Скор. Атк.Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше мощность Крит. Атк. увеличивается на 109. Наносит дополнительный урон в PvP. Предмет используется Кинжальщиками, достигшими 81-го уровня.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16149', 'Vesper Dual Daggers - Gale {PvP}', null, 'Редкий предмет, увеличивает Скор. Атк.Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом. Предмет используется Кинжальщиками, достигшими 81-го уровня.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16150', 'Vesper Dual Sword - Destruction', null, 'Редкий предмет, увеличивает Скор. Атк.При модификации сила атаки становится больше, чем у одноручного меча. При модификации на +4 и выше Крит. Атк. увеличивается на 109, а Макс. HP - на 10%. Наносит дополнительный урон в PvP.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16151', 'Vesper Dual Sword - Destruction {PvP}', null, 'При модификации на +4 и выше Крит. Атк. увеличивается на 109, а Макс. HP - на 10%. Наносит дополнительный урон в PvP. Во время атаки с определенным шансом снижает радиус атаки из луков/арбалетов.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16152', 'Skull Edge Dual Daggers', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 84 уровня и выше.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16153', 'Skull Edge Dual Daggers {PvP}', null, 'Парные кинжалы. Модификация увеличивает Физ. Атк. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 84 уровня и выше. Дает шанс восстановить CP, когда персонаж атакован. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16154', 'Periel Dual Sword', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%. Наносит дополнительный урон в PvP.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16155', 'Periel Dual Sword {PvP}', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%. Наносит дополнительный урон в PvP. Во время атаки с определенным шансом снижает радиус атаки из луков/арбалетов.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16156', 'Mamba Edge Dual Daggers', null, 'Парные кинжалы. При модификации Физ. Атк. усиливается больше, чем у одиночного кинжала. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 85-го уровня и выше. Наносит дополнительный урон в PvP.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16157', 'Mamba Edge Dual Daggers {PvP}', null, 'Парные кинжалы. При модификации Физ. Атк. усиливается больше, чем у одиночного кинжала. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 85 уровня и выше. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'dual_dagger_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16158', 'Eternal Core Dual Sword', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.,Наносит дополнительный урон в PvP.', 'weapon_dual_sword_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16159', 'Eternal Core Dual Sword {PvP}', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.. Наносит дополнительный урон в PvP. Во время атаки с определенным шансом снижает радиус атаки из луков/арбалетов.', 'weapon_dual_sword_i00', '7');
