INSERT INTO `ghtweb_all_items` VALUES ('16179', 'Vesper Cutter- Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк., <Свойство Кристалла Души> Дает возможность увеличить Скор. Атк. на 11%, наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'weapon_vesper_cutter_i01', '7');
