INSERT INTO `ghtweb_all_items` VALUES ('16186', 'Vesper Buster - Cleverness {PvP}', 'Acumen', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает возможность увеличить макс. MP на 15%, наносит дополнительный урон в PvP. С определенной вероятностью увеличивается Скор. Маг. при получении урона.', 'weapon_vesper_burster_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16187', 'Vesper Buster - Cleverness {PvP}', 'Magic Hold', 'Редкий предмет, увеличивает скорость восстановления MP, <Свойство Кристалла Души>Дает шанс 20% колдовства Корня Дриады, наносит дополнительный урон в PvP. С определенной вероятностью увеличивается Скор. Маг. при получении урона.', 'weapon_vesper_burster_i01', '7');
