INSERT INTO `ghtweb_all_items` VALUES ('16212', 'Vesper Pincer- Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Скор. Атк. увеличивается примерно на 11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_vesper_pincer_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16213', 'Vesper Pincer- Thunder {PvP}', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Макс. HP увеличивается на 25%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_vesper_pincer_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('16214', 'Vesper Pincer- Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивающий шанс Крит. Атк., Эксклюзивное оружие Камаэль: Конверсия Резака Венеры<Свойство Кристалла Души>Шанс Крит. Атк. увеличивается на 131. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки. При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'weapon_vesper_pincer_i01', '7');
