INSERT INTO `ghtweb_all_items` VALUES ('17062', 'Event - Scroll of Summon Baby White Tiger', null, 'Свиток, позволяющий призвать белого тигренка. Если восстановить силы тигренка, то можно получить апигу. (Восстанавливать можно только с помощью Лекарства Купидона и Сильнодействующего Лекарства Купидона). Можно обменять.', 'etc_scroll_of_tiger_a', '1');
INSERT INTO `ghtweb_all_items` VALUES ('17063', 'Event - Scroll of Summon Gloomy Baby White Tiger', null, 'Свиток, позволяющий призвать грустного белого тигренка. Если восстановить силы тигренка, то он может превратиться в белого тигра. (Восстанавливать можно только с помощью Лекарства Купидона и Сильнодействующего Лекарства Купидона). Можно обменять.', 'etc_scroll_of_tiger_a', '1');
INSERT INTO `ghtweb_all_items` VALUES ('17064', 'Event - Scroll of Summon Baby White Tiger Captain', null, 'Свиток, позволяющий призвать Белого Тигренка-Вожака. Если восстановить силы тигренка, то можно получить апигу. (Восстанавливать можно только с помощью Лекарства Купидона и Сильнодействующего Лекарства Купидона). Можно обменять.', 'etc_scroll_of_tiger_b', '1');
INSERT INTO `ghtweb_all_items` VALUES ('17065', 'Event - Scroll of Summon Gloomy Baby White Tiger Captain', null, 'Свиток, позволяющий призвать Грустного Белого Тигренка-Вожака. Если восстановить силы тигренка, то он может превратиться в Белого Тигра-Вожака. (Восстанавливать можно только с помощью Лекарства Купидона и Сильнодействующего Лекарства Купидона). Можно обменять.', 'etc_scroll_of_tiger_b', '1');
INSERT INTO `ghtweb_all_items` VALUES ('17066', 'Event - Save the White Tiger Event Pack', null, 'Ивентовая упаковка, которую можно получить один раз в 12 часов с одного аккаунта. Используйте, чтобы получить необходимые для ивента предметы : Свиток Призыва Белого Тигренка, Лекарство Купидона. Нельзя обменять.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17067', 'Event - Cupid\'s Fatigue Relief Potion', null, 'Восстанавливает силы белого тигренка.', 'etc_faitgue_relief_of_cupid_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('17068', 'Event - Cupid\'s Powerful Fatigue Relief Potion', null, 'Восстанавливает силы белого тигренка эффективнее, чем Лекарство Купидона.', 'etc_nutrients_of_cupid_i00', '24');
