INSERT INTO `ghtweb_all_items` VALUES ('17087', 'Twin Coba Seed', null, 'Семя Двойной Кобы. Для получения плода вживите его в монстра в районе Орена. Наилучшего результата можно достичь, если персонаж и монстр 77-87 уровней.', 'etc_twin_coba_seed_i00', '10');
