INSERT INTO `ghtweb_all_items` VALUES ('17093', 'Vitality Maintaining Potion (10 mintues) (Event)', null, 'Поддерживает уровень энергии в течение 10 минут. Время повторного использования: 30 мин. Нельзя обменять, выбросить и уничтожить.', 'etc_lesser_potion_blue_i00', '3');
