INSERT INTO `ghtweb_all_items` VALUES ('17186', 'National Representative Warrior\'s Ring', '3-day limited period', 'Кольцо Национального Героя. Можно использовать в течение 3 дней. Эффекты: МР +21, увеличение Точности, увеличение силы Крит. Атк., увеличение сопротивления Удержанию на 30%, увеличение шанса Удержания на 30%. При надевании двух колец эффекты не суммируются. Нельзя обменять/выбросить.', 'accessory_ring_of_hero_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17187', 'National Representative Warrior\'s Necklace', '3-day limited period', 'Ожерелье Национального Героя. Можно использовать в течение 3 дней. Эффекты: МР + 42, увеличение сопротивления к Параличу/Усыплению/Оглушению на 15%, увеличение шанса Паралича/Усыпления/Оглушения цели на 15%, уменьшение времени перезарядки умений. Отражает часть урона. Нельзя обменять/выбросить.', 'accessory_necklace_of_hero_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17188', 'National Representative Warrior\'s Earring', '3-day limited period', 'Серьга Национального Героя. Можно использовать в течение 3 дней. Эффекты: MP +31, эффект Ярости Вампира, увеличение сопротивления Оглушению и Отрицательным Эффектам на 20%, увеличение шанса Оглушения цели и наложения на нее Отрицательных Эффектов на 20%. Нельзя обменять/выбросить. При надевании двух серег эффекты не суммируются.', 'accessory_earring_of_hero_i00', '0');
