INSERT INTO `ghtweb_all_items` VALUES ('17201', 'Proof of Cheers', null, 'Знак, необходимый для умения \"Воля Национального Героя\", \"Заклинание Благословения\", \"Энергия Победы\". Нельзя обменять/выбросить.', 'BranchSys2.br_cheer_symbol_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17202', 'Proof of Cheers 10 Pack', null, 'Упаковка Знаков Болельщика, содержит 10 штук. Нельзя обменять/выбросить.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17203', 'Agathion Seal Bracelet - Ball Trapping Gnosian', null, 'Браслет для призыва Гасиона с мячом. Носит красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'BranchSys2.br_aga_kball_male_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17204', 'Agathion Seal Bracelet - Ball Trapping Orodriel', null, 'Браслет для призыва Родриэля с мячом. Носит красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'BranchSys2.br_aga_kball_female_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17205', 'Agathion Seal Bracelet - Penalty Kick', null, 'Браслет для призыва Гасиона или Родриэля, выполняющих пенальти. Носят красную униформу. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'BranchSys2.br_aga_kball_kick_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17206', 'Nevit\'s Hourglass - 1 hour', null, 'Увеличивают время действия Благословения Невитта на 1 час, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'etc_dragons_blood_i03', '3');
