INSERT INTO `ghtweb_all_items` VALUES ('17208', 'Nevit\'s Hourglass - 2 hour', null, 'Увеличивают время действия Благословения Невитта на 2 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'etc_dragons_blood_i03', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17209', 'Nevit\'s Hourglass - 2.5 hour', null, 'Увеличивают время действия Благословения Невитта на 2.5 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'etc_dragons_blood_i03', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17210', 'Nevit\'s Hourglass - 3 hour', null, 'Увеличивают время действия Благословения Невитта на 3 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'etc_dragons_blood_i03', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17211', 'Nevit\'s Hourglass - 4 hour', null, 'Увеличивают время действия Благословения Невитта на 4 часа, можно использовать на любом уровне, Нельзя обменять/выбросить.', 'etc_dragons_blood_i03', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17212', 'Nevit\'s Voice', null, 'Раковина моллюска, содержащая голос Невитта. Увеличивает кол-во рекомендаций на 10. Нельзя обменять/выбросить.', 'etc_fish_scale_i01', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17213', 'Solina\'s Biography', null, 'Книга, повествующая о жизни Солины и святой королевской семьи Эльморедена. Была запрещена лично королем, поэтому найти такую книгу - большая удача. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_old_evil_book_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17214', 'Kaerun\'s Memoir', null, 'Книга, повествующая о жизни Солины с точки зрения ее современника Каэруна. Хранилась в монастыре и никогда еще не покидала его пределы. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_spell_books_assistance_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17215', 'Kaerun\'s Memoir Part 1', null, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17216', 'Kaerun\'s Memoir Part 2', null, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17217', 'Kaerun\'s Memoir Part 3', null, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17218', 'Kaerun\'s Memoir Part 4', null, 'Часть записей Каэруна, повествующих о жизни Солины. Записи разделены на 4 части и хранятся в Монастыре Безмолвия. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_piece_of_paper_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17219', 'Eris\'s Chronicle', null, 'Записи настоятельницы Монастыря Безмолвия Элис, повествующие о последних днях жизни Солины. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_spell_books_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17220', 'Catalog Card', null, 'Записка Софии, смотрителя главной библиотеки Руны, в которой указано местонахождение обнаруженных ею книг. Можно изучить, дважды щелкнув по предмету кнопкой мыши.', 'etc_roll_of_paper_black_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17221', 'Key to the Passageway', null, 'Ключ, открывающий дверь Прохода, запечатанного Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'etc_old_key_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17222', 'Key to the Tomb', null, 'Ключ, открывающий дверь Усыпальницы в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17223', 'Key to the Library', null, 'Ключ, открывающий дверь Библиотеки в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17224', 'Key to the Warehouse', null, 'Ключ, открывающий дверь Склада в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17225', 'Key to the Armory', null, 'Ключ, открывающий дверь Оружейной в покоях Святой. Имея при себе ключ, можно входить и выходить из закрытого помещения.', 'etc_old_key_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17226', 'Elcadia\'s Mark', null, 'Магический рунный знак, необходимый для испытания Элькардии.', 'etc_fire_mantra_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17227', 'Elcadia\'s Token', null, 'Магический рунный знак, необходимый для испытания Элькардии.', 'etc_fire_rune_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17228', 'Scroll of Abstinence', null, 'Магический свиток, найденный в покоях Святой. Излучает странную энергию, хотя выглядит очень древним и ветхим.', 'etc_spell_books_element_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17229', 'Shield of Sacrifice', null, 'Щит, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'shield_shrnoens_shield_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17230', 'Sword of Holy Spirit', null, 'Меч, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'weapon_raid_sword_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17231', 'Staff of Blessing', null, 'Посох, найденный в покоях Святой. Излучает странную энергию, хотя стар и непригоден к использованию.', 'weapon_mace_of_prayer_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17232', 'Ball Trapping Gnosian Agathion Pack', null, 'Упаковка с Браслетом Гасиона с Мячом. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17233', 'Ball Trapping Orodriel Agathion Pack', null, 'Упаковка с Браслетом Родриэля с Мячом. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17234', 'Penalty Kick Agathion Pack', null, 'Упаковка с Браслетом Пенальти. Нельзя обменять, выбросить, продать. Можно положить в Личное Хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17235', 'World Cup Special Gift', null, 'Специальный подарок для празднования Чемпионата мира по футболу. При использовании можно получить разные предметы.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17236', 'Gift of Victory Box', null, 'Подарочная коробка для празднования победы. При использовании можно получить Голос и Песочные Часы Невитта.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17237', 'Luxury Gift of Victory Box', null, 'Подарочная коробка для празднования победы. При использовании можно получить Голос и Песочные Часы Невитта.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17238', 'Olympiad Match 3 Participation Certificate', null, 'Бумага, доказывающая участие в трех Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить небольшую награду.', 'mercenary_certification_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17239', 'Olympiad Match 5 Participation Certificate', null, 'Бумага, доказывающая участие в пяти Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить некоторую награду.', 'mercenary_certification_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17240', 'Olympiad Match 10 Participation Certificate', null, 'Бумага, доказывающая участие в десяти Олимпиадах. Если принести ее Управляющему Олимпиады, можно получить внушительную награду.', 'mercenary_certification_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17241', 'Olympiad Team Event Certificate', null, 'Сертификат, подтверждающий участие в пяти Командных Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Свободной и Классовой Олимпиады, можно получить внушительную награду.', 'scroll_of_verification_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17242', 'Olympiad Class-Free Battle Certificate', null, 'Сертификат, подтверждающий участие в пяти Свободных Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Командной и Классовой Олимпиады, можно получить внушительную награду.', 'scroll_of_verification_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17243', 'Olympiad Class Battle Certificate', null, 'Сертификат, подтверждающий участие в пяти Классовых Олимпиадах. Отнесите его Управляющему Олимпиады. Если собрать также Сертификаты Свободной и Командной Олимпиады, можно получить внушительную награду.', 'scroll_of_verification_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17244', 'Olympiad 2 Consecutive Wins Confirmation', null, 'Бумага, доказывающая победу в двух Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить небольшую награду.', 'etc_charm_of_courage_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17245', 'Olympiad 5 Consecutive Wins Confirmation', null, 'Бумага, доказывающая победу в пяти Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить некоторую награду.', 'etc_charm_of_courage_i02', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17246', 'Olympiad 10 Consecutive Wins Confirmation', null, 'Бумага, доказывающая победу в десяти Олимпиадах подряд. Если принести ее Управляющему Олимпиады, можно получить внушительную награду.', 'etc_charm_of_courage_i03', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17248', 'Large Dragon Bone', null, 'Позволяет призывать особых чудовищ в специальной точке Долины Драконов. Нельзя использовать, если чудовище уже находится на своем месте.', 'big_dragon_bone_summon', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17249', 'Large Dragon Skull', null, 'Останки особого чудовища из Долины Драконов. Добыв останки у семи разных драконов, отнесите их Гильмору.', 'etc_fang_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17250', 'Large Baby Dragon', null, 'Зуб особого чудовища из Долины Драконов. Возьмите зуб и отнесите его находящемуся в Долине Драконов Неприкаянному Духу.', 'etc_claw_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17251', 'Drake Lord\'s Essence', null, 'Эссенция Повелителя Дрейков. Отнесите ее Теодрику.', 'etc_crystal_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17252', 'Behemoth Leader\'s Essence', null, 'Эссенция Главы Бехимосов. Отнесите ее Теодрику.', 'etc_crystal_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17253', 'Dragon Beast\'s Essence', null, 'Эссенция Чудовищного Дракона. Отнесите ее Теодрику.', 'etc_crystal_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17254', 'Box of Theodric', null, 'Старинный ящик. Внутри что-то есть.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17255', 'Blessed Scroll: Enchant Weapon (A-Grade)', 'Event', 'Для модификации оружия Ранга A. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов и древкового оружия на 4, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов – на 5, а луков – на 8. Увеличивает Маг. Атк. всех типов оружия на 3. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'etc_blessed_scrl_of_ench_wp_a_i04', '21');
INSERT INTO `ghtweb_all_items` VALUES ('17256', 'Blessed Scroll: Enchant Armor (A-Grade)', 'Event', 'Увеличивает Физ. Защ. брони и аксессуаров ранга А на 1. При модификации на +4 и выше Физ. Защ. будет возрастать на 3. Безопасная модификация до +3 (полный доспех +4). При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0. При модификации брони до + 4 и выше НР также увеличивается в соответствии со значением модификации.', 'etc_blessed_scrl_of_ench_am_a_i04', '22');
INSERT INTO `ghtweb_all_items` VALUES ('17257', 'Blessed Scroll: Enchant Weapon (B-Grade)', 'Event', 'Для модификации оружия Ранга B. Увеличивает Физ. Атк. одноручных мечей, одноручного дробящего оружия, кинжалов и древкового оружия на 3, двуручных мечей, двуручного дробящего оружия, парных мечей и кастетов – на 4, а луков – на 6. Увеличивает Маг. Атк. всех типов оружия на 3. При модификации на +4 и выше дает дополнительные удваивающие бонусы для Физ. Атк./Маг. Атк. При неудачной модификации предмет не разбивается на кристаллы, но уровень его модификации падает до 0.', 'etc_blessed_scrl_of_ench_wp_b_i03', '21');
