INSERT INTO `ghtweb_all_items` VALUES ('17265', 'Certificate of Dawn', null, 'Доказательство принадлежности к Ордену Рассвета, выданное Францем. У жреца Уда его можно обменять на свиток, позволяющий забыть профессию, выученную на 81 уровне.', 'etc_charm_of_courage_i05', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17266', 'Will of Antharas', null, 'Один из камней, созданный Антарасом. Чтобы подчинять своей воле могущественных монстров, Антарас вживляет такие камни в их сердца, после чего постоянно за ними наблюдает.', 'etc_unholy_potion_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17267', 'Sealed Blood Crystal', null, 'Яд из крови, пролитой Антарасом, заразил окружающую зону, а кровь, которая осталась после фильтрации ее от токсинов, за долгие годы кристаллизовалась.', 'etc_powder_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17268', 'Antharas Blood Crystal', null, 'Используя силу Антараса, воскрешают всех погибших союзников. Могут использоваться только в Гнезде Антараса. Могут использоваться максимум 1 раз в час.', 'etc_fire_crystal_1_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('17269', 'Agathion Seal Bracelet - Antharas', null, 'Браслет, призывающий милого Агатиона Антараса. Нельзя обменять/выбросить.', 'pi_high_agathion_bracelet_i00', '0');
