INSERT INTO `ghtweb_all_items` VALUES ('17271', 'Agathion Seal Bracelet - Guardian of the Dawn Kallesin', null, 'Браслет, призывающий Агатиона Хранителя Рассвета Калесина. Нельзя обменять/выбросить.', 'pi_high_agathion_bracelet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17272', 'Antharas Agathion PAck', null, 'Особый подарок в ознаменование завоевания Долины Драконов. При использовании можно получить Браслет Печати Агатиона Антараса', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17273', 'Nevit\'s Messenger Kanna Agathion Pack', null, 'Особый подарок в ознаменование завершения квеста Семи Печатей. При использовании можно получить Браслет Печати Агатиона Герольда Невитта Канны.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17274', 'Guardian of the Dawn Kallesin Agathion Pack', null, 'Особый подарок в ознаменование завершения квеста Семи Печатей. При использовании можно получить Браслет Печати Агатиона Хранителя Рассвета Калесина.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17275', 'Strider Pet Exchange Coupon', null, 'Справка, подтверждающая право на получение Питомца Ездового Дракона, которую можно обменять на Питомца Ездового Дракона через Ленту Новостей.', 'etc_ticket_i00', '0');
