INSERT INTO `ghtweb_all_items` VALUES ('17278', 'Strider Pet Exchange Pack', null, 'Витаминная упаковка. Упаковка, содержащая Купон на Ездового Дракона. Нельзя обменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17279', 'Transformation Scroll: Anakim Pack', null, 'Подарочный ящик, содержащий 1 Свиток Трансформации Анаким. При использовании можно получить Свиток Трансформации в Анакима. Нельзя обменять, выбросить или уничтожить.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17280', 'Transformation Sealbook: Anakim Pack', null, 'Подарочный ящик, содержащий 1 Книгу Трансформации в Анаким. При использовании можно получить Книгу Трансформации – Анаким. Нельзя обменять, выбросить или уничтожить.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('17281', 'Delivery Box', null, 'Ящик, который попросил доставить Изаэль Серебряная Тень из Деревни Охотников. Отнесите его в Долину Драконов Торговцу Долины Китске.', 'etc_jewel_box_i00', '0');
