INSERT INTO `ghtweb_all_items` VALUES ('20393', 'Sweet Fruit Cocktail', null, 'Коктейль из редких фруктов. Выпив его, Вы получите следующие положительные эффекты: \"Легкая Походка\", \"Ускорение\", \"Ярость Вампира\", \"Могущество\", \"Щит\", \"Шепот Смерти\", \"Наведение\" и \"Благословение Тела\". Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище. Время действия: 1 ч.', 'BranchSys.br_fruit_cocktail_i00', '3');
