INSERT INTO `ghtweb_all_items` VALUES ('20515', 'Huge Fortuna Box', null, 'Дает шанс получить Священный Кристалл: Модифицировать Оружие или Древний Кристалл: Модифицировать Оружие высокого ранга. Невозможно обменять/выбросить/продать, но можно поместить в личное хранилище.', 'BranchSys.br_fortuna_box_s_i00', '0');
