INSERT INTO `ghtweb_all_items` VALUES ('20876', 'Love for All Seasons', 'Empower, Wild Magic', 'Увеличивает Маг. Атк. на 75% и шанс нанесения Крит. Атк. магией на 2. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'BranchSys.br_taiwan_newyear_food_a_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('20877', 'Happy New Year', 'Death Whisper, Focus, Guidance', 'Увеличивает мощность Крит. Атк. на 35%, шанс нанесения Крит. Атк. на 30 и точность на 4. Время действия: 1 ч.. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'BranchSys.br_taiwan_newyear_food_b_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('20878', 'Female Aniruddha', 'Shield, Magic Barrier, Blessed Shield', 'Увеличивает Физ. Защ. на 15%, Маг. Защ. на 30% и шанс блока щитом на 15. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'BranchSys.br_taiwan_newyear_food_c_i00', '0');
