INSERT INTO `ghtweb_all_items` VALUES ('20880', 'Chinese Feast', 'Clarity, Acumen, Blessed Soul', 'Снижает расход MP для умений на 20%, для магии - на 10% и для песен/танцев - на 20%. Увеличивает Скор. Маг. на 30%, Макс. MP на 35%. Время действия: 1 ч. Нельзя обменять/выбросить/продать, но можно поместить в личное хранилище.', 'BranchSys.br_taiwan_newyear_food_e_i00', '0');
