INSERT INTO `ghtweb_all_items` VALUES ('21587', '7th Anniversary Cloak - Blood Red', null, 'Сувенир к 7-й годовщине Lineage II.Плащ для настоящих героев эпохи, история которой началась вместе с началом Lineage II. Запечатанный слот для плаща открывается, и возможность надеть плащ появляется после облачения в полный комплект доспехов Династии или выше. Нельзя зачаровать, модифицировать свойства, обменять, выбросить или разрушить, но можно совместно использовать персонажам внутри аккаунта при помощи Менеджера Витаминов или положить в личное хранилище.', 'BranchSys2.Icon.7anni_cloack_i01', '0');
