INSERT INTO `ghtweb_all_items` VALUES ('21769', 'Unrefined Ore', null, 'Необработанная руда. Необходим мастеру для изготовления драгоценных камней. Можно продать в магазин за определенную сумму денег.', 'etc_stone_piece_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21770', 'Unrefined Jewel', null, 'Необработанный самоцвет. Необходим мастеру для изготовления драгоценных камней. Можно продать в магазин за определенную сумму денег.', 'etc_vacualite_noglow_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21771', 'Jewel of Dusk', null, 'Самоцвет, обработанный при помощи древних технологий. Сильно сверкает. Можно продать в магазин за определенную сумму денег.', 'BranchSys2.g_twilight_gem', '0');
