INSERT INTO `ghtweb_all_items` VALUES ('21857', 'Hero\'s Gold Chest', '90-day limited period', 'Золотой Сундук ГерояПодарочный сундук, содержащий по 1 Сундуку с Сокровищами Героя, Упаковке: Снабжение Витаминами, Упаковке: Снабжение Зельями и Упаковке: Снабжение Предметами. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_treasure_box_i08', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21858', 'Dimensional Support Pack', '90-day limited period', 'Упаковка: Снабжение Витаминами Подарочный сундук, содержащий 2 Купона Обмена на Особого Питомца, 3 Благословенных Пера, по 5 Билетов в Камалоку (в Окрестности Камалоки, в Зал Бездны и в Лабиринт Бездны) и 3 Напитка Всплеска Энергии. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21859', 'Potion Support Pack', '90-day limited period', 'Упаковка: Снабжение Зельями\\\\ nПодарочный сундук, содержащий 20 шт. Великого Быстродействующего Зелья Исцеления, 50 шт. Великого Зелья Исцеления, 5 шт. Парного Молока и 5 шт. Энергии Ростка. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21860', 'Supplies Support Pack', '90-day limited period', 'Упаковка: Снабжение Предметами Подарочный сундук, содержащий для каждого уровня по 20 тыс. Чудесных Зарядов Души и Чудесных Зарядов Духа. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21861', 'PC Cafe Energy - 1 hour', null, 'В случае использования в течение 1 часа заряжает энергией при получении Очков Опыта посредством охоты. Время ожидания повторного использования: 60 мин. Применение возможно только для уровней 1 – 75. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_pccafe_point_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21862', 'PC Cafe Energy Pack', null, 'Упаковка: Энергия PC-Клуба.Подарочный сундук, содержащий 3 шт. Энергии PC-Клуба. В случае использования с определенной вероятностью можно получить Энергию PC-Клуба с непрерывным временем, составляющим 1 – 4 часа. Применение возможно только для уровней 1 – 75. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21863', 'PC Cafe Blessing', null, 'При использовании в течение 20 минут заряжает энергией Вас и Вашу группу при получении Очков Опыта посредством охоты. Время ожидания повторного использования: 60 мин. Нельзя обменять, выбросить или уничтожить, но можно положить в личное хранилище.', 'BranchSys.br_flag_of_bookmark_i00', '3');
