INSERT INTO `ghtweb_all_items` VALUES ('21868', 'Joy of Halloween', null, 'Подарок на Хэллоуин. В случае использования можно получить 20 Свитков Призыва Верданди. Нельзя обменять/выбросить, но можно положить в личное хранилище.', 'etc_pi_gift_box_i01', '0');
