INSERT INTO `ghtweb_all_items` VALUES ('21870', 'Agathion Seal Bracelet - Neolithica', '14-day limited period', 'Браслет призыва Агатиона Сэрома. Невозможно получить новогодний подарок Агатиона Сэрома, если в инвентаре нет места или лимит веса превышен. Нельзя обменять, выбросить и уничтожить. Можно положить в личное хранилище.', 'pi_high_agathion_bracelet_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21871', 'Hero Assistance Package', null, 'Купон на получение комплекта предметов, с помощью которых можно стать храбрецом. Использовав этот купон можно получить Комплект Снаряжения (10 дн.), Упаковку Аагатиона Медвежонка (7 дн.), Зелье Мгновенного Восстановления HP, а также Браслет Парового Жука (7 дн.). Нельзя обемнять или выбросить. Можно пложить в личное хранилище.', 'etc_pi_gift_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21872', 'Fresh Herb', null, 'Любимая трава Рудольфа. Потребляется призванным Рудольфом в течение 10 минут.', 'etc_herb_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21873', 'Santa Claus\'s Treasure Box', 'Event', 'Подарочная коробка Деда Мороза. При использовании можно получить подарок от Деда Мороза.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21874', 'Medal of Glory', null, 'Предмет, при помощи которого можно повысить репутацию. Можно поменять на очки репутации у Управляющего Великой Олимпиадой(100 очков за 1 штуку).', 'etc_badge_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21875', 'Campfire Flint', null, 'При использовании с 30 ветками можно зажечь костер. За пределами мирной зоны тепло от костра помогает восстановлению HP, MP и CP. Для получения бонусного эффекта костер нужно разжигать на определенном расстоянии от города. Невозможно поменять, выбросить или уничтожить. Можно положить в личное хранилище.', 'BranchSys2.g_campfire_flint', '3');
