INSERT INTO `ghtweb_all_items` VALUES ('21899', 'Totem of Body', null, 'При использовании призывает тотем, увеличивающий на 30% скорость восстановления HP, а также уменьшающий на 80% урон, получаемый на земле. Время действия тотема: 30 мин. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 10 мин.', 'BranchSys2.totem_of_body', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21900', 'Totem of Spirit', null, 'При использовании призывает тотем, увеличивающий на 30% скорость восстановления MP. Время действия тотема: 30 мин. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 10 мин.', 'BranchSys2.totem_of_mind', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21901', 'Totem of Courage', null, 'При использовании призывает тотем, увеличивающий на 15% физическую защиту, а также снимающий страх через определенное время. Время действия тотема: 30 мин. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 10 мин.', 'BranchSys2.totem_of_bravery', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21902', 'Totem of Fortitude', null, 'При использовании призывает тотем, увеличивающий на 15% сопротивление магии, а также снимающий окаменение через определенные отрезки времени. Время действия тотема: 30 мин. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 10 мин.', 'BranchSys2.totem_of_fortitude', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21903', 'Refined Red Dragon Blood', null, 'При использовании моментально восстанавливает определенное количество HP персонажа и членов группы. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 5 мин.', 'BranchSys2.refined_red_blood_of_dragon', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21904', 'Refined Blue Dragon Blood', null, 'При использовании моментально восстанавливает определенное количество MP персонажа и членов группы. Можно использовать только в Гнезде Валакаса и Антараса. Время повторного использования: 5 мин.', 'BranchSys2.refined_blue_blood_of_dragon', '3');
INSERT INTO `ghtweb_all_items` VALUES ('21905', 'Clear Crystal', null, 'Прозрачный кристалл. Говорят, что в нем заключена энергия Дракона Земли.', 'etc_bead_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21906', 'Empty Crystal', null, 'Пустой кристалл. Говорят, что в нем заключена энергия Валакаса.', 'etc_bead_white_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21907', 'Filled Crystal (Antharas Energy)', null, 'Кристалл, содержащий энергию Дракона Земли. Необходимо отнести Теодрику.', 'etc_bead_gold_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21908', 'Filled Crystal (Valakas Energy)', null, 'Кристалл, содержащий энергию Дракона Огня. Необходимо отнести Клейну.', 'etc_bead_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21909', 'Lavasaurus Stone Fragment', null, 'Часть камня, заставляющего двигаться Лавазавра.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21910', 'Lavasaurus Head Fragment', null, 'Кусок в виде головы дракона, расположенный на голове Лавазавра.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21911', 'Lavasaurus Body Fragment', null, 'Камень, составляющий тело Лавазавра.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21912', 'Lavasaurus Horn Fragment', null, 'Кусок камня в виде рога, расположенный на голове Лавазавра.', 'etc_broken_crystal_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21913', 'Unrefined Red Dragon Blood', null, 'Неопознанная красная жидкость.', 'etc_potion_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21914', 'Unrefined Blue Dragon Blood', null, 'Неопознанная синяя жидкость.', 'etc_potion_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21915', 'Ice Candy Piece', null, 'Отнесите 50 штук Деду Морозу и получите подарок.', 'BranchSys.br_valentine_cream_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('21916', 'Super Kat the Cat Z Summon Necklace', null, 'Витаминный предметПредмет, призывающий помощника, использующего вспомогательные чары магов. Невозможно обменять/выбросить. Можно положить в личное хранилище.', 'BranchSys2.g_supercat_cat_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21917', 'Super Feline Queen Z Summon Necklace', null, 'Витаминный предметПредмет, призывающий помощника, использующего вспомогательные чары магов. Невозможно обменять/выбросить. Можно положить в личное хранилище.', 'BranchSys2.g_supercat_queen_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21918', 'Super Mew the Cat Z Summon Necklace', null, 'Витаминный предметПредмет, призывающий помощника, использующего вспомогательные чары магов. Невозможно обменять/выбросить. Можно положить в личное хранилище.', 'BranchSys2.g_supercat_mew_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21919', 'Hellblade', null, 'Меч, используемый Дарионом. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Ускорение, Фокусировка или Здоровье.', 'BranchSys2.br_wp_Caladbulg_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21920', 'Hellblade', 'Haste', '<Свойство Кристалла Души>Меч, используемый Дарионом. Наделяет использующего особой силой. Увеличивает скорость атаки на примерно 11%. Наносит дополнительный урон в PVP.', 'BranchSys2.br_wp_Caladbulg_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21921', 'Hellblade', 'Health', '<Свойство Кристалла Души>Меч, используемый Дарионом. Наделяет использующего особой силой. Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PVP.', 'BranchSys2.br_wp_Caladbulg_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21922', 'Hellblade', 'Focus', '<Свойство Кристалла Души>Меч, используемый Дарионом. Наделяет использующего особой силой. Увеличивает шанс Крит. Атк. на 131. Наносит дополнительный урон в PVP.', 'BranchSys2.br_wp_Caladbulg_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21923', 'Hellblade {PvP}', null, 'Меч, используемый Дарионом. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: ускорение, фокусировка или здоровье. Наносит дополнительный урон в PVP и при атаке с определенной вероятностью наносит дополнительный урон.', 'BranchSys2.br_wp_Caladbulg_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21924', 'Hellblade {PvP}', 'Haste', '<Свойство Кристалла Души>Меч, используемый Дарионом. Наделяет использующего особой силой. Увеличивает скорость атаки на примерно 11%. Наносит дополнительный урон в PVP и при атаке с определенной вероятностью восстанавливает CP.', 'BranchSys2.br_wp_Caladbulg_i01', '7');
