INSERT INTO `ghtweb_all_items` VALUES ('21935', 'Butcher Blades', null, 'Парные мечи, используемые Куклой. Наделяет использующего особой силой. После модификаций сила атаки увеличивается больше, чем у простых мечей. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Во время PvP увеличивается наносимый урон. Возможно применение после 81 уровня мастером кинжалов.', 'BranchSys2.br_wp_habus_knife_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('21936', 'Butcher Blades {PvP}', null, 'Парные мечи, используемые Куклой. Наделяет использующего особой силой. После модификаций сила атаки увеличивается больше, чем у простых мечей. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. При нападении с определенной вероятностью уменьшает состояния усиления противника на 1. Также уменьшает защиту щитом. Возможно применение после 81 уровня мастером кинжалов. Во время PvP увеличивается наносимый урон.', 'BranchSys2.br_wp_habus_knife_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('21937', 'Butcher Blades - Confusion', null, 'Редкий предмет, обладающий эффектом увеличения ловкостиПарные мечи, используемые Куклой. Наделяет использующего особой силой. После модификаций сила атаки увеличивается больше, чем у простых мечей. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Во время PvP увеличивается наносимый урон. Возможно применение после 81 уровня мастером кинжалов.', 'BranchSys2.br_wp_habus_knife_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('21938', 'Butcher Blades - Confusion {PvP}', null, 'Редкий предмет, обладающий эффектом увеличения ловкостиПарные мечи, используемые Куклой. Наделяет использующего особой силой. После модификаций сила атаки увеличивается больше, чем у простых мечей. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. При нападении с определенной вероятностью уменьшает состояния усиления противника на 1. Также уменьшает защиту щитом. Возможно применение после 81 уровня мастером кинжалов. Во время PvP увеличивается наносимый урон.', 'BranchSys2.br_wp_habus_knife_i00', '6');
INSERT INTO `ghtweb_all_items` VALUES ('21939', 'Claw of Destruction', null, 'Дробящее оружие, используемое Тиадой. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Регенерация HP, Поглощение HP или Здоровье.', 'BranchSys2.br_wp_tiatenon_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21940', 'Claw of Destruction', 'HP Drain', '<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Восстанавливает HP в размере 4% от нанесенного врагу физического урона при атаке с близкого расстояния. Наносит дополнительный урон в PvP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21941', 'Claw of Destruction', 'Health', '<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PvP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21942', 'Claw of Destruction', 'HP Regeneration', '<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Скорость восстановления HP увеличивается. Наносит дополнительный урон в PvP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21943', 'Claw of Destruction {PvP}', null, 'Дробящее оружие, используемое Тиадой. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Регенерация HP, Поглощение HP или Здоровье. Наносит дополнительный урон в PVP и восстанавливает с определенной вероятностью CP.', 'BranchSys2.br_wp_tiatenon_i00', '7');
