INSERT INTO `ghtweb_all_items` VALUES ('21951', 'Claw of Destruction - Landslide {PvP}', null, 'Редкий предмет, обладающий эффектом обездвиживать с определенной вероятностью при удареДробящее оружие, используемое Тиадой. Наделяет использующего особой силой. Дает возможность получить одно из следующих особых свойств: Регенерация HP, Поглощение HP или Здоровье. Наносит дополнительный урон в PVP и восстанавливает с определенной вероятностью CP.', 'BranchSys2.br_wp_tiatenon_i00', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21952', 'Claw of Destruction - Landslide {PvP}', 'HP Drain', 'Редкий предмет, обладающий эффектом обездвиживать с определенной вероятностью при ударе<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Восстанавливает HP в размере 4% от нанесенного врагу физического урона при атаке с близкого расстояния. Наносит дополнительный урон в PVP и восстанавливает с определенной вероятностью CP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21953', 'Claw of Destruction - Landslide {PvP}', 'Health', 'Редкий предмет, обладающий эффектом обездвиживать с определенной вероятностью при ударе<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Увеличивает Макс. HP на 25%. Наносит дополнительный урон в PVP и восстанавливает с определенной вероятностью CP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21954', 'Claw of Destruction - Landslide {PvP}', 'HP Regeneration', 'Редкий предмет, обладающий эффектом обездвиживать с определенной вероятностью при ударе<Свойство Кристалла Души>Дробящее оружие, используемое Тиадой. Скорость восстановления HP увеличивается. Наносит дополнительный урон в PVP и восстанавливает с определенной вероятностью CP.', 'BranchSys2.br_wp_tiatenon_i01', '7');
INSERT INTO `ghtweb_all_items` VALUES ('21955', 'Blades of Delusion', null, 'Парные мечи, используемые Аэнкинелем. Наделяет использующего особой силой. После модификаций парных мечей, как и двуручных мечей, а также кастетов, сила атаки увеличивается больше, чем у простых мечей. После 4-х модификаций критический удар дополнительно увеличивается на 109, а HP на 10%. Во время PvP увеличивается наносимый урон.', 'BranchSys2.br_wp_astarot_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('21956', 'Blades of Delusion {PvP}', null, 'Парные мечи, используемые Аэнкинелем. Наделяет использующего особой силой. После модификаций парных мечей, как и двуручных мечей, а также кастетов, сила атаки увеличивается больше, чем у простых мечей. После 4-х модификаций критический удар дополнительно увеличивается на 109, а HP на 10%. Во время PvP увеличивается наносимый урон. При использовании с определенной вероятностью уменьшает длину выстрела лука/самострела.', 'BranchSys2.br_wp_astarot_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('21957', 'Blades of Delusion - Earth', null, 'Редкий предмет, обладающий эффектом увеличения Макс. HPПарные мечи, используемые Аэнкинелем. Наделяет использующего особой силой. После модификаций парных мечей, как и двуручных мечей, а также кастетов, сила атаки увеличивается больше, чем у простых мечей. После 4-х модификаций критический удар дополнительно увеличивается на 109, а HP на 10%. Во время PvP увеличивается наносимый урон.', 'BranchSys2.br_wp_astarot_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('21958', 'Blades of Delusion - Earth {PvP}', null, 'Редкий предмет, обладающий эффектом увеличения Макс. HPПарные мечи, используемые Аэнкинелем. Наделяет использующего особой силой. После модификаций парных мечей, как и двуручных мечей, а также кастетов, сила атаки увеличивается больше, чем у простых мечей. После 4-х модификаций критический удар дополнительно увеличивается на 109, а HP на 10%. Во время PvP увеличивается наносимый урон. При использовании с определенной вероятностью уменьшает длину выстрела лука/самострела.', 'BranchSys2.br_wp_astarot_i00', '5');
