INSERT INTO `ghtweb_all_items` VALUES ('22173', 'Improved Ring of Baium', null, 'MP +21, сопротивление отравлению +40%, шанс отравить +40%, увеличение силы Крит. Атк., сопротивление удержанию +30%, шанс удержать +30%, Физ. Атк. и Маг. Атк. При надевании двух одинаковых колец эффект не суммируется', 'accessory_ring_of_baium_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22174', 'Improved Ring of Queen Ant', null, 'MP +21, сопротивление отравлению +30%, шанс отравить +30%, увеличение шанса и силы Крит. Атк., сопротивление удержанию +20%, шанс удержать +20%. При надевании двух одинаковых колец эффект не суммируется', 'accessory_ring_of_queen_ant_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22175', 'Improved Blessed Earring of Zaken', null, 'MP +37, сопротивление кровотечению +30%, шанс кровопускания +30%, усиление целительных умений +15%, эффект Ярости Вампира, сопротивление шоковым/ментальной атакам +30%, защита от Тьмы +15. При использовании двух серьг эффективна толька одна. При надевании вместе с обычной серьгой Закена эффективна только Серьга Бессмертного Закена.', 'accessory_earring_of_zaken_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22176', 'Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Кролика-Хулигана. Можно получить апиги, сняв усталость Кролика-Хулигана (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'BranchSys2.icon2.g_ev_rabbit', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22177', 'Fearless Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Бесполезного Кролика. Во время восстановления он может превратиться в Наглого Кролика (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'BranchSys2.icon2.g_ev_rabbit', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22178', 'Large Angry Bunny Lure Scroll', 'Event', 'Свиток призыва Вожака Кроликов-Хулиганов. Можно получить апиги, сняв усталость Вожака Кроликов-Хулиганов (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'BranchSys2.icon2.g_ev_rabbit_boss', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22179', 'Large Fearless Bunny Lure Scroll', 'Event', 'Свиток призыва Вожака Бесполезных Кроликов. Во время восстановления Вожака Бесполезных Кроликов может превратиться в Вожака Наглых Кроликов (восстановление возможно только при использовании Лекарства Купидона, а также Сильнодействующего Лекарства Купидона).', 'BranchSys2.icon2.g_ev_rabbit_boss', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22180', 'Bunny Anger Management Kit', 'Event', 'Ивентовая упаковка, которую можно получить один раз в 12 часов на каждый аккаунт. При двойном нажатии можно получить необходимый свиток вызова Кролика-Хулигана, а также Лекарство Купидона. Нельзя обменять/выбросить. Можно положить в личное хранилище.', 'etc_jewel_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22181', 'Bunny Pacifier Juice', 'Event', 'Снимает усталость кролика.', 'etc_faitgue_relief_of_cupid_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('22182', 'Improved Bunny Pacifier Juice', 'Event', 'Снимает усталость кролика эффективнее, чем лекарство Купидона.', 'etc_nutrients_of_cupid_i00', '24');
INSERT INTO `ghtweb_all_items` VALUES ('22183', 'Graduation Cap', null, 'Колпак Выпускника. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'accessory_graduation_cap_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22184', 'Admiral\'s Hat', null, 'Изящная шляпа, украшенная золотом. Требует 2 ячейки головных уборов. Обменять/выбросить/продать невозможно.', 'Accessary_middle_ages_i01', '0');
