INSERT INTO `ghtweb_all_items` VALUES ('22186', 'Cat the Ranger Summon Necklace Exchange Coupon', null, 'Купон на ожерелье (5 часов) призыва Кота-Рейнджера. Невозможно обменять/выбросить. Можно передавать через Менеджера Витаминов. Можно положить в личное хранилище.', 'etc_ticket_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22187', 'Birthday Present Pack', null, 'Подарок на день рождения, выдаваемый Аллегрией. При использовании можно получить 3 порции энергии радости, Торт Именинника, а также колпак. Обменять и выбросить невозможно. Можно положить в личное хранилище.', 'event_hero_treasure_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22188', 'Birthday Vitality Potion', null, 'При использовании в течение 4 часов восстанавливает энергию после получения опыта во время охоты. Обменять и выбросить невозможно. Можно положить в личное хранилище.', 'etc_potion_blue_i00', '3');
