INSERT INTO `ghtweb_all_items` VALUES ('22215', 'Angry Bunny Earring ', '30-day limited period (event)', 'MP +37, HP+250, эффект Ярости Вампира. Увеличивает Точность, уменьшает время перезарядки магических умений/ расход MP магическими умениями. Действует 30 дней. Нельзя обменять, выбросить. Можно положить в личное хранилище.', 'branchsys2.g_accessory_event_earring', '0');
