INSERT INTO `ghtweb_all_items` VALUES ('22231', 'Mysterious Blessed Spiritshot (S-Grade)', 'Event', 'Пронизывающий оружие духовный свет мгновенно и значительно увеличивает силу оружия. Можно применять с оружием Ранга S. Нельзя обменять или выбросить, но можно положить в личное хранилище.', 'etc_spell_shot_gold_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22232', 'Mysterious Soulshot Pack (S-Grade)', 'Event', 'Откройте двойным щелчком, чтобы получить 1000 Чудесных Зарядов Души (Ранг S).', 'br_cashtex.item.br_cash_pack_of_soulshot_s_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22233', 'Mysterious Blessed Spiritshot Pack (S-Grade)', 'Event', 'Откройте двойным щелчком, чтобы получить 1000 Чудесных Благословенных Зарядов Духа (Ранг S).', 'br_cashtex.item.br_cash_pack_of_blessed_spiritshot_s_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22234', 'Sweet Chocolate Box', null, 'Витаминный предметВ ящике находится Сладкий шоколад - 3 шт. и Мешок Любви на День Святого Валентина - 1 шт. Нельзя выбросить, можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22235', 'Sweet Chocolate', null, 'Витаминный предметВ течение 30 мин. восстанавливает энергию при получении опыта во время охоты. Не действует, если на персонажа наложен аналогичный эффект. Время ожидания повторного использования: 60 мин. Нельзя обменять ,выбросить. Можно положить в личное хранилище.', 'BranchSys.br_valentine_darkchoco_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('22236', 'Valentine\'s Day Love Pouch', null, 'Витаминный предметПри использовании можно получить один из следующих предметов: Свадебный Наряд -14 дней, Браслет Печати Агатиона - Чучу (14 дней), Конфета Розовой Свиньи-14 дней, Свиток: Модифицировать Головной Убор (для воина/мага). Нельзя обменять, выбросить. Можно положить в личное хранилище.', 'BranchSys.br_lucky_bag_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22237', 'Shiny Couple Ring', null, 'Витаминный предметКольцо, которое позволяет призвать друга с таким же кольцом, находящимся в одной группе. Время ожидания повторного использования: 1 час. Нельзя обменять, выбросить. Можно положить в личное хранилище.', 'accessory_shiny_couple_ring', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22238', 'Scroll: Hair Accessory - Warrior Use', null, 'Витаминный предметСвиток используется на головной убор и добавляет свойства, полезные воину. Можно положить в личное хранилище.', 'BranchSys.br_scroll_of_transformation_i00', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22239', 'Scroll: Hair Accessory - Wizard Use', null, 'Витаминный предметСвиток используется на головной убор и добавляет свойства, полезные магу. Можно положить в личное хранилище.', 'BranchSys.br_scroll_of_transformation_i00', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22240', 'Improved Rose Spirit Exchange Ticket - 5 hours', 'Event', 'Витаминный предметКупон для обмена на ожерелье (5 часов), способное призвать улучшенную фею розы. Невозможно обменять/выбросить. Можно обменять через Менеджера Витаминов. Можно положить в личное хранилище.', 'etc_ticket_red_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22241', 'Sweet Chocolate Box', 'Event', 'Витаминный предметВ ящике находится Сладкий шоколад - 3 шт. и Мешок Любви на День Святого Валентина - 1 шт. Нельзя выбросить, можно положить в личное хранилище.', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22242', 'Sweet Chocolate', 'Event', 'Витаминный предметВ течение 30 мин. восстанавливает энергию при получении опыта во время охоты. Не действует, если на персонажа наложен аналогичный эффект. Время ожидания повторного использования: 60 мин. Нельзя обменять, выбросить. Можно положить в личное хранилище.', 'BranchSys.br_valentine_darkchoco_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('22243', '(Not In Use)', 'Event', 'Не используется', 'accessory_shiny_couple_ring', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22244', 'Mysterious Soulshot (C-Grade)', null, 'Витаминный предметПронизывающий оружие свет души мгновенно наносит противнику мощный удар. Возможно применение к оружию Ранга C. Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно передать другому персонажу на аккаунте через Витаминного менеджера.', 'etc_spirit_bullet_green_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22245', 'Mysterious Soulshot (B-Grade)', null, 'Витаминный предметПронизывающий оружие свет души мгновенно наносит противнику мощный удар. Возможно применение к оружию Ранга B. Нельзя обменять или выбросить, но можно положить в личное хранилище. Можно передать другому персонажу на аккаунте через Витаминного менеджера.', 'etc_spirit_bullet_red_i00', '0');
