INSERT INTO `ghtweb_all_items` VALUES ('22254', 'Mysterious Friend Summon Bracelet', '30-day limited period', 'Витаминный предметБраслет, который позволяет призвать друга, находящегося в одной группе с Вашим персонажем и обладающего таким же браслетом. Время ожидания повторного использования: 1 час. Действует 30 дней. Нельзя обменять, выбросить. Можно положить в личное хранилище.', 'accessory_ring_of_friendship_i00', '0');
