INSERT INTO `ghtweb_all_items` VALUES ('22279', 'PC Cafe Energy - 1 hour', 'Event', 'Upon use, for 1 hour(s), energy is replenished when Exp. is acquired through hunting. Re-use time is 60 minutes. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'etc_pccafe_point_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('22280', 'PC Cafe Blessing - 1 hour', 'Event', 'When used, HP Recovery Bonus, Max MP, and Critical Atk. Rate +20%, and you can feel the effects of Prophecy of Water, Might, Haste, Empower, Acumen, Wind Walk, Vampiric Rage, Berserker Spirit, Shield, Focus, Death Whisper, Guidance, Clarity, Wild Magic, and Concentration for 1 hour. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'BranchSys.br_xmas_miracle_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('22281', 'Sujin Transformation Stick', '7-day limited period (event)', 'Stick that transforms you into the Blessed Child Sujin. The transformation ends when you de-equip the item. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse. Special skill re-use delay is 4 hour(s).', 'BranchSys2.br_blessed_taigirl_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22282', 'Sujin Transformation Stick 7-Day Pack', 'Event', 'It contains a stick that transforms you into the Blessed Child Sujin.', 'BranchSys2.br_blessed_taiboy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22283', 'Trejuo Transformation Stick', '7-day limited period (event)', 'Stick that transforms you into the Blessed Child Trejuo. The transformation ends when you de-equip the item. Cannot be exchanged, dropped, or sold. Can be stored in a private warehouse. Special skill re-use delay is 4 hour(s).', 'BranchSys2.br_blessed_taiboy_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22284', 'Trejuo Transformation Stick 7-Day Pack', 'Event', 'It contains a stick that transforms you into the Blessed Child Trejuo.', 'BranchSys2.br_blessed_taiboy_i00', '0');
