INSERT INTO `ghtweb_all_items` VALUES ('22286', 'Jewelry Box - Talisman', null, 'Jewelry box that may contain precious treasure. When used, there is a chance you can obtain a Talisman.', 'etc_treasure_box_i06', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22287', 'Agathion Seal Bracelet - Juju', '33-day limited period (event)', 'A bracelet that can summon a Juju Agathion. Requires room in the inventory and the weight limit to receive a gift from the Juju Agathion. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'high_agathion_bracelet_i01', '0');
