INSERT INTO `ghtweb_all_items` VALUES ('22290', 'Recipe: Happy Cake', 'Event', 'The recipe for a Happy Cake. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'BranchSys.br_valentine_recipe_i00', '5');
INSERT INTO `ghtweb_all_items` VALUES ('22291', 'Happy Cake', 'Event', 'A sweet but yet incomplete Happy Cake. With a little more care, you might be able to make a Decoratioin Happy Cake.', 'BranchSys.br_valentine_cake_1_i00', '0');
