INSERT INTO `ghtweb_all_items` VALUES ('22294', 'Perfect Happy Cake', 'Event', 'A complete Happy Cake. Take this along with Premium Cake Decorations to the Valentine Messenger Queen of Hearts to receive a Miracle Happy Cake.', 'BranchSys.br_valentine_cake_4_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22295', 'Miracle Happy Cake', '30-day limited period (event)', 'Valentine cake containing fresh energy that is received from the Valentine Messenger Queen of Hearts. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'BranchSys.br_valentine_cake_5_i00', '0');
