INSERT INTO `ghtweb_all_items` VALUES ('22300', 'Miracle Happy Cake - Decoration', '15-day limited period (event)', 'Take this along with a Perfect Happy Cake to the Valentine Messenger Queen of Hearts to complete a Miracle Happy Cake. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'BranchSys.br_valentine_deco_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22301', 'Sweet Chocolate Cookie', 'Event', 'When used, energy is replenished by 5000 points. Re-use time is 60 minutes. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'BranchSys.br_valentine_cookie_i00', '3');
INSERT INTO `ghtweb_all_items` VALUES ('22302', 'Antharas\'s Earring', '3-day limited period (event)', 'MP +37, resistance to Bleed +40%, Bleed attack rate +40%, increases heal amount, vampiric rage effect, resistance to Stun/Mental attacks +30%, Stun/Mental attack rate +30%, decreases MP consumption, and increases heal amount and resistance to Earth. Only one effect is applied when two of the same earrings are equipped. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'accessory_earring_of_antaras_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22303', 'Antharas\'s Earring', '7-day limited period (event)', 'MP +37, resistance to Bleed +40%, Bleed attack rate +40%, increases heal amount, vampiric rage effect, resistance to Stun/Mental attacks +30%, Stun/Mental attack rate +30%, decreases MP consumption, and increases heal amount and resistance to Earth. Only one effect is applied when two of the same earrings are equipped. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'accessory_earring_of_antaras_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22304', 'Baium\'s Ring', '3-day limited period (event)', 'MP +21, resistance to Poison +40%, Poison attack rate +40%, resistance to Hold +30%, Hold attack rate +30%, and increases Accuracy, Critical Damage, P. Atk., and Casting Spd. Only one effect is applied when two of the same ring are equipped. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'accessory_ring_of_baium_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22305', 'Baium\'s Ring', '7-day limited period (event)', 'MP +21, resistance to Poison +40%, Poison attack rate +40%, resistance to Hold +30%, Hold attack rate +30%, and increases Accuracy, Critical Damage, P. Atk., and Casting Spd. Only one effect is applied when two of the same ring are equipped.', 'accessory_ring_of_baium_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22306', 'Scroll: Enchant Weapon (S-Grade)', 'Event', 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'etc_scroll_of_enchant_weapon_i05', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22307', 'Scroll: Enchant Weapon (A-Grade)', 'Event', 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4.', 'etc_scroll_of_enchant_weapon_i04', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22308', 'Scroll: Enchant Armor (S-Grade)', 'Event', 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'etc_scroll_of_enchant_armor_i05', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22309', 'Scroll: Enchant Armor (A-Grade)', 'Event', 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value.', 'etc_scroll_of_enchant_armor_i04', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22310', 'Allegra Box', null, 'There is a chance of obtaining a high-grade transformation scroll, Blessed Scroll: Enchant Weapon, and Scroll: Enchant Weapon.', 'Branchsys2.icon2.g_alegra_box', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22311', 'Latus Box', null, 'A Divine Weapon Enchant Crystal and a high grade Ancient Weapon Enchant Crystal can be acquired at a constant rate.', 'Branchsys2.icon2.g-latus_box', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22312', 'Top-Grade Magic Pin Cloth Belt', null, 'Weight +6000. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'armor_magic_pin_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22313', 'Top-Grade Magic Pouch Cloth Belt', null, 'Inventory Slot +18. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'armor_magic_pouch_belt_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22314', 'Blessed Scroll: Enchant Weapon (S-Grade)', null, 'Increases P. Atk. by 5 for S-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 6 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 10 for bow weapons. Increases M. Atk. by 4 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_s_i05', '21');
INSERT INTO `ghtweb_all_items` VALUES ('22315', 'Blessed Scroll: Enchant Armor (S-Grade)', null, 'Increases P. Def. by 1 for S-grade armor and accessories when enchanted. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_am_s_i05', '22');
INSERT INTO `ghtweb_all_items` VALUES ('22316', 'Blessed Scroll: Enchant Weapon (A-Grade)', null, 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_a_i04', '21');
INSERT INTO `ghtweb_all_items` VALUES ('22317', 'Blessed Scroll: Enchant Weapon (B-Grade)', null, 'Increases P. Atk. by 3 for B-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 4 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 6 for bow weapons. Increases M. Atk. by 3 for all weapons. Starting at +4, P. Atk./M. Atk. increases by double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_wp_b_i03', '21');
INSERT INTO `ghtweb_all_items` VALUES ('22318', 'Blessed Scroll: Enchant Armor (A-Grade)', null, 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0.  When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_am_a_i04', '22');
INSERT INTO `ghtweb_all_items` VALUES ('22319', 'Blessed Scroll: Enchant Armor (B-Grade)', null, 'Increases P. Def. by 1 for B-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_blessed_scrl_of_ench_am_b_i03', '22');
INSERT INTO `ghtweb_all_items` VALUES ('22320', 'Scroll: Enchant Weapon (A-Grade)', null, 'Increases P. Atk. by 4 for A-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 5 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 8 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_scroll_of_enchant_weapon_i04', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22321', 'Scroll: Enchant Weapon (B-Grade)', null, 'Increases P. Atk. by 3 for B-grade one-handed sword, one-handed blunt, dagger, spear, and other weapons when enchanted. Increases P. Atk. by 4 for two-handed sword, two-handed blunt, dualsword, and two-handed combat weapon. Increases P. Atk. by 6 for bow weapons. Increases M. Atk. by 3 for all weapons. P. Atk./M. Atk. increase by double starting at +4. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_scroll_of_enchant_weapon_i03', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22322', 'Scroll: Enchant Armor (A-Grade)', null, 'Increases P. Def. by 1 for A-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_scroll_of_enchant_armor_i04', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22323', 'Scroll: Enchant Armor (B-Grade)', null, 'Increases P. Def. by 1 for B-grade armor and accessories. Increases by 3 starting from +4. It can safely be enchanted up to +3. For one-piece armor, it can safely be enchanted up to +4. When armor is enchanted above +4, HP also increases depending on the enchant value. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_scroll_of_enchant_armor_i03', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22324', 'Transformation Scroll: Ranku', null, 'Transformation scroll that transform you into Ranku for 30 minute(s). No effect if used while transformed. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_trans_4f_s_b_01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22325', 'Transformation Scroll: Zaken', null, 'Transformation scroll that transform you into Zaken for 30 minute(s). No effect if used while transformed. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_trans_4f_s_b_01', '1');
INSERT INTO `ghtweb_all_items` VALUES ('22326', 'Blue Talisman - Buff Cancel', null, 'Cancels the buffs of nearby enemies upon use. Only one effect is applies when you wear two of the same talismans. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_talisman_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22327', 'Blue Talisman - Buff Steal', null, 'Stealsthe target\'s abnormal status upon use. Only one effect is applies when you wear two of the same talismans. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_talisman_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22328', 'Territory Health Recovery Potion', null, 'Recovers HP upon use. It can only be used by characters between levels 61-75. Can only be used on the battlefield. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_super_hp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('22329', 'Territory Mana Recovery Potion', null, 'Recovers MP upon use. It can only be used by characters between levels 61-75. Can only be used on the battlefield. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_super_mp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('22330', 'Territory CP Recovery Potion', null, 'Recovers CP upon use. It can only be used by characters between levels 61-75. Can only be used on the battlefield. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'etc_super_cp_potion_i05', '24');
INSERT INTO `ghtweb_all_items` VALUES ('22331', '7th Anniversary Pack', null, 'Celebrating the Lineage II 7th anniversary, this pack contains various items that you should find useful. Cannot be exchanged or dropped. Can be destroyed.', 'BranchSys.br_four_leaf_clover_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22332', '7th Anniversary Bonus Pack', null, 'Celebrating the Lineage II 7th anniversary, this bonus pack contains various items that you should find useful. Cannot be exchanged or dropped. Can be destroyed.', 'BranchSys.br_four_leaf_clover_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22333', 'Hero\'s Treasure Chest', null, 'Chest containing an equipment set pack which can be used for 90 days. Cannot be exchanged or dropped.', 'event_hero_treasure_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22334', 'Rune of Experience Points 50%', '1 hours limited time', 'Ancient characters that bestow a mysterious ability when possessed in the inventory. Increases acquired Exp. by 50%. The remaining period decreases even while logged off. Cannot be exchanged or dropped. Can be destroyed. Can be stored in a private warehouse.', 'br_cashtex.item.br_cash_rune_of_exp_i00', '33');
INSERT INTO `ghtweb_all_items` VALUES ('22335', 'Essence of Destruction', null, 'An item filled with the essence of Shilen\'s followers that you have defeated.', 'etc_crystal_blue_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22336', 'Pathfinder\'s Reward - Relief', null, 'A gift for adventurers who have especially provided high contributions in discovering the cause of the plague.', 'etc_bead_silver_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22337', 'Extra Entrance Pass - Rim Kamaloka', null, 'Entrance pass that allows you five addtional admissions. Can cancel the limit on entry if used while a limit on entry to Rim Kamaloka exists. Can only be used once per day from outside the instant zone. After use, the effect disappears at the corresponding instant dungeon\'s reset time. Cannot be exchanged or dropped.', 'ticket_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22338', 'Extra Entrance Pass - Rim Kamaloka 1 Sheet Pack', null, 'Wrapped pack containing an entrance pass that lets you enter Rim Kamaloka.', 'etc_pi_gift_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22339', 'S84 Top-grade Weapon Chest', 'Event', 'The chest contains 1 S84 top-grade weapon. Which one could it be?', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22340', 'Elegia Armor Chest', 'Event', 'The chest contains 1 Elegia armor. Which one could it be?', 'etc_pi_gift_box_i04', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22341', 'Scroll: Enchant Weapon - C Grade', null, 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. If enchanting fails, the item will not be crystallized but the enchant value will be reset to 0. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_blessed_scrl_of_ench_wp_c_i02', '21');
INSERT INTO `ghtweb_all_items` VALUES ('22342', 'Scroll: Enchant Weapon - C Grade', null, 'When enchanted, P. Atk. increases by 3 for C-grade one-handed swords, one-handed blunts, daggers, spears, and other weapons. P. Atk. increases by 4 for two-handed swords, two-handed blunts, dualswords, and two-handed combat weapons. P. Atk. increases by 6 for bows. M. Atk. increases by 3 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_weapon_i02', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22343', 'Scroll: Enchant Armor - C Grade', null, 'When enchanted, P. Def. increases by 1 for C-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_armor_i02', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22344', 'Scroll: Enchant Weapon - D Grade', null, 'When enchanted, P. Atk. increases by 2 for D-grade one-handed swords, one-handed blunts, daggers, spears, two-handed swords, two-handed blunts, dualswords, two-handed combat weapons, and other weapons. P. Atk. increases by 4 for bows. M. Atk. increases by 2 for all weapons. Starting at +4, P. Atk. / M. Atk. bonus double. Can be exchanged, dropped, and destroyed. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_weapon_i01', '19');
INSERT INTO `ghtweb_all_items` VALUES ('22345', 'Scroll: Enchant Armor - D Grade', null, 'When enchanted, P. Def. increases by 1 for D-grade armor and accessories. Starting at +4, P. Def. increases by 3. Enchanting is safe up to +3, but one-piece body armor can be safely enchanted up to +4. Increases HP according to enchant level when armor is enchanted +4 or above. Cannot be exchanged or dropped. Can be stored in a Private Warehouse.', 'etc_scroll_of_enchant_armor_i01', '20');
INSERT INTO `ghtweb_all_items` VALUES ('22346', 'Enchantment Tool Box', null, 'A box of enchantment-related itmes. Double-click for a chance to receive an item. Cannot be exchanged or dropped.', 'etc_treasure_box_i07', '0');
INSERT INTO `ghtweb_all_items` VALUES ('22347', 'Rune of Fate', null, 'Ancient characters which bestow a mysterious ability if it is possessed in the inventory. It increases acquired XP and SP by 200%. It will be removed from the inventory on June 15, 2011 when the event ends. Cannot be exchanged, dropped, or destroyed. Can be stored in a private warehouse.', 'br_cashtex.item.br_cash_rune_of_feather_i00', '33');
INSERT INTO `ghtweb_all_items` VALUES ('24001', 'Support Power', null, 'Используется для добавления скила. Изменяет параметры персонажа. Возможно использовать только на основном классе.', 'br_cashtex.item.br_cash_lucky_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('24002', 'Seven Sing Prize', null, 'Используется для получения дополнительной награды за прохождение цепочки квестов.', 'br_cashtex.item.br_cash_lucky_box_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25001', 'Newbie Coupon', null, 'Вы можете обменять эти купоны на разные расходные материалы в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'etc_exchange_ticket_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25002', 'Bonus Coin', null, 'Используйте эту монетку для покупок в специальном магазине (для доступа к нему нажмите Alt+B и выберите раздел \"Магазин\").', 'etc_coin_of_fair_i00', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25003', 'Cooper Coin', 'Event', 'Медная монета. Используется в эвентах.', 'etc_magic_coin_blood_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25004', 'Silver Coin', 'Event', 'Серебрянная монета. Используется в эвентах. Равноценна 100 Cooper Coin.', 'etc_magic_coin_silver_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25005', 'Gold Coin', 'Event', 'Золотая монета. Используется в эвентах. Равноценна 100 Silver Coin или 10000 Cooper Coin.', 'etc_magic_coin_gold_i01', '0');
INSERT INTO `ghtweb_all_items` VALUES ('25006', 'Star of Honor', 'Event', 'Звезда за победы в эвенте TvT.', 'etc_belt_deco_i00', '0');
