INSERT INTO `ghtweb_all_items` VALUES ('25715', 'Narsil Blade*Hellblade', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.,Наносит дополнительный урон в PvP.', 'misceoh.icons.dualsword', '7');
