INSERT INTO `ghtweb_all_items` VALUES ('25766', 'Herencia Staff {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: MP Regeneration, Magic Hold, Empower. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.2hmagicblunt0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25767', 'Terakan Sword {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Acumen, Magic Hold, Mana Up. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.1hsword0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25768', 'Sylphen Bow {PvP}', null, 'Дает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.bow0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25769', 'Azerian Rapier {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Narsil BladeДает возможность получить одно из следующих особых свойств: Health, Focus, Haste. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.rapier0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25770', 'Kuhn Blade {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Mechanic SawДает возможность получить одно из следующих особых свойств: Health, Focus, Haste. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.ancientsword0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25771', 'Nexium Claw {PvP}', null, 'Эксклюзивное оружие Камаэль: Конверсия Sylphen BowДает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.crossbow0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25772', 'Phasian Dual Daggers {PvP}', null, 'Парные кинжалы. При модификации Физ. Атк. усиливается больше, чем у одиночного кинжала. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 85 уровня и выше. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'misceoh.icons.dualdagger', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25773', 'Narsil Blade*Hellblade {PvP}', null, 'У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.. Наносит дополнительный урон в PvP. Во время атаки с определенным шансом снижает радиус атаки из луков/арбалетов.', 'misceoh.icons.dualsword', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25774', 'Narsil Blade {PvP}', 'Focus', '<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.magicsword1', '7');
