INSERT INTO `ghtweb_all_items` VALUES ('25881', 'Twister Cigonia - Cleverness {PvP}', null, 'Редкий предмет, увеличивает скорость восстановления MP.Дает возможность получить одно из следующих особых свойств: MP Regeneration, Mana Up, Acumen. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.magicblunt0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25882', 'Herencia Staff - Hail {PvP}', null, 'Редкий предмет, увеличивающий Маг. Атк.Дает возможность получить одно из следующих особых свойств: MP Regeneration, Magic Hold, Empower. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.2hmagicblunt0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25883', 'Terakan Sword - Cleverness {PvP}', null, 'Редкий предмет, увеличивает скорость восстановления MPДает возможность получить одно из следующих особых свойств: Acumen, Magic Hold, Mana Up. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.1hsword0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25884', 'Sylphen Bow - Clairvoyance {PvP}', null, 'Редкий предмет, увеличивающий дальность атаки.Дает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.bow0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25885', 'Azerian Rapier - Thunder {PvP}', null, 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil BladeДает возможность получить одно из следующих особых свойств: Health, Focus, Haste. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.rapier0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25886', 'Kuhn Blade - Gale {PvP}', null, 'Редкий предмет, увеличивающий Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Mechanic SawДает возможность получить одно из следующих особых свойств: Health, Focus, Haste. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.ancientsword0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25887', 'Nexium Claw - Clairvoyance {PvP}', null, 'Редкий предмет, увеличивающий дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Sylphen BowДает возможность получить одно из следующих особых свойств: Focus, Critical Slow, Cheap Shot. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.crossbow0', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25888', 'Phasian Dual Daggers - Gale {PvP}', null, 'Редкий предмет, увеличивает Скор. Атк.Парные кинжалы. При модификации Физ. Атк. усиливается больше, чем у одиночного кинжала. При модификации на +4 и выше шанс Крит. Атк. увеличивается на 109. Используются Кинжальщиками 85 уровня и выше. Наносит дополнительный урон в PvP. Дает шанс при атаке снять с врага один и более положительных эффектов, а также снизить его Защиту Щитом.', 'misceoh.icons.dualdagger', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25889', 'Narsil Blade*Hellblade - Destruction {PvP}', null, 'Редкий предмет, увеличивает Скор. Атк.У парных мечей, двуручного меча, двуручного дробящего оружия и кастетов атака возрастет больше, чем у одноручных мечей. При модификации +4 и выше увеличивается Крит. Атк. На 109 и Макс. HP на 10%.. Наносит дополнительный урон в PvP. Во время атаки с определенным шансом снижает радиус атаки из луков/арбалетов.', 'misceoh.icons.dualsword', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25890', 'Narsil Blade - Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.magicsword1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25891', 'Narsil Blade - Thunder {PvP}', 'Haste', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'misceoh.icons.magicsword1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25892', 'Narsil Blade - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивает шанс Крит. Атк.<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.', 'misceoh.icons.magicsword1', '7');
