INSERT INTO `ghtweb_all_items` VALUES ('25923', 'Azerian Rapier - Thunder {PvP}', 'Focus', 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'misceoh.icons.rapier1', '7');
