INSERT INTO `ghtweb_all_items` VALUES ('25925', 'Azerian Rapier - Thunder {PvP}', 'Health', 'Редкий предмет, увеличивающий шанс Крит. Атк.Эксклюзивное оружие Камаэль: Конверсия Narsil Blade<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP и дает шанс восстановить CP, когда персонаж атакован.При модификации на +4 и выше при критической атаке дает шанс увеличить Физ. Атк., Маг. Атк., мощность лечения; уменьшает расход MP при использовании умений для Вас и членов Вашей группы.', 'misceoh.icons.rapier1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25926', 'Kuhn Blade - Gale {PvP}', 'Focus', 'Редкий предмет, увеличивающий Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Mechanic Saw<Свойство Кристалла Души>Шанс Крит. Атк. +134. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'misceoh.icons.ancientsword1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25927', 'Kuhn Blade - Gale {PvP}', 'Haste', 'Редкий предмет, увеличивающий Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Mechanic Saw<Свойство Кристалла Души>Скор. Атк. +11%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'misceoh.icons.ancientsword1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25928', 'Kuhn Blade - Gale {PvP}', 'Health', 'Редкий предмет, увеличивающий Скор. Атк.Эксклюзивное оружие Камаэль: Конверсия Mechanic Saw<Свойство Кристалла Души>Макс. HP +25%. Наносит дополнительный урон в PvP. При атаке дает шанс нанести дополнительный урон.', 'misceoh.icons.ancientsword1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25929', 'Nexium Claw - Clairvoyance {PvP}', 'Critical Slow', 'Редкий предмет, увеличивающий дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Sylphen Bow<Свойство Кристалла Души>Существует 24% вероятности наложения Замедления при Крит. Атк. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'misceoh.icons.crossbow1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25930', 'Nexium Claw - Clairvoyance {PvP}', 'Cheap Shot', 'Редкий предмет, увеличивающий дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Sylphen Bow<Свойство Кристалла Души>При обычной атаке дает 12% шанс уменьшить расход MP до 1.', 'misceoh.icons.crossbow1', '7');
INSERT INTO `ghtweb_all_items` VALUES ('25931', 'Nexium Claw - Clairvoyance {PvP}', 'Focus', 'Редкий предмет, увеличивающий дальность атаки.Эксклюзивное оружие Камаэль: Конверсия Sylphen Bow<Свойство Кристалла Души>Шанс Крит. Атк. +139. Наносит дополнительный урон в PvP. С некоторой вероятностью восстанавливает СР во время атаки.', 'misceoh.icons.crossbow1', '7');
